// Portal değişiklik günlüğü — ana sayfadaki "Yeni Eklenenler" ve "Son Değişiklikler" kartlarının kaynağı.
//
// Portala yeni bir rapor / ekran eklendiğinde ya da mevcut bir ekran taşındığında, güncellendiğinde veya
// kaldırıldığında buraya BİR SATIR eklenir; kartlar ve /Home/Degisiklikler sayfası bu listeden beslenir.
//   Yeni(...)        → "Yeni Eklenenler" kartı (Tur = yeni)
//   Tasima(...)      → "Son Değişiklikler" kartı (Tur = tasima): ekranın menüdeki yeri değişti
//   Guncelleme(...)  → "Son Değişiklikler" kartı (Tur = guncelleme): ekranda işlev / görünüm değişikliği
//   Kaldirma(...)    → "Son Değişiklikler" kartı (Tur = kaldirma)
// Ekran adı KurumsalMenu'daki rapor adıyla aynıysa bağlantı ve menü yolu otomatik bulunur; menüde olmayan
// ekranlar (ör. Ana Sayfa, tema) için Href / Yol elle verilir.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

namespace WebApplication3.Data
{
    public class PortalDegisiklik
    {
        public DateTime Tarih { get; set; }
        /// <summary>yeni | tasima | guncelleme | kaldirma</summary>
        public string Tur { get; set; }
        public string Ekran { get; set; }
        /// <summary>Menü yolu metni (ör. "Mali İşler › Finans › Ödeme Yönetimi").</summary>
        public string Yol { get; set; }
        public string Aciklama { get; set; }
        public string Href { get; set; }
        public string Kim { get; set; }

        public string TurAdi => Tur == "yeni" ? "Yeni" : Tur == "tasima" ? "Taşındı" : Tur == "kaldirma" ? "Kaldırıldı" : "Güncellendi";
        public string TurRenk => Tur == "yeni" ? "green" : Tur == "tasima" ? "amber" : Tur == "kaldirma" ? "red" : "blue";
        public string Modul => string.IsNullOrEmpty(Yol) ? "" : Yol.Split('›')[0].Trim();

        public string TarihMetni
        {
            get
            {
                int fark = (DateTime.Today - Tarih.Date).Days;
                if (fark == 0) return "Bugün";
                if (fark == 1) return "Dün";
                return Tarih.ToString("d MMM", PortalDegisiklikler.Tr);
            }
        }
    }

    public static class PortalDegisiklikler
    {
        internal static readonly CultureInfo Tr = new CultureInfo("tr-TR");

        private static readonly Lazy<List<PortalDegisiklik>> _liste = new Lazy<List<PortalDegisiklik>>(Olustur);
        public static List<PortalDegisiklik> Liste => _liste.Value;

        public static IEnumerable<PortalDegisiklik> YeniEklenenler => Liste.Where(x => x.Tur == "yeni").OrderByDescending(x => x.Tarih);
        public static IEnumerable<PortalDegisiklik> SonDegisiklikler => Liste.Where(x => x.Tur != "yeni").OrderByDescending(x => x.Tarih);

        // ---------- Günlük ----------
        private static List<PortalDegisiklik> Olustur()
        {
            var l = new List<PortalDegisiklik>();
            DateTime T(int gun, int ay) => new DateTime(DateTime.Today.Year, ay, gun);

            // --- Yeni eklenen rapor / ekranlar ---
            Yeni(l, T(9, 11), "Kredi Raporu", "Mali İşler › Finans › Krediler ve Finansman altında. Zamanında ödenemeyen banka kredilerinin yapılandırması tek ekranda: her kredi için YAPILANDIRMA ÖNCESİ bilgiler (banka / şube, kredi no ve türü, kullanım tarihi, anapara, faiz, vade, taksit, kalan anapara ve vade, son ödeme, geciken taksit adedi ve tutarı, gecikme faizi, masraf, önceki durum) ve YAPILANDIRMA SONRASI (yapılandırma tarihi, protokol no, yeni anapara, yeni faiz, BSMV, yeni vade, ödemesiz dönem, yeni taksit — boş bırakılırsa anüite ile hesaplanır —, ilk taksit tarihi, ödenen taksit, durum); TEMİNATLAR satır satır (ipotek: tapu bilgisi, derece, ipotek tutarı, ekspertiz, malik; kefalet, rehin, teminat mektubu, çek / senet, nakit blokaj …). Sekmeler: Krediler (öncesi ↔ sonrası karşılaştırması, aylık fark, toplam geri ödeme ve faiz), Yapılandırma Öncesi, Yapılandırma Sonrası, Teminatlar · İpotek, Taksit Takvimi (anapara / faiz / kalan, Kasa Nakit Akışı durumu), Aylık Nakit Yükü (eski taksit ↔ yeni taksit). Kutular: kredi sayısı, öncesi toplam borç, sonrası toplam geri ödeme, aylık taksit yükü öncesi → sonrası, toplam faiz, teminat ve ipotek toplamı, nakit akışındaki taksitler. Kayıtlar kalıcıdır (App_Data/kredi-yapilandirma.json). \"Nakit akışa aktar\" açıkken her taksit Kasa Nakit Akışı'na Havale / EFT satırı olarak yazılır (ödenen taksitler ÖDENDİ; yapılandırma değişince satırlar güncellenir) ve kredi Planlı Düzenli Ödemeler'e \"Kredi\" kategorisiyle kaydedilir (bütçe kalemi Kredi Faiz ve Banka Komisyonları). Dosya yokken tek örnek kayıt gösterilir; silinebilir. Excel.", "/KrediYapilandirma", "Mali İşler › Finans › Krediler ve Finansman");
            Yeni(l, T(24, 10), "Ödeme Talebi", "Talep › Yeni Talep › Ödeme Talebi (Onaylarım › Mali İşler Onayları ve Mali İşler › Finans › Ödeme Yönetimi'nde de). Birimler ödeme talebini talep motoru ekranında açar: talep eden kişiye göre cari kapsamı — satın alma satınalmacısı olduğu şirketin tedarikçileri ve temsilcisi olduğu tedarikçiler, idari işler cari kartta temsilcisi olduğu cariler (kira, temizlik, danışmanlık …), muhasebe ve finans konularına göre resmi kurumlar (vergi dairesi, SGK, gümrük) ve finansal kuruluşlar (banka, leasing, sigorta); yönetici tüm cariler. Konu listesi birime göre; açık fatura seçilince belge no, tutar, para birimi ve son ödeme otomatik dolar (Cari Mutabakat ekstresi). Türler: tedarikçi faturası, sipariş avansı, cari bakiye, vergi / SGK / resmi ödeme, kredi / kart / banka / sigorta, kira / aidat / abonelik, diğer; onay akışı türe göre (yönetici → finans, resmi ödemede finans, finansal işlemde finans + direktör, kirada direktör + finans), eşiği aşan TL tutarda direktör onayı eklenir. Kural kontrolleri: cari kapsamı, tür ↔ belge tipi ↔ cari tipi uyumu, mükerrer belge (açık talep ve nakit akışta planlı), vade uyarısı, nakit / çek yöntemi notu. Onaylanan talep Kasa Nakit Akışı › Yeni Ödeme › Departman Talepleri'ne düşer; finans \"Ekle\" deyince nakit akış satırı olur, ödeme gerçekleşince talepte Nakit Akış Durumu ve Ödeme Durumu (ödendi tarihi, dekont) görünür. Yan kartta seçilen personelin cari kapsamı; takip raporu, onay bekleyenler, timeline, ekler, audit.", "/OdemeTalebi", "Talep › Yeni Talep › Ödeme Talebi");
            Yeni(l, T(5, 10), "Vade Tarihine Göre Çek ve Senet Özeti", "Mali İşler › Finans › Finansal Araçlar altında (Yönetim › Özel Raporlar'da aynı ekran). \"Vade Tarihine Göre Tedarikçi Aylık Çek Özeti\" tablosunun uyarlaması; Beş sekme: Verilen Çekler, Verilen Senetler, Tahsile Gönderilen Çekler, Tahsile Gönderilen Senetler ve çek + senet ortak Aylık Nakit Görünümü; 12 ay tek ekranda. Şirketin verdiği tüm çekler / senetler vade ayına göre cari bazında — tedarikçi ödemeleri, maaş çekleri, kira çekleri; Ocak–Aralık tutarları, 12 aylık toplam, aylık ortalama, pay %, tür ara toplamları, verilen çek toplamı ve adedi; aynı tabloda tahsile gönderilen çekler bloğu (bankaya nakit dönüşü için ibraz edilen müşteri çekleri; yalnız Ziraat Bankası ve Halk Bankası satırları, toplam ve adet) ve NET satırı; hücreye tıklayınca carinin ya da bankaya gönderilen çeklerin listesi (çek no, müşteri, banka, keşide, vade, tutar, durum). Tahsile Gönderilen Çekler sekmesi: banka bazında aylık tablo (tahsil edildi / tahsilde / karşılıksız; portföyde ve ciro edilen durum filtresiyle), Tahsil Bankası filtresi ve banka kartları. Aylık Nakit Görünümü: ay ay verilen ↔ tahsile gönderilen, net ve kümülatif. Filtreler: şirket, vade yılı, çek türü, durum, arama; Excel.", "/CekOzet", "Mali İşler › Finans › Finansal Araçlar");
            Yeni(l, T(29, 9), "Bütçe Raporu", "Mali İşler › Finans › Bütçe ve Planlama altında. Üç gider grubu ayrı izlenir: Sabit Giderler (personel, kira, sigorta, amortisman, lisans, finansman, vergi-aidat), Tedarik Zinciri · Hammadde (hammadde, ticari mal, ambalaj, lojistik, ithalat, sarf) ve Genel Giderler (enerji, bakım, danışmanlık, hukuk, seyahat, pazarlama, ofis, iletişim, hizmet, eğitim, banka, temsil, bağış). Şirket × yıl bazında 12 aylık bütçe ve kapanmış aylar için gerçekleşen; içinde bulunulan ay geçici. Bütçe Özeti: grup bazında aylık bütçe / gerçekleşen / sapma tablosu, KPI'lar, şirket bazlı özet, en yüksek sapmalar ve revizyon günlüğü. Grup sekmelerinde alt grup ara toplamlı kalem tablosu: seçili ay ve yıl başından bugüne bütçe / gerçekleşen / sapma, yıllık bütçe, kullanım ve durum (Aşım / Hedefte / Tasarruf); satırdan aylık kırılım, şirket kırılımı ve açık aylara gerekçeli bütçe revizyonu. Filtreler: şirket, yıl, seçili ay, sapma durumu, arama; Excel. Aylık tabloda o ay vadesi gelen müşteri çekleri: vadesi gelen, ciro edilen, karşılıksız / riskli, Kullanılabilir Çek, bütçe karşılama % ve gider sonrası kalan; seçili ayın çek listesi (çek no, müşteri, banka, vade, tutar, durum).", "/Butce", "Mali İşler › Finans › Bütçe ve Planlama");
            Yeni(l, T(29, 9), "Cari Mutabakat Yönetimi", "Mali İşler › Muhasebe › Cari Mutabakat ve Mali İşler › Cari İşler › Mutabakat ve Kapama altında (aynı ekran): \"Cari Mutabakat Yönetimi — IT Geliştirme Çalışması v1.0\" uyarlaması. Müşteri, tedarikçi ve çift rollü tüm cariler tek yapıda; Aktif / Pasif sekmeleri son 12 ay (parametrik) hareket kuralıyla otomatik ayrılır (cari kart statüsünü değiştirmez). Kontrol Merkezi: şirket, cari kodu, ünvan, kart tipi, sınıf, rol, ilişki, temsilci, iletişim bilgileri durumu, güncel bakiye TL karşılığı, birden fazla döviz, bakiye yaşlandırması (en eski açık fatura), son mutabakat, son mutabakat sonrası işlem, otomatik mutabakat durumu ve duruma bağlı işlem; 12 filtre; tekil / toplu Temsilciye Gönder ve Mutabakat Gönder. İç yetkili otomatik atanır (Müşteri → satış temsilcisi, Tedarikçi → satın alma sorumlusu, Çift Rol → ikili onay). Temsilci ekranı: A. İletişim Bilgileri Kontrolü (birden fazla kişi, mutabakat yetkilisi, ana yetkili, e-posta gönder, bilgiler doğru mu) ve B. Bakiye Kontrolü (bakiye tarihi, borç / alacak / net, döviz detayı, açık fatura, çek / senet, bekleyen ödeme / tahsilat, mahsup / virman, zorunlu kontrol soruları, fark / düzeltme bildirimi); döviz bazında Ekstreyi Gör, PDF ve Excel. Kapanış Kontrolü: eşikten eski açık bakiye ve yabancı para değerleme riski otomatik işaretlenir, muhasebe kapanış seçimi + açıklama ile çözer; çözülmeden cari Gönderime Hazır olamaz. Mutabakat Durumu elle seçilmez (Henüz Başlanmadı → İç Kontrolde → Kapanış Kontrolü Gerekli / Gönderime Hazır → Gönderildi → Mutabık / İtirazlı → Yeniden Mutabakat Gerekli). Gönderim öncesi blokaj kontrolleri, mutabakat mektubu PDF önizleme, tekrar gönder, cari yanıtı işleme, itiraz çözümü, tam günlük (kim, ne zaman, önceki / yeni, durum geçişi) ve parametreler.", "/CariMutabakat", "Mali İşler › Muhasebe › Cari Mutabakat");
            Yeni(l, T(28, 9), "Müşteri Fiyat ve Kâr Oranları", "Yalnız Yönetim › Yönetim Özeti › Fiyat ve Kâr Yönetimi altında: iki katmanlı fiyatlandırma. 1) Üretici Uras Kimya'nın ürünlerini yetkili satıcılarına (Selvi Kimya, Alv Kimya, Uras Kimya GmbH) kaç % kârla sattığı — toplu (genel), ürün grubu ya da kalem kalem; en özel tanım geçerli; satıcı alış fiyatı = üretim maliyeti × (1 + oran). 2) Yetkili satıcının her müşteri carisine ürün ürün kaç % kârla sattığı — müşteri satış fiyatı = satıcı alış fiyatı × (1 + oran), liste fiyatına göre fark ve uçtan uca marj. Ürün tablosunda kalem oranı doğrudan girilir, Kaydet ile bellek içine yazılır; yalnız Yönetici yetkisi kaydedebilir, diğer roller salt okunur. Özet sekmesinde satıcı × grup ve müşteri × grup oran matrisleri ile değişiklik günlüğü (kim, ne zaman, eski → yeni); Excel fiyat listeleri.", "/FiyatYonetimi", "Yönetim › Yönetim Özeti › Fiyat ve Kâr Yönetimi");
            Guncelleme(l, T(21, 10), "Konsolide Finansal Takip Paneli", "Kasa ve Çek · Senet sekmelerine \"Satır Kaynağı · İşlem\" sütunu: her satırın hangi kayıttan geldiği rozetle görünür — Kasa Nakit Akışı (nakit ödeme / plan), Kasa Fişi (elden ödeme / tahsilat), Çek Akıbeti (portföy girişi / ciro / bankaya ibraz / teminat), Dolaşım Planı (gerçekleşen / planlı adım) — altında belge no, tarih ve kaynak ayrıntısı. Kaynağa göre yapılacak iş aynı hücrede: elden ödenmiş kasa çıkışı → \"Nakit Akışa Ekle\"; planlanmamış portföy belgesi → \"Nakit Akışa Ekle\" (tedarikçiye planla) ya da \"İbraz Et\" (plansız çıkış GMY onayına düşer); planlı belge → \"İbraz Et · Tedarikçiye Çık\" (ciro / bankaya tahsile ver, plan satırı ÖDENDİ); ibraz edilmiş, nakit akıştan gelen ya da tahsilat satırı → \"işlem gerekmez\". Altlıkta kaynak dağılımı ve ibraz edilecek planlı belge sayısı; çekmecede \"Satır Kaynağı\" satırı; arama kaynak metninde de arar. Düzen: her sütunun başlığı ve hücreleri aynı hizada (metin sol, tutar sağ, sıra / tarih / rozet orta), satırlar çizgiyle ayrıldı, tarih ve belge sütunları kesilmeden sığar. Sütun adları açıklayıcı: Kasa'da \"Cari · Ödenen / Tahsil Edilen\", Çek'te \"Kimden Geldi\" (her satırda çeki veren müşteri ve bankası) ve \"İbraz / Ciro · Kime Çıktı\" (yalnız çıkış: Ciro → tedarikçi / Bankaya İbraz → banka, tarih, belge no; çıkmamışsa \"Henüz çıkmadı · portföyde · plan → tedarikçi\") — eski \"Karşı Taraf\" sütunu ikiye ayrıldı, içerik karışmaz. Kasa ve Çek · Senet sekmelerine \"Fiş\" sütunu: hareketin muhasebe fişi numarası (nakit akış satırının fişi, kasa tediye / tahsil fişi, çek giriş fişi, ciro / ibraz fişi, dolaşım adımı fişi; plan satırlarında fiş yok). Numaraya tıklanınca pencere açılır: üstte belge detayı (çek çıkışında ibraz / ciro detayı: çıkış türü → yer, tarih, ciro bordrosu / ibraz belge no, plan satırı, dolaşım, kontrol; kasa hareketinde hareket detayı), altında yevmiye fişi başlığı ve borç / alacak satırları. Çekmecede \"Muhasebe Fişi\" satırı ve Fiş düğmesi; arama fiş numarasında da arar. Banka Hareketleri, Kasa Hareketleri ve Çek · Senet tabloları ortak başlık düzenine geçti (aynı sıra ve adlar): Sıra · Tarih · Şirket · Banka / Kasa / Belge · Vade · İşlem Türü · Karşı Taraf · Açıklama · Satır Kaynağı · İşlem · [Çek: Kimden Geldi · Planlanan Tedarikçi · İbraz / Ciro · Kime Çıktı] · Giriş (₺) · Çıkış (₺) · Nakit Akış Eşleşmesi · Kontrol · Onay · SAP · Fiş · İşlemler. Kontrol: kasa / bankada hareket tutarı ↔ nakit akış satırı (Uyumlu / Fark), çekte plan ↔ ibraz. Dövizli işlemler: tutar TL karşılığı üstte, altta döviz tutarı ve kur (kasa / banka / çek aynı düzen). Geniş tablolar kart içinde yatay kayar. İki yeni sekme: Kredi · Banka Kartı (Kasa Nakit Akışı'nda kartla ödenen / planlı satırlar: kart, taksit, ekstre dönemi; Kontrol sütunu Finekra kart ekstresi ödemesiyle eşleşme — Ekstre Ödendi / Bekleniyor; altta kart ekstre ödemeleri listesi) ve Temlik · Mahsup · Yansıtma (ödeyen şirket ≠ fatura sahibi olan ödemeler: otomatik grup içi Mahsup / Temlik belgesi, Belge Hazır / Muhasebeleşti / Belge Yok kontrolü, satırdan Mahsup ↔ Temlik tür seçimi, belgeyi aç; yöntemi Mahsup / Temlik / Yansıtma olan satırlarda bağlı modül kaydı). Durum Özeti sekmesi en sona taşındı. Satır Kaynağı · İşlem hücresinde yalnızca kaynak rozeti ve yapılacak iş (Nakit Akışa Ekle / İbraz Et / işlem gerekmez); belge no, kişi ve tarih ayrıntısı araç ipucunda ve çekmecede \"Kaynak Ayrıntısı\" alanında. Referans · No, İşlem Türü, Cari · Muhasebe Hesabı, döviz ayrıntısı ve (Çek · Senet'te) Açıklama satıra tıklayınca açılan çekmecenin Hareket kartında; Çek · Senet tablosunda Dolaşım sütunu: Kasa Nakit Akışı dolaşım planı akışı (eden → alan → …, gerçekleşen adım yeşil, planlı gri; altında kaç adım gerçekleşti ve sıradaki adım); aynı akış ve adım listesi (tür, durum, tarih, belge) çekmecenin Çek · Plan ↔ İbraz Kontrolü kartında. Kart başlıklarının sağındaki kısa bilgi notları (son akış, onay bekleyen, eşleşme kuralı vb.) kaldırıldı; bu bilgiler tablo altlığında ve Durum Özeti'nde zaten var.", "/Rapor123?sekme=cek&bas=&bit=", "Mali İşler › Finans › Konsolide Finansal Hareketler");
            Guncelleme(l, T(20, 10), "Konsolide Finansal Takip Paneli", "Kasa ve Çek · Senet sekmelerine \"Kasa Nakit Akışı Eşleşmesi\" sütunu: her satırda Kasa Nakit Akışı'nda karşılığı var mı yok mu görünür. Var → satır bağlantısı (#no, durum, makbuz / talimat); Yok → aynı hücrede \"Nakit Akışa Ekle\": kasa çıkışında Ödeme Ekle penceresi cari, kasa, tutar, tarih ve açıklamayla dolu açılır, satır ÖDENDİ nakit olarak yazılır ve hareketle eşlenir (ikinci kez listelenmez); çek / senette portföydeki belge tedarikçiye planlanır (Çek Akıbeti: Planlandı). Nakit tahsilatlar \"Tahsilat · Nakit Akış Dışı\" olarak ayrılır. Onay Durumu süzgecine \"Nakit Akışta Yok / Var\"; Durum Özeti'ne \"Nakit Akışta Olmayan Kasa Çıkışı\" ve \"Nakit Akışta Olmayan Çek · Senet\" göstergeleri (tıklayınca sekme süzülür); tablo altlığında var / yok sayıları; hareket çekmecesinde eşleşme satırı.", "/Rapor123?sekme=kasa&bas=&bit=", "Mali İşler › Finans › Konsolide Finansal Hareketler");
            Guncelleme(l, T(19, 10), "Konsolide Finansal Takip Paneli", "Üst kartlar kaldırıldı; yeni \"Durum Özeti\" sekmesi (varsayılan) panelin durumunu tablo düzeninde gösterir: iş listesi (Finekra onay bekleyen, SAP'ye işlenmemiş, nakit akışta olmayan çıkış, gecikmiş / bugün planlı / bugün ödenen ödemeler, açık talimat, nakit onayı, plana aykırı çek, planlı çekler, GMY bekleyen çıkış, gün sonu, bakiyeler — satıra tıklayınca ilgili sekme süzülür), şirket bazında durum matrisi, bugün ödenecek ve gecikmiş ödemeler (banka hareketi var mı, SAP'ye işlendi mi, talimat), vadesi gelen planlı çek / senetler ve senkron satırı. Finekra: Kasa Nakit Akışı'nda hazırlanan banka talimatı \"Bankaya İletildi\" olunca banka hareketi otomatik düşer (satırla eşleşik, talimat no ile); satırdaki \"SAP'ye İşle\" ile cari / muhasebe hesabı / belge (hangi faturaya istinaden) seçilir — eşleşmiş nakit akış satırının belgesi ya da carinin açık faturaları tutar yakınlığıyla otomatik önerilir, fiş önizlenip atılır. \"Ödeme Ekle\": gün içinde yapılmış ama nakit akışta olmayan ödeme (ya da yeni plan) Kasa Nakit Akışı'na yazılır (ödendi → ÖDENDİ + fiş; çek / senet seçilirse belge planlanır). Kasa satırından nakit akış satırı açılır; Çek sekmesinde portföydeki belge \"Nakit Akışa Gönder\" ile tedarikçiye planlanır, planlı belge \"Tedarikçiye Çık\" ile ciro edilir (nakit akış satırı ÖDENDİ, Çek Akıbeti Ciro Edildi; plansız belge GMY onayına düşer). Kasa Nakit Akışı bağlantıları satırı doğrudan açar; pencereye dönünce veri tazelenir.", "/Rapor123?sekme=ozet", "Mali İşler › Finans › Konsolide Finansal Hareketler");
            Guncelleme(l, T(19, 10), "Çek Akıbeti Raporu", "\"Durum Özeti\" paneli (araç çubuğundaki düğme; açık / kapalı durumu hatırlanır): portföy çek / senet X · R (kullanılabilir, planlı), planlı belgeler ve vadesi gelenler, nakit akıştaki çek / senet satırları, GMY onayı bekleyen plansız çıkışlar, plana aykırı çıkışlar, bankada tahsildekiler, son hareketler; Kasa Nakit Akışı ve Takip Paneli bağlantıları. Planlı belgede \"Tedarikçiye Çık\" plan satırı üzerinden ciro eder (Kasa Nakit Akışı ÖDENDİ, muhasebe fişi, akıbet Ciro Edildi). Çek detay penceresinde hızlı işlemler: portföydeki belge için \"Nakit Akışa Gönder\" (tedarikçi, planlanan tarih, belge → Kasa Nakit Akışı çek / senet satırı, belge Planlandı), planlı belge için \"Tedarikçiye Çık / Bankaya Tahsile Ver\", plansız belgede çıkış talebi (GMY onayı); nakit akış satırı ve Takip Paneli bağlantıları. Üç ekran aynı kayıt üzerinde senkron çalışır.", "/CekAkibeti", "Mali İşler › Finans › Çek Akıbeti Raporu");
            Guncelleme(l, T(19, 10), "Kasa Nakit Akışı", "Banka talimatı \"Bankaya İletildi\" (ya da doğrudan \"Gerçekleşti\") olunca her satır için Finekra banka hareketi otomatik akar ve Konsolide Finansal Takip Paneli'ne satırla eşleşik düşer; SAP kaydı (cari / fatura seçimi) orada atılır, satır ÖDENDİ olur. Takip Paneli ve Çek Akıbeti'nden gelen bağlantılar (?doc=) ilgili satırın çekmecesini doğrudan açar.", "/Rapor79?sekme=talimat", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(24, 10), "Konsolide Finansal Takip Paneli", "Kasa Nakit Akışı tasarım dilinde yeni ekran: üst kartlar (tıklanınca süzer), sekmeler (Finekra · Banka · Kasa · Çek · Nakit Akış Eşleşme · Bakiyeler · Günlük), sabit başlıklı tablolar, çekmece. Finekra sekmesi: banka hareketleri otomatik akar; Onayla ile cari / muhasebe hesabı seçilir, fiş önizlenir ve muhasebe kaydı atılır. Her hareket Kasa Nakit Akışı ile eşlenir (otomatik: tutar ± 1 ₺, tarih ± 7 gün; elle: aday seçimi); eşleşmiş satır onayla birlikte ÖDENDİ olur, fiş iki kez atılmaz; nakit akışta karşılığı olmayan çıkış \"Nakit Akışa Gönder\" ile ÖDENDİ satır olur (düğme her satırda: eşleşmiş satırı açar, çıkış ve virmanı gönderir; tahsilat ödeme planı dışında kalır; fiş onayda cari / hesap seçilince atılır). Düzenli Ödemeler sekmesi — planlı düzenli ödemeler (aylık ödeme takvim listesi, sorumlu Serkan Genç): tedarikçi, ürün / hizmet, şirket, ödeme şekli (nakit / çek), ödeme günü, ortalama aylık tutar, kategori; her ay otomatik olarak o ayın ödeme gününe planlanmış Kasa Nakit Akışı satırı açılır (panel her açılışta bu ayın eksiklerini tamamlar; aynı kayıt aynı aya iki kez akmaz; nakit satırı GMY nakit onayına düşer), \"Bu Ayı Akıt\", \"Gelecek Ayı Planla\", satır bazında akıt, yeni kayıt / düzenle / pasife al; geçen ay, bu ay ve gelecek ay akış durumu (nakit akış kaydı, planlanan, ödendi, makbuz), şirket bazında alt toplamlar ve özet kartları (aylık yük, nakit / çek, akan, ödenen, planlı, gelecek ay, şirket ve kategori dağılımı). Banka sekmesi kaldırıldı (banka hareketleri yalnız Finekra sekmesinde); Finekra tablosunda SAP sütunu (hareket SAP'ye işlenmiş mi: Var / Yok; süzgeçte SAP'ye işlenmemiş / işlenmiş) ve dövizli hareketler (USD / EUR hesaplar ya da dövizli ödemeler: TL karşılığı üstte, altta döviz tutarı · kur · kaynak; eşleşme, fiş ve toplamlar TL karşılığıyla). Bakiyeler sekmesi (ayrıntılı): üstte özet kartları (kullanılabilir banka bakiyesi, nakit kasa, çek X / R, çek + senet, X kasa, R kasa, genel toplam); kasa bakiyeleri şirket şirket nakit kasa, çek X ve R (adet · tutar · kullanılabilir · planlı), çek toplamı, senet X ve R, senet toplamı, çek + senet toplamı, X kasa toplamı (nakit + çek X + senet X), R kasa toplamı (çek R + senet R), kasa genel toplamı ve TOPLAM satırı; banka bakiyeleri SAP ↔ Finekra şirket bazında kullanılabilir banka bakiyesi alt toplamı ve genel toplam. Gün Sonu Mutabakatı sekmesi — şirket × gün: 1) Gün içi işlemler onayı — Ahmet Özkan (Finans Sorumlusu): günün kasa / banka / çek hareketleri toplu onaylanır, kalan bakiyeler kesinleşir; 2) Kalan bakiyeler otomatik: kasa (nakit), banka hesapları (Finekra günü hareketleri), çek ve senet portföyü şirket şirket X · R işlem tipine göre adet · tutar (açılış − gün içi giriş + çıkış); 3) Fiziksel sayım — Berk Berberoğlu (Kasa Sorumlusu): fiziksel çek / senet (isteğe bağlı kasa) sayımı girilir, portföy listesiyle karşılaştırılır; sistemle birebir eşleşiyorsa bakiyeler onaylanır, eksik ya da fazla belge varsa bildirim kaydedilir (tür, eksik / fazla, adet, tutar, belge no'ları); finans bildirimi çözünce yeniden sayım yapılır. Eski görünüm /Rapor123/Eski.", "/Rapor123?sekme=finekra", "Mali İşler › Finans › Konsolide Finansal Hareketler");
            Guncelleme(l, T(23, 10), "Kasa Nakit Akışı", "Ödenen Tutar sütunu: TL karşılığı üstte (ödemede baz alınan kurla), dövizli ödemede altta döviz tutarı ve kur; TL ödemede yalnız TL. Ödenen satırlar ödenme tarihine göre tablonun en altında, ödenmemişler planlanan tarihe göre üstte. Kart başlığı ve sütun başlıkları aşağı inerken sabit kalır.", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(22, 10), "Kasa Nakit Akışı", "Talimat hazırlama penceresi: seçili satırlar, dövizli satırlarda baz kur (TCMB alış / satış / efektif otomatik, fatura üstü ya da anlaşılan kur elle) satıra ve talimata yazılır; banka hesabı / kasa seçimi. Talimat seçimi: kutucuk büyütüldü, ilk hücre tıklanınca seçilir, düğme seçili sayısını gösterir. Çeki Ver / İbraz Et: muhasebe kayıtları önce simüle edilir (çıkış adımları, fişler, grup içi bakiye etkisi); grup içi işlemde onay kutusu işaretlenmeden kayıt atılmaz. Üstteki \"Çek · Senet → Çek Akıbeti\" Çek Akıbeti Raporu'na gider; planlama / ibraz sonrası rapor bağlantısı.", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(27, 10), "Müşteri Cari Kartları", "Satıra tıklayınca açılan kart detayında \"Düzenle\" düğmesi: CARİ_MASTER alanları (ünvan, vergi, bölge / ülke / şehir, sınıf, ilişki, rol / eş cari, iletişim, vade, not, şirket) ve faaliyet satırları yeni talep açmadan doğrudan düzeltilir; talep formundaki bağımlı seçimler ve §13 canlı doğrulama aynen çalışır, kart kodu ve kart tipi değişmez, durum otomatik kalır (Pasif seçimi elle pasif). Değişen alanlar kartın \"Değişiklik Geçmişi\" kartına (zaman, alan, eski → yeni, kim) yazılır. \"Güncelleme Talebi\" bağlantısı onaylı akış için duruyor. Kart detay paneli sekmeli oldu: \"Kart\" (CARİ_MASTER, kredi limiti, faaliyetler, değişiklik geçmişi), \"Yeni Talep\" (kart bilgileri yüklü güncelleme talebi formu), \"Talepler\" (bu carinin açılış / güncelleme talepleri), \"Talep Detayı\" (seçilen talebin onay süreci ve audit log'u; onay / ret / onaya gönder işlemleri panelden yapılır), \"Onay Bekleyenler\" (bu cari için bekleyenler, hızlı onay / ret) ve \"Cari Ekstre\" (Cari Ekstre raporunu bu cari koduyla yeni sekmede açar; rapor artık 120.xxx / 320.xxx kart kodlarını tanır). Değişiklik günlüğü üç yerde: kart detayında o carinin geçmişi (kart açılışı, doğrudan düzenleme, durum, kredi limiti); Müşteri Cari Kartları'nda yeni \"Değişiklikler\" sekmesi ve Müşteri Talep Formu'nda \"Değişiklikler\" sekmesi (tüm müşteri carileri; arama, kaynak / alan / kullanıcı / dönem süzgeçleri, Excel; satıra tıklayınca kart açılır).", "/CariKart/Musteri", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Müşteri Portföyü");
            Guncelleme(l, T(27, 10), "Müşteri Cari Kartları", "Cari risk ve kolay limit: kart detayında \"Cari Risk\" kartı — toplam bakiye, vadesi geçmiş (kalem, en uzun gecikme, en eski vade), vadesi gelecek, içerideki (vade bekleyen) çek / senet, ödenmemiş toplam, riskli çek, toplam cari risk ve vadesi geçmiş kalem listesi. Risk durumu OTOMATİK ve yalnız gecikmeye göre: 30 günden fazla vadesi geçmiş ödeme → Riskli; 1–30 gün gecikme → İzlemede; yoksa Risksiz (takipteki çekler bilgi olarak gösterilir ve toplam riske girer). Listede \"Risk\" sütunu (rozet + gecikme / tutar) ve \"Risk Durumu\" süzgeci; Excel'e risk sütunları. Kredi limiti kullanımı artık toplam cari riske (açık bakiye + içerideki çek / senet + riskli çek) göre hesaplanır. Limit tanımı kolaylaştı: Dinamik limitte çarpan yerine ortalamanın yüzdesi girilir (%200 = son 3 ay ortalamasının 2 katı; %100 / %150 / %200 / %300 / %400 hızlı düğmeleri, canlı önizleme), Manuel limitte tutar yazılır; tüm roller limit tanımlayabilir, değişiklik günlüğe yazılır.", "/CariKart/Musteri", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Müşteri Portföyü");
            Guncelleme(l, T(27, 10), "Tedarikçi Cari Kartları", "Cari risk: \"Cari Risk\" kartı (borç bakiyemiz, vadesi geçmiş / gelecek ödemelerimiz, verilen çek / senet, ödenmemiş toplam, toplam risk), otomatik risk durumu (30 günden fazla gecikmiş ödeme → Riskli), listede \"Risk\" sütunu ve süzgeci; limit yüzdeyle (%) ya da manuel tutarla kolayca tanımlanır.", "/CariKart/Tedarikci", "Tedarik Zinciri › Tedarikçi Yönetimi › Tedarikçi Kartları");
            Guncelleme(l, T(27, 10), "Müşteri Cari Kartları", "Sayfa sıkılaştırıldı: 14 süzgeç tek satırda (Ara biraz geniş, kalanı eşit dar sütun; dar ekranda sarar), rozetler (Limite Yakın, Riskli, sınıf / ilişki / rol etiketleri) küçüldü, liste tablosu dar hücre ve küçük yazıyla daha çok satır gösterir; üst açıklama ve kart başlıkları küçültüldü. Aynı düzen Tedarikçi Cari Kartları'nda.", "/CariKart/Musteri", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Müşteri Portföyü");
            Guncelleme(l, T(27, 10), "Cari Bilgileri", "Cari Bilgileri artık Müşteri Cari Kartları ile Tedarikçi Cari Kartları'nın BİRLEŞİK görünümüdür (aynı CARİ_MASTER verisi, süzgeçler, Düzenle, kredi limiti, risk, değişiklik günlüğü, Özetler ve Değişiklikler sekmeleri; listede Tip sütunu, Cari Kart Tipi süzgeci Tümü; iki ayrı Yeni Talep düğmesi). \"Muhatap (Cari) Ana Verileri\" ekranı kaldırıldı; eski adresi Cari Bilgileri'ne yönlenir. Adres satırıyla ön süzgeç: ?tip=&bolge=&sinif=&risk=&limit=&ara=&kod=.", "/Rapor120", "Muhasebe › Cari İşler › Cari Hesap Yönetimi");
            Guncelleme(l, T(29, 10), "Planlı Ödemeler", "Ekran sekmelere ayrıldı: \"Planlı Ödeme Listesi\" (varsayılan), \"Özet\" (aylık yük, nakit / çek, bu ay akan · ödenen · planlı, gelecek ay, çek planı toplamı, çek karşılama, şirket ve kategori dağılımı tabloları), \"Çek Planı Matrisi\" ve \"Bu Ayın Ödeme Takvimi\"; süzgeçler ve düğmeler üstte tüm sekmeler için ortak; ekran her zaman Planlı Ödeme Listesi ile açılır.", "/PlanliOdemeler", "Mali İşler › Finans › Ödeme Yönetimi");
            Guncelleme(l, T(29, 10), "Kasa Nakit Akışı Görünüm", "Ekran \"Ödeme Takibim\" olarak sıfırdan: Kasa Nakit Akışı'nı herkes görmez — satın almacılar ve ödeme talebi açan kişiler yalnız KENDİ ödemelerinin sürecini izler (talep eden ya da satınalmacısı olduğu nakit akış satırları + Ödeme Talebi modülünden gelenler). Süreç şeridi her satırda: Talep → Onay → Nakit Akışa Planlandı → Banka Talimatı / Çek · Senet / Nakit Onayı → Ödendi → Dekont · Makbuz; sıradaki adım, geciken, planlanan tarih, yöntem, talimat / çek no. Sekmeler: Bekleyen Ödemelerim, Ödenenler, Ödeme Taleplerim; kişisel özet kutuları (bekleyen, geciken, bu hafta, onay bekleyen, son 30 gün ödenen, taleplerim). Satıra tıklayınca süreç zaman çizelgesi, ödeme bilgileri, çek / senet akıbeti (imzalı ibraz belgesi), ekler (dekont, makbuz, ciro bordrosu) ve günlük. Kasa / banka bakiyeleri ve başkalarının ödemeleri görünmez; başka satır açılamaz. Örnekte görünüm kişisi seçilebilir.", "/Rapor130", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(29, 10), "Konsolide Finansal Takip Paneli", "Çek ibraz süreci uçtan uca: Çek sekmesinde planlı belgeye tıklayınca \"İbraz Et · Tedarikçiye Çık\" penceresinde \"Ciro Bordrosu / İbraz Belgesi PDF Oluştur\" (belge bilgileri, planlanan tedarikçi, nakit akış satırı, dolaşım, teslim eden / teslim alan imza alanları; belge no çıkışta üretilecek numarayla aynı), tedarikçiye imzalatılır, imzalı nüsha aynı pencereden çıkışla birlikte ya da sonra \"İmzalı Belgeyi Yükle\" ile yüklenir (çıkmamış planlı belgede yüklerken çıkış da işlenebilir). Satırda ve çekmecede ibraz süreci şeridi (Planlandı → İbraz Belgesi → Tedarikçiye Çıkış → İmzalı Belge Yüklendi), imzalı belge bağlantısı. Yüklenen belge Çek Akıbeti Raporu (İbraz Belge No yanında simge, detayda satır), Çek Ekstre Raporu (Görüntüle, serüven, Dosya Yükle) ve Kasa Nakit Akışı satır eklerinde (Ciro Bordrosu) aynı kayıt olarak görünür; çekmeceden Çek Ekstre bağlantısı.", "/Rapor123?sekme=cek", "Mali İşler › Finans › Konsolide Finansal Hareketler");
            Guncelleme(l, T(29, 10), "Çek Ekstre Raporu", "Rapor Çek Akıbeti kaydına bağlandı: belge listesi ve seçilen belgenin hareketleri (portföye giriş, planlandı, ciro / ibraz, tahsil, dolaşım adımları) Çek Akıbeti günlüğünden gelir; ana kart (tutar, kimden geldi, keşideci, banka, vade, güncel konum), \"serüven\" zaman çizelgesi, Kasa Nakit Akışı planı; imzalı ibraz belgesi varsa \"Görüntüle\", yoksa uyarı ve \"Dosya Yükle\" ile yükleme (Takip Paneli ile aynı kayıt). Takip Paneli çekmecesinden ve Çek Akıbeti'nden bağlantı.", "/Rapor60", "Mali İşler › Finans › Finansal Araçlar");
            Guncelleme(l, T(29, 10), "Planlı Ödemeler", "Her düzenli ödeme için AY BAZINDA ÇEK PLANI: portföydeki müşteri çeklerinden / senetlerinden ödeme gününe uygun vadeli olanlar seçilir (vade uygunluğu: Uygun · Sınırda · Vade Geç; \"Otomatik Seç\" ihtiyacı karşılayacak en yakın vadelileri seçer; tüm grup portföyleri, arama, şirket süzgeci). Kullanım: ödeme nakit / havale olsa bile (ör. maaş) çek BANKAYA TAHSİL için planlanır (Çek Akıbeti: Planlandı · Tahsil → …; çek tahsil edilince ödeme bankadan yapılır); ödeme şekli çek olan kayıtlarda çek TEDARİKÇİYE CİRO için o ayın Kasa Nakit Akışı satırına bağlanır (satır yoksa açılır). Listede \"Çek Planı\" sütunu (hangi aya kadar, kaç ay, ne kadar, tam karşılanan son ay), özet kutularında toplam çek planı ve bu ay / gelecek ay çek karşılama, \"Çek Planı Matrisi\" (kayıt × önümüzdeki 6 / 9 / 12 ay: planlanan / ihtiyaç, tam · kısmi · yok; hücreden çek seçimi), çekmecede ay ay tablo (ödeme günü, ihtiyaç, nakit akış satırı, planlanan belgeler, karşılama; ✕ ile plandan çıkarma). Kayıtlar bütçe kalemine eşlenir (kategori / hizmete göre otomatik öneri, formda değiştirilir) ve Bütçe Raporu'na otomatik gelir. Takip Paneli › Düzenli Ödemeler'de de Çek Planı sütunu.", "/PlanliOdemeler", "Mali İşler › Finans › Ödeme Yönetimi");
            Guncelleme(l, T(29, 10), "Bütçe Raporu", "Planlı düzenli ödemeler bütçeye OTOMATİK gelir: her düzenli ödeme kaydı bir bütçe kalemine eşlenir (elektrik → Elektrik, catering → Yemek ve Personel Servisi, güvenlik / temizlik → Temizlik ve Güvenlik Hizmetleri, ambalaj / palet → Ambalaj Malzemeleri, bulut → Yazılım Lisans …). Yeni \"Düzenli Ödemeler\" sekmesi: kalem bazında düzenli ödeme planı (açık aylarda aylık tutar, akmış aylarda nakit akış satırı) ↔ kalem bütçesi (pay %), ödenen (Kasa Nakit Akışı ÖDENDİ), kayıt listesi (kalem eşlemesi, çek planı özeti). Bütçe Özeti aylık tablosuna \"Düzenli Ödemeler · Otomatik\" bloğu (plan, ödenen, toplam gider bütçesi içindeki pay); gider grubu sekmelerinde kalem altında düzenli ödeme notu; kalem detayında düzenli ödeme kayıtları ve aylık katkı tablosu.", "/Butce?sekme=duzenli", "Mali İşler › Finans › Bütçe ve Planlama");
            Guncelleme(l, T(29, 10), "Planlı Ödemeler", "Ekran sıfırdan, Konsolide Finansal Takip Paneli › Düzenli Ödemeler sekmesiyle AYNI liste ve AYNI tasarımla kuruldu (tek veri: aylık ödeme takvim listesi — tedarikçi, ürün / hizmet, şirket, ödeme şekli, ödeme günü, ortalama aylık tutar, kategori; her ay otomatik Kasa Nakit Akışı satırı). Özet kutuları (aylık yük, nakit / çek, bu ay akan · ödenen · planlı, gelecek ay, şirket ve kategori dağılımı), şirket alt toplamlı liste (geçen ay · bu ay · gelecek ay nakit akış satırı ve durumu), Bu Ayı Akıt / Gelecek Ayı Planla / satır akıt, yeni kayıt / düzenle / pasife al, çekmecede kayıt + akan aylar + günlük; ek olarak Bu Ayın Ödeme Takvimi (gün bazında kartlar), şirket / durum / kategori / ödeme şekli / arama süzgeçleri ve Excel. Burada ya da panelde yapılan her değişiklik iki ekranda da anında görünür; panelde \"Planlı Ödemeler Ekranı\" bağlantısı. Eski hatırlatma e-postası / taksit planı ekranı kaldırıldı.", "/PlanliOdemeler", "Mali İşler › Finans › Ödeme Yönetimi");
            Guncelleme(l, T(29, 10), "Yapılan Ödemeler", "\"Yeni Ödeme Ekle\" sekmesi: Cari İşler › Tahsilat mantığının tersi — ödemeyi biz yapıyoruz. Tedarikçi seçilir (kod / ad arama + liste; bakiye, son ödememiz, son alış faturası, ortalama gecikme, açık alış faturaları); bir ödemede birden çok ödeme satırı (havale + nakit + çek + senet + kart), satır kuru TCMB'den otomatik ya da elle; açık ALIŞ faturaları Otomatik (FIFO) ya da Manuel seçilir, kapanış simülasyonu canlı (gün, vade farkı, kur farkı, tedarikçiye avans). \"Kaydet ve İşle\": cari hesabına borç olarak işlenir, her satır şirketin Kasa Nakit Akışı'na ÖDENDİ satır olarak düşer (dekont / makbuz no, banka hesabı, kapatılan fatura), Ödeme Listesi'nde \"Ödeme Ekranı\" kaynağıyla görünür (Şirket Bazlı / Konsolide raporlara girer) ve Konsolide Finansal Takip Paneli'ne çıkış olarak düşer. \"Taslak Kaydet\": işlenmez; Kayıtlı Ödemeler sekmesinden \"İşleme Al\" (çek teslim edilince vb.). Ekstre PDF / Excel, simülasyon PDF / Excel, ödeme makbuzu PDF / Excel, Otomatik Kapat; tedarikçi kartı, takip raporu, adat, Kasa Nakit Akışı bağlantıları. Tedarikçi Fatura ve Ödeme Takip detayına \"Ödeme Yap\" düğmesi; Adat Hesaplama'dan tedarikçi aktarımı taslak ödeme olur.", "/YapilanOdemeler?sekme=yeni", "Mali İşler › Finans › Ödeme Yönetimi");
            Yeni(l, T(28, 10), "Sigorta ve Kasko Poliçe Takibi", "Tüm grup şirketlerinin sigorta ve kasko poliçeleri tek listede (Yönetim › Şirket Dökümanları › Sigorta; İdari İşler › Araç ve Seyahat kısayolu): kasko, trafik, iş yeri, DASK, nakliyat, sorumluluk, makine kırılması, alacak, çevre, grup sağlık, ferdi kaza. Poliçe detayları ve teminatlar, POLİÇE PDF YÜKLEME (zeyil, dekont), 12 AYLIK TAKSİT TAKVİMİ (poliçe × ay ızgarası; hücreden taksit ödeme, dekont; geciken kırmızı, bu hafta mavi), araç poliçeleri (plaka × kasko / trafik; Araç Bakım ile bağlı), yenileme takvimi (45 gün kala uyarı; Yenile ile yeni dönem poliçesi ve taksit planı), hasar kayıtları, iptal, günlük; tür / şirket / sigortacı özeti, 12 ay taksit yükü, Excel.", "/Sigorta", "İK ve İdari İşler › İdari İşler › Sigorta");
            Yeni(l, T(28, 10), "Araç Bakım ve Onarım Takibi", "Tüm grup araçlarının (14 araç; Uras Kimya, Alv Kimya, Alv Filo, Uras Holding, Selvi Kimya, DRN) bakım ve onarım kayıtları (İK ve İdari İşler › Araç ve Seyahat kısayolu; Yönetim › Şirket Dökümanları › Araç, Taşınmaz): periyodik bakım, arıza, kaza onarımı, lastik, akü, fren, klima, kaporta, muayene. Her kayıtta SERVİS DETAYI (yetkili / özel servis, şehir, giriş-çıkış, km), parça ve işçilik kalemleri, KDV, fatura, ödeme, garanti, sonraki bakım (km / tarih), servis fişi ve fatura PDF yükleme; süreç Planlandı → Serviste → Tamamlandı → Faturalandı. Araçlar sekmesi: sonraki bakıma kalan km / gün, muayene, kasko / trafik bitişi, yıl ve toplam maliyet, km başına maliyet; araç dosyası (geçmiş, km / zimmet güncelleme, poliçeler, PDF). Bakım Takvimi (planlı servisler, yaklaşan bakım / muayene / sigorta), Maliyet Analizi (araç × ay, tür), Excel.", "/AracBakim", "İK ve İdari İşler › İdari İşler › Araç, Taşınmaz ve Demirbaş");
            Yeni(l, T(28, 10), "Tüm Şirket Dökümanları", "Yönetim › Şirket Dökümanları: tüm grup şirketlerinin (Uras Baskı Teknolojileri, Uras Kimya, Alv Kimya, Selvi Kimya, Uras Holding, Avrupa Paper, Alv Filo, URS Makine, DRN) resmî belgeleri tek yerde. Kırılımlar menüde ayrı rapor: Kuruluş ve Sicil · Vergi ve Mali · İmza ve Yetki · Ruhsat, İzin ve Sertifika · Sözleşmeler ve Kiralar · Sigorta · Banka ve Finans · Marka ve Tescil · Araç, Taşınmaz ve Demirbaş. Her kırılımda belge türleri tanımlı (zorunlu mu, geçerlilik süresi, düzenleyen kurum, hangi şirketlerde). Sekmeler: Belgeler (şirket bazında liste), Şirket × Kategori matrisi, Yenileme Takvimi (60 gün içinde dolacak sarı, dolan kırmızı), Eksik Belgeler (zorunlu olup bulunmayan; Ekle ile form dolu açılır), Şirketler (künye: ünvan, VKN, sicil, MERSİS + Şirket Dosyası PDF), Yeni Belge (dosya yükleme), Günlük. Çekmece: belge bilgileri, yenile (yeni geçerlilik), sürümler (aç / yeni sürüm yükle), arşiv, günlük; dosyası yüklenmemiş örnek belgeler için kapak sayfası PDF'i. Excel.", "/SirketDokuman", "Yönetim › Şirket Dökümanları › Genel Bakış");
            foreach (var (ad, url) in new[] { ("Şirket Künyeleri ve Dosyaları", "/SirketDokuman/Sirketler"), ("Belge Yenileme Takvimi", "/SirketDokuman/Takvim"), ("Eksik Belgeler", "/SirketDokuman/Eksik"), ("Kuruluş ve Sicil Belgeleri", "/SirketDokuman/Kurulus"), ("Vergi ve Mali Belgeler", "/SirketDokuman/Vergi"), ("İmza ve Yetki Belgeleri", "/SirketDokuman/Imza"), ("Ruhsat, İzin ve Sertifikalar", "/SirketDokuman/Ruhsat"), ("Sözleşmeler ve Kiralar", "/SirketDokuman/Sozlesme"), ("Banka ve Finans Belgeleri", "/SirketDokuman/Banka"), ("Marka, Patent ve Tescil Belgeleri", "/SirketDokuman/Marka") })
                Yeni(l, T(28, 10), ad, "Şirket Dökümanları kırılımı: aynı ekran bu kategoriye / görünüme süzülmüş açılır (tüm şirketler).", url, "Yönetim › Şirket Dökümanları");
            Yeni(l, T(28, 10), "Sigorta Poliçeleri", "Şirket Dökümanları › Sigorta kırılımı (tüm şirketlerin poliçe belgeleri); menüde İK ve İdari İşler › İdari İşler › Sigorta altında, Sigorta ve Kasko Poliçe Takibi'nin yanında.", "/SirketDokuman/Sigorta", "İK ve İdari İşler › İdari İşler › Sigorta");
            Yeni(l, T(28, 10), "Araç, Taşınmaz ve Demirbaş Belgeleri", "Şirket Dökümanları › Araç, Taşınmaz ve Demirbaş kırılımı (tapu, yapı kullanma, araç ruhsat ve muayene belgeleri); menüde İK ve İdari İşler › İdari İşler › Araç, Taşınmaz ve Demirbaş altında, Araç Bakım ve Onarım Takibi'nin yanında.", "/SirketDokuman/Varlik", "İK ve İdari İşler › İdari İşler › Araç, Taşınmaz ve Demirbaş");
            Guncelleme(l, T(28, 10), "Yurtdışı Satış Siparişi", "Marka sütununun yanına \"Fatura Kesen · Gönderici\" sütunu eklendi: faturayı kesen grup şirketi ve malı sevk eden şirket (depo / fabrika) her siparişte ayrı seçilir (Selvi Kimya, Uras Kimya, Alv Kimya, Avrupa Paper, Daf Kimya); süzgeç, çekmecede değiştirme, yeni sipariş formunda seçim (marka seçilince gönderici ve yükleme yeri önerilir), Excel'de sütunlar. Belgelerde fatura kesen \"Seller\", gönderici \"Shipper\" satırında ünvan, adres ve VKN ile çıkar.", "/Rapor94/Ihracat", "Satış ve Operasyon › Yurtdışı Satış › İhracat Satış İşlemleri");
            Guncelleme(l, T(28, 10), "Yurtiçi Satış Siparişi", "Marka sütununun yanına \"Fatura Kesen · Gönderici\" sütunu eklendi; fatura kesen ve gönderici şirket siparişte ayrı seçilir, süzülür, çekmecede değiştirilir ve belgelerde Satıcı / Gönderici satırında çıkar.", "/Rapor94/Index", "Satış ve Operasyon › Yurtiçi Satış › Satış İşlemleri");
            Yeni(l, T(28, 10), "Yurtdışı Satış Siparişi", "İhracat siparişleri ayrı ekranda (Satış ve Operasyon › Yurtdışı Satış › İhracat Satış İşlemleri). Satış Selvi Kimya'dan; MARKA basitçe seçilir (URAS · ALV KİMYA · INKNOVATORS · SELVİ) ve belgeler o markanın adı, ünvanı ve adresiyle TEK TUŞLA üretilir: Proforma Invoice, Commercial Invoice, Packing List ve hepsi tek PDF \"İhracat Belge Seti\" (belge numaraları sipariş kaydına yazılır; marka değişirse eski belgeler işaretlenir). Satışçılardan gelen SİPARİŞ TALEPLERİ \"Sipariş Talepleri\" sekmesine düşer; \"Siparişe Dönüştür\" ile yükleme tarihi / saati ve marka kesinleşir, numara verilir. Her siparişte YÜKLEME TARİHİ VE SAATİ, yükleme yeri, nakliye ve firma planlanır; satışçılar süreci (Talep → Sipariş → Hazırlanıyor → Yüklemeye Hazır → Yüklendi → Faturalandı) listedeki süreç şeridinden ve Yükleme Takvimi'nden izler (geciken kırmızı). Yeni Sipariş / Talep formunda kalem fiyatları müşterinin özel fiyatından (Muhataplar İçin Özel Fiyatlar) otomatik gelir; GTİP / HS, koli, brüt kg hesaplanır. Marka ve temsilci özeti, Excel.", "/Rapor94/Ihracat", "Satış ve Operasyon › Yurtdışı Satış › İhracat Satış İşlemleri");
            Guncelleme(l, T(28, 10), "Yurtiçi Satış Siparişi", "\"Satış Siparişi\" ekranı sıfırdan ve ikiye ayrıldı: Yurtiçi Satış Siparişi (bu ekran) ve Yurtdışı Satış Siparişi (İhracat). Marka seçimi (URAS · ALV KİMYA · INKNOVATORS · SELVİ), tek tuşla Sipariş Formu / Proforma Fatura (seçili markanın adıyla), satışçı sipariş taleplerinin siparişe dönüştürülmesi, yükleme tarihi / saati / yeri / nakliye planı, süreç şeridi (Sipariş → Hazırlanıyor → Yüklemeye Hazır → Yüklendi → Faturalandı), Yükleme Takvimi, kalem fiyatlarının özel fiyattan otomatik gelmesi, marka / temsilci özeti, Excel.", "/Rapor94/Index", "Satış ve Operasyon › Yurtiçi Satış › Satış İşlemleri");
            Guncelleme(l, T(28, 10), "Muhataplar İçin Özel Fiyatlar", "Ekran sıfırdan (eski adı \"Muhattaplar İçn Özel Fiyatlar\"): her müşteri için TÜM ürünlerde satış fiyatı. Satıcı şirket + müşteri seçilir; tüm ürünler tek tabloda — Min Fiyat Listesi (satıcı alış fiyatı × 1,05), Liste Fiyatı, son satış (tarih, miktar), son 12 ay miktarı, mevcut özel fiyat, düzenlenebilir Yeni Fiyat, min üstü %, ₺ karşılığı (fiyatlandırma kuru), kaynak, geçerlilik, durum. TOPLU FİYAT: daha önce fiyat verilmemiş / hiç alınmamış kalemlere Min Fiyat (ya da Liste / Son Satış) + % ile fiyat üretilir — genel % ya da ürün grubu bazında %, yuvarlama 0,01 / 0,05 / 0,10; kapsam: fiyatsız, aldığı ama fiyatsız, seçili grup, işaretli, tümü; önce tabloya yazılır, Kaydet ile tanımlanır. Satır başına Min + % ve kaldır; işaretlilere toplu işlem; min fiyatın altına inilemez (Yönetici onayla girebilir). Fiyatları Kopyala (başka müşteriden ± %), müşteriye gönderilecek fiyat listesi PDF / Excel, tablo CSV. Ürün Bazında sekmesi: bir ürünün tüm müşterilerdeki fiyatı, son satışı, Fiyat Yönetimi oran fiyatı. Günlük: kim, ne zaman, eski → yeni. Özet kutuları: fiyat verilmemiş, aldığı ama fiyatsız, min altı, süresi dolan.", "/Rapor95", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Fiyat ve Müşteri Koşulları");
            Guncelleme(l, T(28, 10), "Konsolide Finansal Hareketler", "Menüdeki ad \"Konsolide Günlük Finansal Hareketler\" → \"Konsolide Finansal Hareketler\" olarak değişti (Mali İşler › Finans › Nakit Akışı ve Likidite); ekran aynı: Konsolide Finansal Takip Paneli.", "/Rapor123/Index", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Kaldirma(l, T(28, 10), "Banka ve Finans Kuruluşları", "Menüden kaldırıldı (Mali İşler › Finans › Nakit ve Banka Yönetimi); banka ve finans kuruluşu carileri Cari Bilgileri ekranında (Müşteri / Tedarikçi Cari Kartları birleşik görünümü) izlenir. Menüde adı \"(Kaldırıldı)\" rozetiyle durur.");
            Guncelleme(l, T(28, 10), "Muhasebe Çek Akıbeti Raporu", "Menüde yeri değişti: Finans › Finansal Araçlar'dan Muhasebe › Çek ve Senet Muhasebesi'ne taşındı (muhasebe kayıtları muhasebenin işi; ekran aynı).", "/Rapor71/Index2", "Mali İşler › Muhasebe › Çek ve Senet Muhasebesi");
            Guncelleme(l, T(28, 10), "Muhasebe Çek İbraz Kontrolü", "Menüde yeri değişti: Finans › Finansal Araçlar'dan Muhasebe › Çek ve Senet Muhasebesi'ne taşındı (ibraz kontrolü muhasebenin işi; ekran aynı).", "/Rapor126", "Mali İşler › Muhasebe › Çek ve Senet Muhasebesi");
            Yeni(l, T(29, 10), "Zimmet Raporu", "İK ve İdari İşler altında yeni IT alanı: IT ve idari varlıkların zimmeti. Dizüstü / masaüstü bilgisayar, monitör, cep telefonu, SIM hattı, tablet, yazıcı, erişim kartı, yazılım lisansı, şirket kredi kartı ve e-imza seri no, şirket, alış tarihi, değer ve garantiyle envantere alınır; personele zimmetlenir / devredilir, iade alınır, arızalı / serviste / hurda / kayıp izlenir. Kişi Bazında görünümde kimde ne var (araç zimmeti Araç Takip'ten gelir), Zimmet Tutanağı PDF (imza alanlı), dosya yükleme (tutanak, fatura), hareket günlüğü, Excel. Personel Dosyası her kişinin zimmetlerini bu kayıttan canlı okur.", "/Zimmet", "İK ve İdari İşler › IT › Zimmet ve Envanter");
            Yeni(l, T(29, 10), "Araç Takip Raporu (Filo Özeti)", "İdari İşler için tüm araçlar tek tabloda ve SENKRON: hangi şirkete kayıtlı, kimde, km, kaskosu / trafik sigortası var mı (Sigorta ekranından canlı), bakım durumu ve muayene (Araç Bakım'dan canlı), ruhsat belgeleri (Şirket Dökümanları). Bu ekranda KM GİRİŞİ yapılır (aracın km'si ve sonraki bakım hesabı otomatik güncellenir), YAKIT tüketimi (L/100 km), aylık yakıt limiti (L ve ₺) ve yakıt alımları, aylık HGS LİMİTİ ve gerçekleşen tutar izlenir; EV–İŞ MESAFESİNE göre 30 günde kaç litre / kaç ₺ yakıt tüketileceği hesaplanır (mesafe × 2 × çalışma günü × tüketim / 100 × yakıt fiyatı). Limit aşımı, poliçe yok, bakım / muayene gecikti, km girilmedi uyarıları; Limitler sekmesinde araç başına tüketim, yakıt, HGS, ev–iş mesafesi düzenlenir; araç takip özeti PDF, Excel.", "/AracTakip", "İK ve İdari İşler › İdari İşler › Araç, Taşınmaz ve Demirbaş");
            Yeni(l, T(29, 10), "Personel Dosyası", "Her personel için tek dosya: kimlik ve iletişim, acil durum, ehliyet, ŞİRKET PASAPORTU (kullanıyor mu, şirket kasasında mı, no, bitiş, vizeler), ZİMMETLER (Zimmet Raporu'ndan canlı), ARAÇ (Araç Bakım / Araç Takip / Sigorta'dan canlı: km, bakım, kasko), açık AVANSLAR (Nakit Avans), belgeler (iş sözleşmesi, SGK giriş, sağlık raporu, İSG sertifikası … dosya yükleme ve geçerlilik takibi; eksik / süresi dolan uyarısı), eğitimler ve günlük. Sekmeler: Personel · Pasaport ve Vize · Belge Takibi · Zimmet ve Araç; Personel Dosyası PDF.", "/PersonelDosya", "İK ve İdari İşler › İnsan Kaynakları › Personel ve Organizasyon");
            Kaldirma(l, T(29, 10), "Kasa / Banka Bakiye Raporu", "Menüden kaldırıldı (Mali İşler › Finans › Nakit ve Banka Yönetimi); kasa ve banka bakiyeleri Konsolide Finansal Takip Paneli › Bakiyeler sekmesinde şirket şirket izlenir (nakit kasa, çek / senet X · R, banka SAP ↔ Finekra). Eski adres (/Rapor147) oraya yönlenir. Menüde adı \"(Kaldırıldı)\" rozetiyle durur.");
            Kaldirma(l, T(29, 10), "Nakit Akışı (Ödeme Bekleyenler)", "Menüden kaldırıldı (Mali İşler › Finans › Nakit Akışı ve Likidite); ödeme bekleyen satırlar Kasa Nakit Akışı'nda (planlanan tarihe göre üstte; Talepler ve Yeni Ödeme ile birlikte). Eski adres (/Rapor) Kasa Nakit Akışı'na yönlenir. Menüde adı \"(Kaldırıldı)\" rozetiyle durur.");
            Kaldirma(l, T(29, 10), "Nakit Akışı (Ödenenler)", "Menüden kaldırıldı; ödenen satırlar Kasa Nakit Akışı'nda (ödenme tarihine göre altta; Ödenen Tutar, makbuz / dekont) ve Konsolide Finansal Takip Paneli › Tümü sekmesinde izlenir. Eski adres (/Rapor3) Kasa Nakit Akışı'na yönlenir. Menüde adı \"(Kaldırıldı)\" rozetiyle durur.");
            Guncelleme(l, T(29, 10), "Modül Sayfası", "Menüden kaldırılan raporlar listeden silinmez: adı üstü çizili, yanında kırmızı \"(Kaldırıldı)\" rozeti (şema, sol menü, liste ve üst çubuk araması); tıklanınca kaldırılma notu ve yerine geçen ekranı sekmede açan düğme gösterilir. Liste durum süzgecine \"Kaldırıldı\" seçeneği; grup özetinde kaldırılan sayısı.", "/Modul/mali-isler?yol=finans/nakit-akisi-likidite", "Mali İşler");
            Guncelleme(l, T(29, 10), "Kasa Nakit Akışı", "\"Yeni Ödeme\" yanına \"Talepler\" düğmesi (rozet: açık talep sayısı; onaylı varsa yeşil): Ödeme Talebi modülünden gelen departman talepleri tüm şirketlerden tek listede — şirket, departman / talep eden, kurum, belge, son ödeme, tutar, mutabakat, yöntem, öncelik, durum. Onaylanmış talep \"Nakit Akışa Ekle\" ile kendi şirketinin nakit akışına satır olur (nakit yöntemde nakit onayına düşer); onay bekleyen talepte düğme yerine \"Onay Bekliyor\" ve modül bağlantısı. Yeni Ödeme › Ödenmemiş Faturalar ve Cari Bakiyeleri listeleri artık hiçbir şirkette boş kalmaz: seçilen şirketin kendi carileri önde, grup tedarikçileri (şirket etiketiyle) arkada; fatura sahibi ≠ ödeyen senaryosu desteklenir.", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(29, 10), "Konsolide Finansal Takip Paneli", "Panel artık Durum Özeti yerine yeni \"Tümü · Tüm İşlemler\" sekmesiyle açılır: banka (Finekra), kasa, çek / senet, kart ve grup içi hareketler tek listede — tarih / saat, şirket, hesap ve tip rozeti, işlem türü, karşı taraf, açıklama, satır kaynağı, giriş / çıkış (dövizde döviz tutarı ve kur), nakit akış eşleşmesi, onay, SAP, fiş; altlıkta tip bazında adetler ve net. Varsayılan \"Bugün\" (o gün yapılan tüm işlemler); başlangıç / bitiş ya da hızlı dönem seçilince kendiliğinden \"Seçili Dönem\" olur, Bugün ↔ Seçili Dönem düğmesiyle geçilir. Satıra tıklayınca banka hareketi ya da kasa / çek çekmecesi açılır; onay durumu ve arama süzgeçleri burada da çalışır. Durum Özeti sekmesi yerinde duruyor.", "/Rapor123?sekme=tumu", "Mali İşler › Finans › Konsolide Finansal Hareketler");
            Guncelleme(l, T(29, 10), "Konsolide Finansal Takip Paneli", "\"Ödeme Ekle\" penceresi geliştirildi: üç sekme — Ödeme Ekle (form), PORTFÖY ÇEK / SENET ve PLANLI. Portföy sekmesi tüm grup şirketlerinin portföydeki çek / senetlerini listeler: çek no, portföy şirketi, kimden geldi (keşideci), banka / şube, vade ve kalan gün, tutar, Çek Akıbeti durumu, kullanım durumu; arama (no, müşteri, banka, tedarikçi, talimat), şirket / belge / durum / vade süzgeçleri ve özet. Planlı sekmesi Kasa Nakit Akışı'nda ve Çek Akıbeti'nde \"Planlandı\" olan belgeleri planlanan tedarikçi, plan tarihi, nakit akış satırı (#, durum, talimat, onay, çıkış talebi, bağlantı) ve dolaşım özetiyle gösterir. Satırdan: \"Bu Belgeyle Öde\" (belge ödeme formuna seçilir, tutar ve tarih dolar), \"Planla\" (nakit akışa çek / senet satırı), \"İbraz / Ciro\" (planlı belge plan satırı üzerinden tek adımda tedarikçiye ciro ya da bankaya tahsile verilir; plansız belgede GMY onayına düşer). Formdaki çek seçiminin yanında \"Portföyde Ara\" düğmesi.", "/Rapor123?sekme=cek", "Mali İşler › Finans › Konsolide Finansal Hareketler");
            Guncelleme(l, T(29, 10), "Tahsilat", "Cari seçimi sadeleştirildi: kod / ad arama kutusu + cari listesi (açık fatura adedi ve tutarıyla); 14 süzgeç kaldırıldı (toplu ekranlarda kalır). Adat Hesaplama'da da aynı: Müşteri / Tedarikçi seçimi + arama + liste.", "/Rapor117", "Muhasebe › Cari İşler › Alacak ve Tahsilat Takibi");
            Guncelleme(l, T(29, 10), "Tahsilat", "Dinamik yapı (Adat Hesaplama mantığı): bir tahsilatta BİRDEN ÇOK ÖDEME SATIRI (nakit + çek + senet + havale + kart birlikte; her satırda yöntem, tarih / çek vadesi, belge no, banka, kur, tutar). Kur OTOMATİK (satır tarihinin TCMB kuru, Data/KurOrnek.cs) ya da tıklayınca ELLE. Fatura seçimi OTOMATİK (en eski vadeliden FIFO) ya da MANUEL (faturalar işaretlenir, istenirse tutar sınırı; \"Tutarı Faturalardan Al\"). Kapanış simülasyonu her değişiklikte yenilenir: faturada kapanan, kalan, hangi ödeme satırı, gün, kur farkı, vade farkı; avans. \"Kaydet ve İşle\" cari hesabına işler; \"Taslak Kaydet (İşleme Alma)\" cariye işlemez, Tahsilatlar sekmesinde Taslak olarak durur ve istenen zaman \"İşleme Al\" ile aynı kayıttan ibraz edilir (çekler teslim alınınca vb.; taslak silinebilir). Cari bilgisi: SON ÖDEME ve SON YÜKLEME (fatura) tarihi, ortalama ödeme gecikmesi, son 12 ay hacim, eşleşmemiş ödeme, vade bekleyen çek. Cari seçimi 14 ortak süzgeçle. \"Otomatik Kapat\": tahsilattan önce kapaması yapılmamış ödemeleri faturalarla eşleştirip kapatır. İndir: cari ekstre PDF / Excel, tahsilat simülasyonu PDF / Excel, kayıtlı tahsilat makbuzu PDF / Excel (QuestPDF / ClosedXML). Takip Paneli'ne satır bazında (banka / kasa / çek) düşer.", "/Rapor117", "Muhasebe › Cari İşler › Alacak ve Tahsilat Takibi");
            Guncelleme(l, T(29, 10), "Adat Hesaplama", "Rapor sıfırdan geliştirildi: cari (müşteri / tedarikçi) 14 ortak süzgeçle seçilir; açık faturalar (düzenlenebilir hesap tutarı, müşteri ödeme koşuluna göre dinamik vade) ve ödeme / çek satırları (portföydeki vade bekleyen çekler ve eşleşmemiş ödemeler otomatik; nakit / çek / senet / havale eklenir) ile FIFO kapanış simülasyonu CANLI: gün, vade farkı (tutar × gün × aylık oran ÷ 3000), aylık adat dağılımı (ağırlıklı ortalama vade, net gecikme, VF payı), KPI (fatura, ödeme, kalan bakiye, net adat farkı, vade farkı, KDV'li tutar). Cari bilgisi: son ödeme, son yükleme, ortalama gecikme, risk. Taslak Kaydet (cari bazında saklanır, girince yüklenir), Tahsilata Aktar (satırlar Tahsilat ekranına taslak tahsilat olur), Otomatik Kapat; PDF / Excel (faturalar, tahsilat, tam), ekstre PDF / Excel, kart / ekstre / tahsilat / tedarikçi takip bağlantıları. Eski onay akışı ve SAP robotu kaldırıldı.", "/Rapor21", "Muhasebe › Cari İşler › Cari Hesap Yönetimi");
            Guncelleme(l, T(29, 10), "Otomatik Kapatma", "Cari listesine Müşteri / Tedarikçi Cari Kartları ile aynı 14 süzgeç geldi (Ara: kod, ünvan, VKN, yetkili, e-posta; Cari Kart Tipi; Bölge; Ülke; Sınıf; İlişki Durumu; Rol; Durum; Faaliyet Ana Grubu; Faaliyet Grubu; Satış Temsilcisi; Şirket; Limit Durumu; Risk Durumu) + kapama durumu, para birimi ve sıralama; adres satırından ön süzgeç. Listede sınıf / bölge, temsilci, risk ve limit sütunları; satırdan kart, tahsilat (müşteri) ya da tedarikçi takip (tedarikçi) bağlantıları.", "/Rapor64", "Muhasebe › Cari İşler › Mutabakat ve Kapama");
            Guncelleme(l, T(29, 10), "Tedarikçi Fatura ve Ödeme Takip Raporu", "Rapor sıfırdan tasarlandı: tedarikçi kartları üzerinde (14 ortak süzgeç; Satınalma Temsilcisi) borç bakiyesi (X / R), açık alış faturalarının vade kırılımı (gecikmiş · bu hafta · 8–30 · 31–60 · 60+ gün), verilen çek / senet, Kasa Nakit Akışı'ndaki planlı ödemeler (adet, tutar, gecikmiş plan), son ödeme / son alım, ortalama ödeme gecikmesi, risk ve açık hesap limiti; ödeme durumu süzgeci, tıklanınca süzen özet kartlar, Excel. Tedarikçi Detayı: alış faturaları (durum, ödeme eşleşmesi, gecikme), ödemeler ve verilen çekler (eşleşmemişler işaretli), nakit akış planlı ödemeleri (satır bağlantısıyla), günlük; Otomatik Kapat, Ödeme Talebi, Kasa Nakit Akışı, ekstre PDF / Excel, kart, adat, E-Mutabakat bağlantıları. Ödeme Takvimi: fatura vadeleri ile nakit akış planı hafta hafta (fark = plansız vade).", "/Rapor52", "Muhasebe › Cari İşler › Tedarikçi ve Borç Takibi");
            Guncelleme(l, T(29, 10), "Tedarikçi Konsolide Ödeme Takip Raporu", "Rapor sıfırdan tasarlandı: tüm grup şirketlerinin tedarikçi borçları tek listede (14 ortak süzgeç): borç bakiyesi, vade kırılımı, çek / senet, planlı ödeme, son 30 gün ödeme, vade dağılım çubuğu, risk ve limit; \"Plansız Vade\" göstergesi (gecikmiş + bu hafta − planlı). Haftalık Ödeme Planı: fatura vadeleri ↔ nakit akış planı, hafta hafta fark; Şirket Özeti (plan karşılama oranı) ve Satınalmacı Özeti (satıra tıklayınca liste süzülür); Planlı Ödemeler sekmesi Kasa Nakit Akışı tedarikçi satırlarını (plan tarihi, belge, yöntem, satınalmacı, durum) listeler. Tedarikçi Fatura ve Ödeme Takip, Ödeme Talebi, Kasa Nakit Akışı ve Otomatik Kapatma ile entegre.", "/Rapor53", "Muhasebe › Cari İşler › Tedarikçi ve Borç Takibi");
            Guncelleme(l, T(28, 10), "Konsolide Tahsilat Takip Raporu", "Rapor sıfırdan hazırlandı; tüm şirketlerin müşteri carileri tek listede: bakiye (X / R), vade kırılımı (gecikmiş · bu hafta · 8–30 · 31–60 · 60+ gün), açık toplam, içerideki çek / senet, son 30 gün tahsilat ve son tahsilat, vade dağılım çubuğu, risk ve limit durumu, temsilci; süzgeçler (şirket, temsilci, bölge, risk, durum: gecikmiş / bu hafta / çek / 30 gündür tahsilat yok), sıralama, tıklanınca süzen özet kartlar, Excel. Haftalık Beklenen: önümüzdeki 8 haftanın beklenen tahsilat planı fatura vadelerinden (gecikmişler ilk satırda; satıra tıklayınca faturalar). Şirket Özeti: şirket bazında bakiye / gecikmiş / vade kovaları / çek / 30 gün tahsilat oranı. Son Tahsilatlar: Tahsilat ekranından kaydedilenler. Satırdan Tahsilat ekranı, cari kart, ekstre ve Takip Paneli'ne geçiş. Veri: cari kartları + Cari Mutabakat + Tahsilat.", "/Rapor17", "Muhasebe › Cari İşler › Alacak ve Tahsilat Takibi");
            Guncelleme(l, T(28, 10), "Tahsilat", "Konsolide Finansal Takip Paneli ile entegre: Tahsilat ekranından kaydedilen her tahsilat şirketine göre panele düşer — Havale / EFT ve Kredi Kartı → Banka sekmesi (giriş), Nakit → Kasa (giriş), Çek / Senet → Çek · Senet (portföye giriş); satır kaynağı \"Tahsilat Ekranı · Bakiyeden / Fatura Bazlı\", referans tahsilat no, açıklamada kapatılan faturalar, avans, vade / kur farkı; dövizli tahsilatta döviz tutarı ve kur. Tahsilatlar listesinde \"Takip Paneli\" ve \"Ekstre\" bağlantıları. Bakiyeden tahsilatta artan avans artık eşleştirilmemiş tahsilat olarak Otomatik Kapatma'da görünür.", "/Rapor117", "Muhasebe › Cari İşler › Alacak ve Tahsilat Takibi");
            Guncelleme(l, T(28, 10), "Otomatik Kapatma", "\"Mutabakat\" raporu sıfırdan tasarlandı ve adı Otomatik Kapatma oldu (\"Otomatik Kapama\" ekranı kaldırıldı, buraya yönlenir). Amaç: açık (kapanmamış) faturalar ile faturayla eşleştirilmemiş ödeme / tahsilat / çek / senet hareketlerini kapatmak. Cariler sekmesi: tüm carilerde açık fatura ve eşleşmemiş ödeme adet / tutarı, kapatılabilir tutar, öneri sayısı (birebir / FIFO), durum (Kapatılabilir · Ödeme Bekliyor · Yalnız Açık Fatura · Temiz), süzgeçler; \"Tüm Carilerde Otomatik Kapat\" ve seçili carilerde otomatik kapat tek tıkla (aynı para biriminde önce birebir tutar eşleşmesi, sonra en eski vadeli faturaya FIFO). Cari Eşleştirme: açık faturalar ve eşleşmemiş ödemeler yan yana, kutucukla seçip \"Otomatik Eşleştir\" (öneri) ya da \"Seçileni Eşle\" (elle, tutar düzenlenebilir), eşleştirme listesi, kapama özeti, \"Eşleşmeleri Kapat\". Kapatılan tutar fatura ve ödemenin kalanından düşer, cari günlüğü ve kapama kaydına yazılır; Kapama Kayıtları sekmesi ve Excel. ?kod= ile cari ön seçilir.", "/Rapor64", "Muhasebe › Cari İşler › Mutabakat ve Kapama");
            Guncelleme(l, T(28, 10), "E-Mutabakat", "Rapor sıfırdan tasarlandı: cari kartta kayıtlı ana mutabakat yetkilisinin e-postası ve cep telefonu üzerinden sistem mutabakat talebini kendisi gönderir — E-POSTA (PDF ekstre + yanıt bağlantısı) ve WHATSAPP (kısa mesaj + yanıt bağlantısı), ikisi birden de gönderilebilir. Cariler sekmesi: yetkili, kanal uygunluğu (e-posta var / WhatsApp var / eksik), bakiye ve döviz özeti, son gönderim, e-mutabakat durumu (Gönderilmedi · Yanıt Bekliyor · Hatırlatma Zamanı · Mutabık · İtirazlı); satıra tıklayınca sağda e-posta ve WhatsApp mesaj önizlemesi, Gönder düğmeleri ve cihazdaki posta / WhatsApp uygulamasını açan mailto: / wa.me bağlantıları; seçilenlere toplu gönderim, hatırlatma (eşik 5 gün yanıtsız), \"Yanıtları Çek\" (bağlantıdan gelen Mutabık / İtiraz cevapları otomatik işlenir), elle yanıt işleme. Gönderimler ve Yanıtlar: belge no, kanal, kime, özet, tekrar, sonuç, yanıt; Excel. İletişim Bilgileri: kişi bazında e-posta / cep düzeltme ve ana yetkili seçimi. Şablonlar: e-posta konu / gövde, WhatsApp mesajı, hatırlatma eki, yer tutucular. Günlük. Gönderimler Cari Mutabakat günlüğüne de yazılır.", "/Rapor59", "Muhasebe › Cari İşler › Mutabakat ve Kapama");
            Guncelleme(l, T(28, 10), "Cari Ekstre / Hesap Ekstresi Mutabakatı", "Tasarım sıfırdan düzenlendi: her carinin cari ekstresi (120 / 320 cari hesabı) ile muhasebe hesap ekstresi (bağlı kebir hesabı) dönem bazında karşılaştırılır. Cariler: hesap kodu, cari borç / alacak / bakiye, hesap borç / alacak / bakiye, fark, satır sayıları, durum (Uyuşuyor · Fark Var · Hesap Tanımsız) ve fark nedenleri; dönem, tip, şirket, durum ve fark türü süzgeçleri; tıklanınca süzen özet kartlar; Excel. Satır Karşılaştırma: sol cari ekstre, sağ hesap ekstresi satır satır — Eşleşti · Tutar Farkı (kur / kuruş) · Yalnız Cari (fatura muhasebeye aktarılmamış) · Yalnız Hesap (kur farkı / mahsup fişi cariye işlenmemiş) · Mükerrer fiş; her farkta neden, öneri ve tek tıkla düzeltme fişi (tümü için de). Düzeltme Fişleri sekmesi; fişler cari günlüğüne yazılır.", "/Rapor141", "Muhasebe › Cari İşler › Mutabakat ve Kapama");
            Guncelleme(l, T(27, 10), "Tahsilat", "Ekran sıfırdan tasarlandı (Data/TahsilatOrnek.cs, Controllers/TahsilatController.cs): müşteri tahsilatı BAKİYEDEN (tutar en eski vadeli açık faturalardan FIFO dağıtılır, artan kısım bakiyeye avans) ya da FATURA BAZLI (kapatılacak faturalar seçilip tutar yazılır; \"Tümünü Doldur\"). Her satırda otomatik gecikme günü, VADE FARKI (kalan × kur × aylık %3,5 / 30 × gün) ve dövizli faturada KUR FARKI (tutar × (tahsilat kuru − fatura tarihindeki kur)); Hesap Özeti'nde KDV dahil tutarlar. Kayıt Cari Mutabakat hareketine X / R işlem tipiyle işlenir (Havale / EFT, Nakit, Çek, Kredi Kartı, Senet), kart günlüğüne yazılır. Basit fatura kesme: tek tıkla KDV'li Kur Farkı (KFF) / Vade Farkı (VFF) faturası, 30 gün vadeli, cari hesabına Fatura olarak işlenir; Fark Faturaları sekmesinde yazdırılabilir önizleme. Tahsilatlar sekmesinde kayıtlar, dağıtım detayı ve Excel. ?kod= ile cari ön seçilir (kart detayından).", "/Rapor117", "Muhasebe › Cari İşler › Alacak ve Tahsilat Takibi");
            Guncelleme(l, T(27, 10), "Cari Bakiye Raporu", "X / R ve özet: bakiyeler X ve R işlem tipine göre ayrı izlenir — \"Bakiye Tipi\" seçimi (X + R / yalnız X / yalnız R) bakiye sütununu, özet kutularını ve sıralamayı o tipe göre hesaplar; Cari Bölge sütunu eklendi; sütun başlığına tıklayınca sıralama (yön değiştirilebilir; Vadesi Geçmiş, Toplam Risk vb.), özet kutularına tıklayınca süzme / sıralama; satır sonundaki simgeler kartı (detay paneli) ve Cari Ekstre'yi açar, çift tıklama kartı açar. \"Özet · Satışçı\" sekmesi: temsilci bazında cari sayısı, bakiye, vadesi geçmiş, gecikmeli cari, çek / senet, toplam risk, riskli ve limit aşan sayısı, kredi limiti (satıra tıklayınca liste o temsilciye süzülür); tip-bölge özeti ve X / R özeti. X / R tüm cari raporlarında ortak altyapı: Cari Mutabakat hareketleri işlem tipi taşır, kart detayındaki Cari Risk kartında Bakiye X / R görünür, Tahsilat X / R ile kaydedilir, Cari Ekstre Aktarım sütunu / süzgeci.", "/Rapor65", "Muhasebe › Cari İşler › Cari Hesap Yönetimi");
            Guncelleme(l, T(27, 10), "Cari Bakiye Raporu", "Tasarım sıfırdan yenilendi ve cari kartlarıyla entegre edildi: müşteri ve tedarikçi carilerinin para birimi bazında bakiyesi ve TL karşılığı, vadesi geçmiş (kalem, en uzun gecikme) / vadesi gelecek açık faturalar, içerideki çek / senet, toplam cari risk, kredi limiti ve kullanımı, otomatik risk durumu (30 gün kuralı) ve durum. Süzgeçler Müşteri / Tedarikçi Cari Kartları ile aynı: ara, cari kart tipi, bölge, ülke, sınıf, ilişki, rol, durum, faaliyet ana grubu / grubu, temsilci, şirket, limit durumu, risk durumu. Üstte özet kutuları (müşteri alacağımız, tedarikçi borcumuz, vadesi geçmiş, vadesi gelecek, çek / senet, riskli cari, limit aşan; tıklayınca süzer), sıralama (toplam risk, bakiye, vadesi geçmiş, gecikme, kullanım, kod, ad), müşteri / tedarikçi / genel alt toplamlar, Excel; satırdan karta (detay paneli) ve Cari Ekstre'ye geçiş.", "/Rapor65", "Muhasebe › Cari İşler › Cari Hesap Yönetimi");
            Guncelleme(l, T(27, 10), "Cari Ekstre", "Tasarım sıfırdan yenilendi (wwwroot/css/ekstre-rapor.css): tek satır üst şerit (başlık, aktif veritabanı, Sistemi Kur); süzgeç kartı — alanlar bir satırda, seçenekler küçük çipler, \"Raporla\" başlık satırında, seçili cari ve tarih aralığı özetli; cari başlığı ile işlem düğmeleri (Cari Notları, Mutabakat Kaydet / Yap, Excel, Mutabakat Formu, Dikey / Yatay PDF) tek satırda; altında özet kutuları (toplam borç, toplam alacak, net bakiye ve yönü, hareket sayısı, açık ve kısmi belge sayısı). Ekstre blokları cari + para birimi başlıklı; tablo sıkı ve okunur: küçük büyük-harf başlıklar, muhatap kodu ve adı tek hücrede, borç kırmızı / alacak yeşil, bakiye kalın; \"Durum\" etiketleri açık zemin + koyu yazı (Açık / Kısmi / Kapalı) olarak okunur hale geldi; alt toplam satırında hareket sayısı; renk açıklaması tablo altında tek satır. Şirket ve para birimi özetleri yan yana iki kartta, muhasebe hesap bakiyeleri ayrı kartta. Mutabakat ve not pencereleri aynen çalışır.", "/Rapor20", "Cari Ekstre");
            Guncelleme(l, T(27, 10), "Cari Ekstre", "Rapor, Müşteri / Tedarikçi Cari Kartları'ndaki kart kodlarını (120.xxx / 320.xxx) tanır: cari listesinde CARİ_MASTER kartları da yer alır, kart detay panelindeki \"Cari Ekstre\" sekmesi raporu o cariyle açar. Tedarikçi kodlarında satırlar alış faturası (alacak) / ödeme (borç) olarak üretilir ve bağlı hesap 320 Satıcılar gösterilir.", "/Rapor20", "Cari Ekstre");
            Guncelleme(l, T(27, 10), "Tedarikçi Cari Kartları", "Kart detayında \"Düzenle\": tedarikçi kartı yeni talep açmadan doğrudan düzeltilir (CARİ_MASTER alanları ve faaliyet satırları; canlı doğrulama; değişiklik geçmişi). Kart detay paneli sekmeli: Kart · Yeni Talep · Talepler · Talep Detayı · Onay Bekleyenler · Cari Ekstre (Cari Ekstre raporu tedarikçi koduyla yeni sekmede; alış faturası / ödeme satırları). Değişiklik günlüğü: kart detayında o tedarikçinin geçmişi, Tedarikçi Cari Kartları'nda ve Tedarikçi Talep Formu'nda \"Değişiklikler\" sekmesi (kart açılışı, doğrudan düzenleme, durum, kredi limiti; süzgeçler ve Excel). Müşteri kartlarındaki düzenlemeler tedarikçi kartlarına da uygulandı: kredi limiti (tedarikçinin tanıdığı açık hesap limiti; Yok / Manuel / Dinamik = son N ay alış faturaları aylık ortalaması × çarpan; kullanım = ödenmemiş alış faturaları / limit), listede \"Kredi Limiti\" ve \"Limit Kullanımı\" sütunları, \"Limit Durumu\" süzgeci, Excel'e limit sütunları, kart detayında \"Kredi Limiti\" kartı (son N ay alış tablosu, açık borç, tanım formu, limit geçmişi). Özet (KPI) kartları kaldırıldı, süzgeç alanı sıkılaştırıldı; sayfa \"Cari Kartları\" ve \"Özetler\" (Faaliyet Bazlı Satınalma Temsilcisi Dağılımı §12, Cari Kart Tipi / Bölge / Sınıf Matrisi §5) sekmelerine ayrıldı.", "/CariKart/Tedarikci", "Tedarik Zinciri › Tedarikçi Yönetimi › Tedarikçi Kartları");
            Guncelleme(l, T(27, 10), "Müşteri Cari Kartları", "Kredi limiti eklendi. Limit türü Yok / Manuel / Dinamik: Manuel limit Muhasebe / Yönetici tarafından elle ₺ girilir; Dinamik limit son N ayın satış faturalarından aylık alım ortalaması × çarpan olarak (varsayılan son 3 ay × 2, 1.000 ₺'ye yuvarlı) her açılışta güncel veriyle yeniden hesaplanır. Listede \"Kredi Limiti\" ve \"Limit Kullanımı\" sütunları (açık bakiye / limit, çubuk ve %), \"Limit Durumu\" süzgeci (Limit İçinde / Limite Yakın ≥ %80 / Limit Aşıldı / Limit Yok), Excel'e limit sütunları; üstteki özet (KPI) kartları kaldırıldı, süzgeç alanı sıkılaştırıldı. Sayfa iki sekme oldu: \"Cari Kartları\" (süzgeç + liste) ve \"Özetler\" (Faaliyet Bazlı Satış Temsilcisi Dağılımı §12 ve Cari Kart Tipi / Bölge / Sınıf Matrisi §5; temsilci dağılımı liste süzgecine göre hesaplanır). Kart detayında \"Kredi Limiti\" kartı: tanım, son N ay aylık alım tablosu (fatura adedi ve ₺), açık bakiye, kullanım, kalan limit, tanım formu (tür, manuel tutar, ay sayısı, çarpan, not) ve limit geçmişi. Grup içi cariler varsayılan limitsiz.", "/CariKart/Musteri", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Müşteri Portföyü");
            Guncelleme(l, T(23, 10), "Çek Akıbeti Raporu", "Çek / Senet Durum Parametreleri Standart Raporu uygulandı. 27 standart başlığın tamamı bilgi eksiltmeden 14 sütunda tek sayfa genişliğine sığdırıldı (sütun yönetimi kaldırıldı; üst satır ana değer, alt satır tamamlayıcı bilgi; her alanın süzgeci korunur, birleşik sütunlarda iki açılır liste): Çek Numarası · Belge Tipi · İşlem Tipi · Banka Adı / Şube; Portföye Giriş Tarihi (altında ay / yıl); Vade Tarihi (altında Vade Ay/Yıl · Vade Durumu); Uygunluk Durumu (altında Uygun Değil nedeni); Çek Tutarı (altında Para Birimi · TL Karşılığı); Çek Kimden Geldi (altında Asıl Borçlu); Hareket Durumu (altında Konum Durumu); İşlem Türü; Çek Kime Verildi (altında çıkış türü); İbraz Tarihi (altında ay / yıl); İbraz Belge No (altında Tahsilat Belge No · Vadeli Çek İbrazı); Planlanan Tedarikçi; Açıklama / İşlem Tipi (satır kaynağı rozeti + Nakit Akışa Ekle / İbraz Et / Tedarikçiye Çık + açıklama). Dar ekranda sütunlar alt sınırlarına kadar daraltılır, yine sığmazsa yatay kaydırılır ve Çek Numarası solda sabit kalır. Çek Tutarı para simgesiyle (₺ € $ £), dövizli belgede altında ₺ karşılığı. Planlanan Tedarikçi Kasa Nakit Akışı ile bütünleşik: planlı belgede plan satırının kurumu da değişir, uygun belgede tedarikçi yazılınca çek / senet satırı açılıp belge planlanır, silinince belge satırdan çıkar; hücrenin altında Nakit Akış satırı ve durumu (tıklanır). Belge detayında \"Dolaşım · Grup İçi Ciro Zinciri\" bölümü (zincir, adım tablosu, Kasa Nakit Akışı ve Konsolide Finansal Hareketler bağlantıları). Liste dinamik: Kasa Nakit Akışı / Takip Paneli'nde belge planlanıp ibraz edilince ya da dolaşım adımı gerçekleşince 20 sn içinde sayfa yenilenmeden tazelenir (süzgeç ve seçim korunur). İşlem Türü standart listeye indirildi (Portföyde, Planlandı, Erteleme Yapıldı, Bankaya Tahsile Verildi, Bankadan Tahsil Edildi, Elden Tahsil Edildi, Ciro Edildi, Teminata Verildi, Tahsil Riski, Konkordato Sürecinde, Karşılıksız, Protesto Edildi, İade Edildi, İptal Edildi); konum ayrı seçilir (\"Erteleme Yapıldı - Bankada\" gibi birleşik adlar kalktı). Otomatik akış: Konum Durumu (Portföyde / Bankada / Tedarikçide / Avukatta / Kapandı) ve Hareket Durumu (Portföyde / İşlem Yapıldı) işlem türünden; Vade Durumu (Vade Bekleniyor / Vadesi Bugün / Vadesi Geçti / Tahsil / Kapandı) vade tarihi ve türden; Uygunluk (Uygun / Uygun Değil) dördünden türetilir, elle girilmez ve başka koşul eklenmez — Portföyde ya da Erteleme Yapıldı + konum Portföyde + hareket Portföyde + Vade Bekleniyor belge Uygun; planlı, vadesi bugün / geçmiş, bankada, tedarikçide, avukatta, tahsil, iade, iptal ve riskli (Tahsil Riski, Konkordato Sürecinde, Karşılıksız, Protesto Edildi) belgeler Uygun Değil (nedeni rozetin araç ipucunda ve detayda). Standart raporda olmayan \"Kullanım Durumu\" alanı rapordan kaldırıldı; durum parametreleri yalnız İşlem Türü / Konum Durumu / Hareket Durumu / Vade Durumu / Uygunluk Durumu. Standart tablonun dışındaki kombinasyonlara izin verilmez: Tahsil Riski, Karşılıksız ve Protesto Edildi yalnız vadesi geçmiş evraka uygulanır (pencerede uyarı, Uygula kapalı; sunucu da reddeder). İşlem türü değiştirilince açılan pencerede konum, kime verildiği ve belge no sorulur; hareket, konum, vade durumu ve uygunluk uygulanmadan önce önizlenir; plansız çıkış yine GMY onayına düşer; satır sayfa yenilenmeden güncellenir. Özet kartları standart raporun yönetici süzgeçleri oldu (Portföyde, Uygun · Verilebilir, Planlandı, Vadesi Geçti, Bankada, Riskli · Karşılıksız, Tahsil Edildi, Kapandı). Kasa Nakit Akışı'na yalnız Uygun belgeler seçilebilir; vadesi gelmiş / geçmiş portföy belgesinde yalnız İbraz Et düğmesi kalır.", "/CekAkibeti", "Mali İşler › Finans › Çek Akıbeti Raporu");
            Guncelleme(l, T(22, 10), "Çek Akıbeti Raporu", "Tablo Konsolide Finansal Takip Paneli › Çek · Senet sekmesiyle aynı düzene getirildi: Belge · No, Vade, Kimden Geldi, İşlem Türü, Dolaşım, Satır Kaynağı · İşlem (kaynak rozeti + Nakit Akışa Ekle / İbraz Et / Tedarikçiye Çık / GMY Onayı Bekliyor / işlem gerekmez), Planlanan Tedarikçi, İbraz / Ciro · Kime Çıktı, Tutar, Nakit Akış Eşleşmesi, Kontrol, Uygunluk, Fiş. Tablo ekran genişliğine sığdırılır: sütunlar alt sınırlarına kadar orantılı daraltılır (kırpılan metin araç ipucunda), başlıklar iki satıra sarılır, hücre yazısı ve dolgusu sıkılaştırıldı; araç çubuğu, yıl düğmeleri, özet kartları (simge, tutar, adet) ve belge detayı penceresi de küçük ölçüye indirildi; dar ekranda işlem düğmeleri alt alta geçer, pencere boyutu değişince yeniden hesaplanır. Kasa Nakit Akışı'nda plan / ibraz yapılıp bu sekmeye dönülünce liste kendini tazeler.", "/CekAkibeti", "Mali İşler › Finans › Çek Akıbeti Raporu");
            Guncelleme(l, T(21, 10), "Kasa Nakit Akışı", "Ödeme adımı: çek / senet satırında \"Çeki Ver / İbraz Et\" (tedarikçiye ciro ya da bankaya tahsil; belge çıkar, satır ÖDENDİ, fişler otomatik); Havale satırında alıcı banka · IBAN · hesap adı (cari karttan getirilir) ile banka talimatı; ekler: dekont, imzalı makbuz, imzalı talimat, ciro bordrosu dosya olarak yüklenip rapor sayfasından açılır (Talimatlar sekmesinde İmzalı Yükle). Dövizli ödemede kur kaynağı (TCMB alış / satış / efektif — o günün kuru otomatik; anlaşmalı / fatura kuru elle; çekte tahsil günü kuru), kur günü, kur anlaşması notu ve bu cariye kur farkı faturası kesilip kesilmeyeceği. Fatura sahibi ≠ ödeyen şirket olan her ödemede otomatik Grup İçi Mahsup / Temlik belgesi (Mahsup ve Temlik sekmelerinde liste, yazdırılabilir belge; ödeme gerçekleşince iki şirkette muhasebe fişi, grup içi bakiye güncellenir). Departman taleplerinde mahsup sütunu kaldırıldı. Yeni ödemede fatura seçilince fatura vadesi, cari seçilince cari kart vade şartı son ödeme / planlanan tarihe otomatik gelir; çek seçiminde vadesi son ödeme tarihine yakın çekler önce listelenir. Çek satırlarında banka adı kaldırıldı (çekmecede).", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(20, 10), "Kasa Nakit Akışı", "Üst süzgeçte \"Satınalmacı\" yerine \"Temsilci / Talep Eden\" (satınalma temsilcisi ya da ödemeyi talep eden kişiye göre süzer); tablo kartındaki bilgi satırı kaldırıldı; sekmeler büyütüldü (kısa adlar: Havale, Talimat, Aylık) ve tek satırda kalır.", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(19, 10), "Kasa Nakit Akışı", "Departman taleplerinde Mahsup (ödemeden düşülecek iade faturası / alacak dekontu, ayrı sütun; ödenecek net ayrıca) ve ödeme öncesi Mutabakat durumu (Mutabık / Mutabık Değil / Bekliyor / Gerekmez) sütunları; talep nakit akışa net tutarla, mutabakat durumuyla ve mahsup notuyla alınır. Tutar (₺) hücresinde üst satır ₺ ile, alt satırda yalnız ödenecek dövizli tutar ve belgeye göre oran. Avans satırlarında konu metni yazılmaz (ayrıntı çekmecede), alt satırda yalnız avans no.", "/Rapor79?sekme=nakit", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(18, 10), "Kasa Nakit Akışı", "Yeni Ödeme'de departman talepleri ve temsilci süzgeci: (1) \"Departman Talepleri\" sekmesi — departmanlardan gelen ödeme talepleri (satınalma siparişi, fatura, muhasebeden gelen vergi / SGK / gümrük ödemesi, kira …): talep no, departman, talep eden, ödenecek kurum, belge tipi ve no, açıklama, son ödeme, tutar, önerilen yöntem, öncelik, onay durumu; \"Ekle\" ile talep doğrudan nakit akış satırı olur (nakit yöntemde onaya düşer), kalem simgesiyle forma alınıp düzenlenir. Belge tipi seçeneklerine Resmi Ödeme (vergi, SGK, gümrük) ve Diğer eklendi. (2) Ödenmemiş Faturalar, Cari Bakiyeleri ve Departman Talepleri sekmelerinde şirket ve arama yanında Temsilci / Talep Eden süzgeci (cari için satınalma temsilcisi, talep için talep eden); listelerde Temsilci sütunu. (3) Listelerdeki açıklama notu kaldırıldı; liste çekmece boyuna yayılır, altta boşluk kalmaz.", "/Rapor79?sekme=tumu", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(17, 10), "Kasa Nakit Akışı", "Yeni Ödeme'de üç giriş yolu ve sadeleşme: (1) Yeni Ödeme çekmecesinde Elle Giriş yanında \"Ödenmemiş Faturalar\" (şirket seçilir; o şirketin ödenmemiş tüm faturaları: cari, belge no, belge tarihi, son ödeme, gecikme, belge tutarı, kalan, nakit akışta planlı mı) ve \"Cari Bakiyeleri\" (şirketin tüm carileri: açık fatura adedi, toplam, vadesi geçmiş ve gelecek tutar, en eski vade, döviz dökümü, nakit akışta planlanan) sekmeleri; bilgiler Cari Mutabakat ekstresinden gelir, \"Seç\" ile satır forma dolar, cari adına tıklayınca Cari Ekstre Raporu o cariyle açılır. (2) Rapor açıklama kutuları (notlar) artık varsayılan gizli (üst çubuktaki bilgi düğmesiyle açılır); Kasa Nakit Akışı'ndaki uzun notlar kaldırıldı. (3) Avans satırlarında personel adı tabloda yazılmaz (\"Nakit Avans · Departman\"); şirket masrafı avansının ayrıntısı (kullanan, konu, kategori) satıra tıklayınca çekmecede görünür, şahsi avansta hiçbir yerde görünmez (Nakit Avans modülü listelerinde de maskelenir). (4) Çek / senet portföyü X ve R işlem tipine göre ayrı: bakiye satırları, üst kart özeti, portföy penceresinde Tip sütunu, Çek sekmesinde belge yanında rozet. (5) Bankaya tahsile gönderilen belgelerde cari olarak banka adı \"(Tahsil)\" ekiyle yazılır.", "/Rapor79?sekme=cek", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(16, 10), "Kasa Nakit Akışı", "Cari bazlı aylık görünüm, gizlilik ve düzen: (1) Aylık Ödemeler ve Çek · Senet Vade Dağılımı altında \"Cari Bazında\" tablo — o yıl hangi cariye ay ay ne çıkmış (planlanan modunda ne planlanmış), yıl toplamı, bu aya kadar toplam ve aylık ortalama (bu aya kadar ÷ ay sayısı, ör. 6. ayda ÷ 6); yönteme göre dağılım (Çek, Banka, Nakit …) ve yöntem süzgeci; vade görünümünde tahsile gönderilenler banka bazında satır; hücreye tıklayınca o carinin ödemeleri / belgeleri, detay kartı kapatılabilir. (2) Şahsi (maaş) avansında gizlilik: personel adı ve konu Kasa Nakit Akışı'nda gösterilmez (\"Personel Avansı (Şahsi) · Departman\"); şirket masrafı avansında çekmecede tür, konu, kategori, kullanan ayrıntılı görünür. (3) Çek satırının çekmecesinde \"Yönteme Özel Bilgiler · Çek\" kartı: Belge Ekle (portföy), belge bazında Çıkış Planı (hangi şirketten nasıl çıkacağı: zincir, son adım, simülasyon), Değiştir (kaldır + portföyden yeni seç), Kaldır; her belgenin çıkış yolu satırda yazar. (4) Sekme çubuğu tek satıra sığar (Günlük alta inmez); her sekmede satırlar kendi içinde 1'den numaralanır; Mutabakat durumu her sekmede Ödeme Durumu altında; Talep Eden bilgisi fatura sahibinin altında (satınalmacı / kaydı açan / avans kullanan / çıkış talebini yapan) ve çekmecede alan.", "/Rapor79?sekme=aylik", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(15, 10), "Kasa Nakit Akışı", "\"Aylık Ödeme · Çek Vade\" sekmesi: (1) Aylık Ödemeler — seçilen yılda ay ay, yönteme göre (Çek, Senet, Banka, Nakit, Kart, Mahsup, Temlik, Yansıtma, Diğer) ne kadar ödeme yapıldığı; tarih esası gerçekleşen (ödenme tarihi), planlanan ya da tümü; hücreye tıklayınca o ayın ödemeleri, Çek / Senet hücresinde o ay çıkan belgeler (vadesi ne olursa olsun) ve alt bilgide vade dağılımı; \"Bu Ayın Çeklerini Vade Tarihine Göre Gör\" ile geçiş. (2) Çek · Senet Vade Dağılımı — tüm yılda vade ayına göre verilen çek / senet adet ve tutarı (çıkmış / planlı ayrımı; önceki ve sonraki yıl vadeliler), çıkış ayı filtresi ve çıkış ayı × vade ayı matrisi; satır ya da hücreye tıklayınca belge listesi (belge no, banka, keşideci, vade, çıkış tarihi, verilen cari, akıbet, kontrol), belgeden ödeme kaydına geçiş.", "/Rapor79?sekme=aylik", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(14, 10), "Kasa Nakit Akışı", "Onay, makbuz, muhasebe ve belge kontrolü: (1) Her sekmede Planlanan Ödeme Tarihi yanında Son Ödeme Tarihi (vadesi geçen kırmızı), Belge No · Belge Tipi (tıklanınca belge detayı: fatura / sipariş başlığı, kalemler, ödeme planı, mükerrer kontrolü; Cari Bakiye satırında carinin açık kalemleri) ve Fatura Sahibi ile Ödeyen Şirket iki ayrı sütun. Üstteki kartlar tıklanınca filtre (ödenen, kalan, bu hafta, geciken, onay bekleyen, mükerrer, avans); başlık altındaki uzun açıklama kaldırıldı. (2) GMY çek kontrolü: Kasa Nakit Akışı'nda planlanmamış bir çek Çek Akıbeti Raporu'ndan ciro / bankaya ibraz edilmek istenirse çıkış yapılmaz; aynı belge (çek no, banka, tutar) Çek sekmesine \"GMY Onayı Bekliyor\" satırı olarak düşer, Alev Özavşar onaylarsa çıkış işlenir ve satır ödenir, reddederse belge portföyde kalır. Nakit akışta planlanıp talimatla çıkan belgeler için ek onay yoktur. (3) Nakit talep → onay → makbuz: nakit ödeme satırı taleptir, Alev Özavşar / Neslihan Uludağ / Özge İsen onaylamadan ödenmez ve talimata alınmaz; onaylı satırdan \"Makbuz Kes\" ile kasa tediye makbuzu (makbuz no, kasa, teslim alan, tutar yazıyla, yazdırılabilir) kesilir, satır ÖDENDİ olur, muhasebe fişi (320 Satıcılar / 332 İştiraklere Borçlar / 196 Personel Avansları borç, 100 Kasa alacak) otomatik atılır; kasa talimatı gerçekleşince makbuzlar otomatik kesilir. Tüm ödemelerde (banka, kart, çek ciro, grup içi dolaşım adımları) muhasebe fişi otomatik; çekmecede fiş satırları görünür. (4) Dövizli fatura ve ödeme oranı: belge tutarı ayrı alan, satır tutarı belgeye göre % (ör. 100.000 USD'lik faturanın %70'i); \"Kısmi Ödeme / Taksit\" ile satır oranlara bölünür, kardeş satırlar aynı belge no ile ödeme planında izlenir; planlanan toplam belge tutarını aşarsa ve aynı belge aynı tutar ikinci kez girilirse sistem mükerrer uyarısı verir (satırda rozet, kayıt öncesi onay sorusu). (5) Çekmecede işlem çubuğu: tablodaki her işlem (portföyden belge seç, dolaşım, planı kaldır, nakit onayı, makbuz, talimat, taksit, belge detayı, modül kaydı) satırın üzerinden de yapılır; \"Belge Seç\" ile carinin açık faturaları / siparişleri ya da cari bakiyesi seçilir (satır fatura veya siparişten değil cari bakiyeden de açılabilir). Portföy penceresinde \"Planla ve Dolaşımı Planla\" seçilen her çek için dolaşım planını sırayla açar.", "/Rapor79?sekme=nakit", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(14, 10), "Çek Akıbeti Raporu", "Plansız çıkış kontrolü: Kasa Nakit Akışı'nda planlanmamış belgede işlem türü ciro / bankaya tahsil / teminat olarak değiştirilirse çıkış uygulanmaz, seçim eski değerine döner ve belge Kasa Nakit Akışı'na GMY onayı satırı olarak düşer (uyarı mesajı kayıt numarasını verir); onaylanınca çıkış işlenir. Planlı belgelerde çıkış doğrudan işlenir (plan ↔ ibraz kontrolü sürer).", "/CekAkibeti", "Mali İşler › Finans › Finansal Araçlar");
            Guncelleme(l, T(13, 10), "Kasa Nakit Akışı", "Ödeme talimatı, grup içi çek dolaşım senaryosu, firma bilgisi ve avans senkronu: (1) Her sekmede satır seçilip \"Seçilenlerden Talimat Oluştur\" ile ödeme talimatı hazırlanır — ödeyen şirket ve ödeme yöntemi bazında ayrı talimat (banka ödeme talimatı, çek / senet teslim-ciro talimatı, kasa ödeme talimatı …); çek talimatında planlanmış belgeler ve dolaşım planı hazır gelir; Talimatlar sekmesinde durum akışı (Hazırlandı → Onaylandı → Bankaya İletildi / Teslim Edildi → Gerçekleşti) ve yazdırılabilir belge (şirket başlığı, \"Şubeniz nezdinde bulunan … hesabımızdan\" metni, tablolar, konkordato komiser heyeti imza bloğu). Talimat gerçekleşince satırlar ÖDENDİ olur, çekler plana göre ciro / ibraz edilir, avanslar teslim edilir. (2) Çek / Senet belgesi için \"Dolaşım Planla\": çekin hangi grup şirketlerinden geçeceği (ör. Selvi → Uras Kimya → URS Makine → Uras Holding → Alv Kimya) ve son adım (tedarikçiye ciro / bankaya ibraz) seçilir, uygunluk simülasyonu her adımda grup içi borcun kapanıp kapanmadığını ve bakiyenin şişip şişmeyeceğini gösterir, \"Otomatik Öner\" mevcut borç ilişkilerinden zincir önerir; plan kaydedilir, adımlar gerçekleştirildikçe çek alan şirketin portföyüne geçer, grup içi bakiyeler güncellenir ve hareketler Konsolide Finansal Takip Paneli › Çek sekmesinde (planlı adımlar onay bekleyen PLAN satırı olarak) görünür. Örnek senaryo tohumda: Alv Kimya'nın faturası Selvi çekiyle, ilk iki adım gerçekleşmiş. (3) Portföyden belge seçimi: portföy şirketi (başka grup şirketinin portföyü de), vade / tutar / banka süzgeçleri, sıralama, planlıları gösterme, \"Tutara Yakın Seç\". (4) Sütun başlıkları tam ad (Planlanan Ödeme Tarihi, Ödenecek Cari, Fatura / Sipariş No, Ödeme Durumu, Ödenme Tarihi, Ödenen Tutar …); her satırda Fatura Sahibi / Ödeyen Şirket sütunu (ikisi farklı olabilir), çekmecede seçilir. (5) Nakit Avans modülünde onaylanan avanslar Nakit sekmesine otomatik satır olarak düşer (kurumda personel, belge no avans no, fatura sahibi masraf şirketi); satır ÖDENDİ olunca ya da talimat gerçekleşince avans modülünde teslim edilmiş sayılır ve Bekleyen Ödemeler listesinden düşer; modülde teslim edilen avans burada ÖDENDİ olur. Uras Holding şirket listesine eklendi.", "/Rapor79?sekme=cek", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(13, 10), "Konsolide Finansal Takip Paneli", "Çek sekmesinde grup içi dolaşım hareketleri: Kasa Nakit Akışı'ndaki dolaşım planının gerçekleşen her adımı ciro eden şirkette çıkış, alan şirkette giriş satırı (adım n/N, plan özeti, ciro belge no); gerçekleşmemiş adımlar onay bekleyen \"PLAN\" satırları olarak listelenir, böylece planlanan dolaşım ile gerçekleşen izlenir.", "/Rapor123?hesapTipi=CEK", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(12, 10), "Kasa Nakit Akışı", "Ekran portalın modern rapor diline taşındı (eski 23 sütunlu görünüm \"Eski Görünüm\" düğmesiyle /Rapor79/Eski'de duruyor): şirket, tarih aralığı, durum, satınalmacı ve arama filtreleri; sekiz gösterge (dönem toplamı, ödenen, kalan, bu hafta vadesi gelen, geciken, banka + kasa mevcudu, çek / senet portföyü, net nakit durumu); ödeme yöntemi sekmeleri (Tümü, Nakit, Çek, Senet, Havale / EFT, Kredi / Banka Kartı, Mahsup, Temlik, Yansıtma, Diğer, Bakiye · Projeksiyon, Günlük) — her sekmede yalnız o yöntemin sütunları, sıkı yazı ve tek satırlı hücrelerle 12+ sütun ekrana sığar. Durum, planlanan tarih ve yönteme özel alanlar satırda düzenlenir ve anında kaydedilir; satıra tıklayınca çekmecede tüm alanlar, dekontlar ve kayıt günlüğü; Yeni Ödeme çekmeceden açılır. Mahsup, Temlik ve Yansıtma sekmeleri Grup İçi Özel Finansal İşlemler modülleriyle CANLI bağlı: satır modül kaydına bağlanır (\"Kayıt Seç\"), kurum / tutar / tarih kayıttan alınır, durum, muhasebe ve kontrol her açılışta modülden okunur, kayıt bağlantıyla modülde açılır; sekmenin üstünde modül özeti (toplam, açık, onay bekleyen) ve Grup İçi Özel Finansal İşlemler Raporu bağlantısı. Yansıtma yeni ödeme yöntemi olarak eklendi.", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(12, 10), "Kasa Nakit Akışı (Eski Görünüm)", "Ödeme listesi ödeme yöntemine göre sekmelere ayrıldı: Tümü (ana 23 sütunlu liste), Nakit, Çek, Senet, Havale / EFT, Kredi / Banka Kartı, Mahsup, Temlik, Diğer; her sekmede yönteme özel sütunlar (Havale / EFT: banka hesabı, alıcı IBAN, dekont no · Nakit: kasa, makbuz no, teslim alan · Kredi Kartı: kart, taksit, ekstre dönemi · Mahsup: fiş no, karşı belge · Temlik: temlik no, temlik eden; alanlar satırda düzenlenir ve anında kaydedilir). Çek ve Senet sekmelerinde ödeme satırına portföyden belge seçilir (\"Belge Seç\": planlanmamış, kullanılabilir belgeler; arama, çoklu seçim, satır tutarıyla fark); seçilen belgenin çek no, bankası, keşideci, kimden geldiği, vadesi, tutarı ve akıbeti sütunlarda görünür, satır tutarı belge toplamı olur ve belge Çek Akıbeti Raporu'nda otomatik \"Planlandı\" olur (planlanan tedarikçi = satırın kurumu); \"Kaldır\" belgeyi portföye döndürür. Akıbet sütununda plan ↔ ibraz kontrolü (Uyumlu / FARKLI / İbraz Bekliyor). Ana listedeki Çek / Senet seçimi de aynı bağlantıyı kurar. Veri bellek içi (Data/NakitAkisOrnek.cs + CekAkibetOrnek.cs).", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(12, 10), "Çek Akıbeti Raporu", "Kasa Nakit Akışı ile ortak kayıt: nakit akışta satıra seçilen çek / senet burada işlem türü \"Planlandı\" ve planlanan tedarikçiyle (satırın kurumu) otomatik görünür. \"Planlananlar (Kasa Nakit Akışı)\" özet kartı eklendi; Planlanan Tedarikçi ve Açıklama sütunları varsayılan görünür (açıklamada plan kaynağı ya da ibraz / ciro bilgisi ve plana uygunluk). Portföydeki (ibraz / tahsilat belgesi olmayan) çeklerde işlem türü artık kayıt üzerinden değiştirilebilir; Ciro Edildi / Bankaya Tahsile Verildi seçilince ibraz bilgisi oluşur ve plandan farklı yere çıkış uyarı verir. İbraz ve tahsilat detaylarında plan ↔ ibraz kontrolü.", "/CekAkibeti/Index2", "Mali İşler › Finans › Finansal Araçlar");
            Guncelleme(l, T(12, 10), "Konsolide Finansal Takip Paneli", "Çek sekmesine Planlanan Tedarikçi (Kasa Nakit Akışı planı, kayıt no ve planlayan), İbraz / Ciro Bilgisi (ciro edilen tedarikçi ya da tahsile verilen banka, tarih, belge no) ve KONTROL sütunları eklendi: Uyumlu (planlanan tedarikçiye çıktı), FARKLI (plana aykırı yere çıktı; satır Eksik olarak işaretlenir), İbraz Bekliyor (planlandı, henüz çıkmadı), Plansız İbraz. Özet kartlarının altında \"Çek Plan ↔ İbraz Kontrolü\" kutusu: sayılar ve tek tıkla süzme (Farklı / Uyumlu / İbraz Bekliyor / Plansız), Kasa Nakit Akışı ve Çek Akıbeti bağlantıları. Bekleyen Talepler listesinde plana aykırı çıkan çekler. KASA / BANKA / ÇEK hareketleri bellek içi örnek veriden (ödeme planı ve çek kaydı) üretilir; Çek sekmesi artık açılabiliyor.", "/Rapor123?hesapTipi=CEK", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(5, 10), "Vade Tarihine Göre Çek ve Senet Özeti", "Verilen Çekler sekmesinde Uras Kimya 2026 tedarikçi çekleri \"2026 Bütçe Analizi\" tablosundaki (Vade Tarihine Göre Tedarikçi Aylık Çek Özeti) rakamlarla birebir: 122 cari, aylık toplamlar (Ocak 7.617.764,71 … Aralık 3.254.151,13), yıllık 116.506.525,87 TL ve her ayın çek adedi tablodaki AYLIK ÇEK ADEDİ satırına eşit (32, 39, 31, 42, 53, 45, 66, 70, 70, 61, 30, 18; toplam 557). Açılışta Şirket filtresi kullanıcının şirketi (Uras Kimya); Tümü (Konsolide) ve diğer şirketler seçilebilir, Temizle varsayılan şirkete döner. % sütunu cari satırında ödeme türü içi pay (tedarikçi payı tedarikçi toplamına; tablodaki gibi), tür satırında genel pay; tür satırlarında aylık toplamla birlikte çek adedi. Matris kuruşsuz, hücre ipucunda ve Excel çıktısında kuruşlu tam tutar. Maaş ve kira çekleri ayrı türlerde kalır (kira alıcısı \"Ofis Kirası · Mal Sahibi\").", "/CekOzet", "Mali İşler › Finans › Finansal Araçlar");
            Guncelleme(l, T(29, 9), "Müşteri Cari Kartları", "Cari durumu OTOMATİK oldu: son 1 yıl (365 gün) içinde cari hareketi varsa Aktif, yoksa Pasif. Hareket kaynakları: kart açılışı, teklif / sipariş, numune gönderimi ve teslimi, ihracat yüklemesi / belge gönderimi / tahsilat, alım faturası, ödeme, nakit avans (ad ya da cari kodu eşleşmesiyle). Kart listesinde durumun altında son hareket tarihi, detayda \"19. Durum\" yanında kaynak (otomatik / elle) ve \"Son Hareket\" satırı. \"Pasife Al\" düğmesi \"Elle Pasife Al\" oldu: otomatik kuralı ezer; \"Elle Pasifi Kaldır\" ile kural yeniden geçerli olur (1 yıl hareket yoksa kart Pasif kalır). Tedarikçi, finansal, resmi kurum ve personel carileri için de aynı kural; teklif, numune, ihracat ve fiyat ekranlarındaki cari kart bilgileri bu durumu gösterir.", "/CariKart/Musteri", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Müşteri Portföyü");
            Guncelleme(l, T(29, 9), "Modül Sayfası", "Modül menüsü (TALEP, MALİ İŞLER … paneli) daraltılabilir: başlığın sağındaki sol ok menüyü dar bir dikey şeride indirir, içerik tam genişlik alır; şeritteki sağ ok geri açar. Tercih tüm modüllerde ortaktır ve tarayıcıda saklanır.", "/Modul/talep", "Talep");
            Guncelleme(l, T(29, 9), "Rapor Teması", "Yan paneller daraltılabilir: liste / özet / parametre sütunu olan ekranlarda (Cari Mutabakat, Mahsup, Temlik, Yansıtma, Grup İçi Rapor, Nakit Avans, İzin ve talep modülü, Cari Kart Talebi, Fiyat / Kâr, Yetki Yönetimi, Kalem ve Muhatap Ana Verileri, Dönem Sonu Kapanış, Toplu Üretim, Tahsilat / Ödeme / İbraz UDF panelleri, Cari Açılış Formu, Toplu Kalem Güncelleme) panel başlığındaki ok sütunu dar bir şeride indirir, ana çalışma alanı tüm genişliği alır; şeritteki ok geri açar, tercih tarayıcıda saklanır. Açıklama kutuları gizlenebilir: üst çubuktaki bilgi (i) düğmesi tüm raporlardaki başlık altı açıklamaları, sabit not paragraflarını ve bilgi kutularını tek tıkla gizler / gösterir; tercih tarayıcıda saklanır ve açık sekmelere anında uygulanır. Rapor başlıklarındaki ikonlu rozetler ve akış kutuları tıklanabilir oldu: ilgili sekmeye geçip filtre alanına gider ve alanı kısa süre vurgular (ör. \"Konsolide · 6 Şirket\" → liste sekmesi, şirket filtresi) ya da ilgili ekranı sekmede açar (ör. \"Cari Kart Bilgileriyle\" → Müşteri Cari Kartları; Fiyat / Kâr ekranındaki satıcı ve müşteri kutuları → cari kart). Davranış ortak (rapor-tema.js, data-git / data-url): Müşteri Teklifleri, Numune Gönderim, İhracat Belge, Fiyat / Kâr ve Yapılan Ödemeler ekranlarında uygulandı.", "/FiyatYonetimi", "Yönetim › Yönetim Özeti › Fiyat ve Kâr Yönetimi");
            Guncelleme(l, T(29, 9), "Rapor Tabloları", "Tüm raporlarda tablo hücreleri ve başlıkları yatayda ve dikeyde ortalandı (ana ERP raporlarındaki düzen). Sola yaslı metin ile sağa yaslı sayı / tarih / kod sütunları yan yana gelince değerler komşu sütuna kaymış görünüyordu; tema betiği tarih ve kod hücrelerini de sayı sanıp sağa itiyordu. İkon ve rozetler hücre içinde dikeyde ortalı. Müşteri Teklifleri, Numune Gönderim, İhracat Belge ve Fiyat / Kâr ekranlarında satırlar tek satıra sabitlendi (hücreler kırılmaz, tablo gerekirse yatay kayar); satır yükseklikleri eşitlendi.", "/MusteriTeklif?sekme=liste", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Teklif Yönetimi");
            Guncelleme(l, T(29, 9), "Müşteri Fiyat ve Kâr Oranları", "\"Üretici Liste Fiyatı ($)\" ve \"Üretici Listesine Göre\" sütunları kaldırıldı (ayrı liste fiyatı kavramı yok; fiyatlar yalnız maliyet + kâr oranından türer). Ana para birimi USD oldu: üretim maliyeti ve satıcı alış fiyatı $ üzerinden hesaplanır; \"Kâr (TL)\" ve \"Liste Fiyatı / Listeye Göre\" sütunları Yetkili Satıcı Fiyatları tablosundan kaldırıldı. Müşteri Fiyatları sekmesine \"Kur ve Döviz Kâr Marjı\" kartı (USD/TL ve EUR/TL piyasa kuru + döviz kâr marjı %; fiyatlandırma kuru piyasanın marj kadar üstünde alınır, yalnız Yönetici kaydeder) ile müşteriye satış fiyatının € ve ₺ sütunları eklendi; kur değişiklikleri günlüğe yazılır. Satıcı Alış Fiyatı iki sekmede de $ ve ₺ olarak gösterilir. Sütun adları netleştirildi: \"Satıcı Alış Fiyatı\" (Uras Kimya → satıcı), \"Müşteriye Satış Fiyatı\" (satıcı → müşteri), \"Üretici Liste Fiyatı\" (Uras Kimya tavsiye); tabloların üstünde kimden kime olduğunu yazan grup başlığı satırı var.", "/FiyatYonetimi?sekme=musteri", "Yönetim › Yönetim Özeti › Fiyat ve Kâr Yönetimi");
            Yeni(l, T(28, 9), "İhracat Belge Gönderim Takibi", "Satış ve Operasyon › Yurtdışı Satış › İhracat Operasyon Takibi altında (Yönetim › Özel Raporlar'da aynı ekran): ihracat operasyonunun kargo firmalarıyla gönderdiği belgelerin konsolide takibi — akreditif ibraz setleri (amir bankaya DHL Express ile), vesaik tahsili evrakları, müşteriye / forwarder'a giden orijinal konşimento ve dolaşım belgeleri, konsolosluk ve ticaret odası tasdik gönderileri. Her gönderimde ihracat dosyası ve fatura, ödeme şekli, akreditif no / amir banka / ibraz son tarihi, alıcı, belge seti (tür, no, adet, orijinal / kopya), kargo firması, gönderim (takip) numarası ve takip sayfası bağlantısı, masraf (döviz / TL), gönderen operasyon uzmanı, kargo hareketleri, teslim, banka sonucu (uygun / rezerv / ödendi) ve ibraz riski (süresinde / kritik / geç ibraz). Aylık Özet, Müşteri Bazlı (CARİ_MASTER sütunlarıyla) ve Gönderim Listesi sekmeleri; ibraz riski listesi, Şirket × Amaç ve Ay matrisleri, kargo ve belge türü dağılımı, detay drawer'ı, Excel.", "/IhracatBelge", "Satış ve Operasyon › Yurtdışı Satış › İhracat Operasyon Takibi");
            Yeni(l, T(28, 9), "Numune Gönderim Takip Raporu", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Numune Yönetimi altında (Yönetim › Özel Raporlar'da aynı ekran): tüm grup şirketlerinin müşterilere gönderdiği yurtiçi ve yurtdışı numunelerin konsolide takibi — gönderim tarihi, gönderen şirket, cari kart bilgileri, alıcı kişi / adres, gönderen satış temsilcisi, amaç, numune kalemleri (parti / lot, miktar) ve gerçek bedeli, kargo firması (DHL Express, UPS, FedEx, TNT, Turkish Cargo, Yurtiçi / Aras / MNG / Sürat Kargo, şirket aracı), gönderim (takip) numarası ve takip sayfası bağlantısı, ağırlık / desi, gönderim masrafları (kargo faturası döviz / TL, gümrük müşavirliği / ihracat beyannamesi, sigorta; masraf kime), kargo hareketleri, tahmini / gerçek teslim, teslim alan, numune irsaliyesi / proforma / beyanname, sonuç ve geri bildirim (numune → teklif → sipariş bağlantısı Müşteri Teklifleri ile). \"Aylık Numune Özeti\" sekmesi ay ay gönderim adedi (yurtiçi / yurtdışı), numune bedeli, kargo / gümrük / sigorta masrafları, toplam maliyet, teslim, teklife ve siparişe dönen, dönüşüm oranı, ortalama masraf ve teslim süresini 12 ay + Toplam + Aylık Ort. düzeninde şirket, kargo firması, temsilci ve amaç kırılımıyla verir; \"Müşteri Bazlı\" sekmesi CARİ_MASTER sütunlarıyla müşteri başına özettir. Filtreler, KPI kutuları, Şirket × Bölge ve Ay matrisleri, kargo dağılımı, en çok numune gönderilen 10 müşteri, detay drawer'ı, Excel (liste, kalem, özet).", "/NumuneGonderim", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Numune Yönetimi");
            Yeni(l, T(28, 9), "Müşteri Teklifleri", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Teklif Yönetimi altında (Yönetim › Özel Raporlar'da aynı ekran): tüm grup şirketlerinin müşterilere verdiği tekliflerin konsolide listesi — teklif no, şirket, cari kart bilgileri (kod, ünvan, VKN, sınıf, bölge, ilişki durumu, satış temsilcisi, vade şartı), teklif kalemleri, tutar / para birimi / TL karşılığı, geçerlilik, durum (Gönderildi, Revize Edildi, Satışa Döndü, Reddedildi, Süresi Doldu), sipariş ve fatura bilgisi. \"Aylık Teklif Özeti\" sekmesi ay ay verilen teklif (adet / tutar) ile satışa dönen (adet / tutar) ve dönüşüm oranını 12 ay + Toplam + Aylık Ort. düzeninde şirket ve temsilci kırılımıyla gösterir; \"Müşteri Bazlı\" sekmesi CARİ_MASTER sütunlarıyla müşteri başına teklif / dönüşüm özetidir. Filtreler, KPI kutuları, Şirket × Durum ve Ay × Dönüşüm matrisleri, kaybetme nedenleri, en büyük 10 müşteri, teklif detayında kalemler + cari kart bilgileri + müşterinin teklif geçmişi, Excel.", "/MusteriTeklif", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Teklif Yönetimi");
            Guncelleme(l, T(2, 11), "Konsolide İK Paneli", "R / X ayrımı raporun her yerinde altlı üstlü: Birleşik Tablo'da Yol, Yemek, Mesai, Prim ve Kesintiler sütunları artık R + X toplamı yerine üstte R (bordrolu), altta X (bordro dışı) gösterir (ana tablodaki R / X değerleriyle birebir; dip toplam ve KPI'daki Kesintiler de R / X). İşten Çıkış Senaryosu'nda Ek Ödemeler ve Kesintiler, Ek Çalışmalar'da Toplam Ek Çalışma, Prim Ödemeleri'nde Dönem Primi / Tablodaki Prim / Fark aynı biçimde (fark R ve X için ayrı ayrı \"Uyumlu\"). Toplanmış tek rakam R ile X'i karıştırdığından kaldırıldı; satır bağları (Net Toplam + Ek Ödemeler − Kesintiler = Net Ödenen) R + X toplamıyla aynen tutar. Excel çıktıları da iki satırlı hücreyle.", "/PersonelMaliyet?sekme=birlesim", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(2, 11), "Konsolide İK Paneli", "Özet Raporu'na \"Kapsam Mutabakatı\" kartı eklendi: kırılım toplamının Personel Maliyet Tablosu + Özel Kişiler + Üretim Personeli (SGK'sız gündelikçi) satırlarından oluştuğu kişi sayısı ve X-Net / R-Net / Toplam Net / Genel Maliyet toplamlarıyla gösterilir (her satır kendi sekmesinin dip toplamıyla aynıdır, tıklayınca sekmeye gider); SGK'lı gündelikçiler bilgi satırında (hak ediş − bordro Net-R mahsup = elden X → bordro satırının X-Net'i; toplama ayrıca girmez), aynı ad iki kaynakta geçerse \"Mükerrer\" uyarısı, aksi halde \"Mutabık · Mükerrer Yok\". Düzeltme: SGK'lı gündelikçilerin elden X farkı yalnız güncel dönemin (Kasım 2026) bordro satırına yazılıyordu; Ekim ve Eylül 2026'da bu kişilerin X-Net'i 0 kalıyor, Özet / Birleşik Tablo / İşten Çıkış toplamları eksik çıkıyordu. Artık her dönem kendi Net-R mahsubuyla hesaplanıp o dönemin satırına yazılır; Üretim Personeli sekmesindeki R Mahsup / Elden X / Net Ödenen sütunları da seçili döneme göredir. Özet Excel'ine Kapsam Mutabakatı sayfası eklendi.", "/PersonelMaliyet?sekme=ozet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(2, 11), "Konsolide İK Paneli", "Excel çıktıları ekrandaki tasarımla birebir: tüm sekmelerdeki Excel düğmeleri artık düz CSV yerine biçimli .xlsx indirir — sütun grupları birleşik başlık hücresi, koyu başlık satırları, R üstte / X altta hücreler iki satırlı ve renkli (R yeşil, X turuncu), tutarlar gerçek sayı + ₺ biçimi (toplanabilir), hesaplanan / genel maliyet sütun zeminleri, işten ayrılan satırı üstü çizili, emekli / engelli rozetleri, dip toplam satırı mavi zeminli; başlık satırları ve Sıra'dan Adı-Soyadı'na kadar olan sütunlar Excel'de de dondurulmuş; \"0 ₺ Sütunları Gizle\" ile gizlenen sütunlar ve Kart sütunu dosyaya girmez; sayfanın üstünde sekme başlığı, dönem · sayaç · tarih · hazırlayan, KPI kutuları (renk çubuğuyla), altında ekrandaki açıklama notu; çok tablolu sekmelerde (Ek Çalışmalar, Diğer Kesintiler, Muhasebe Kayıtları, Özet Raporu) her tablo ayrı sayfa; yatay A4 tek sayfa genişliğine sığar, başlık satırları her yazdırma sayfasında yinelenir. Aynı bileşen Personel Muhasebe İşlemleri ekranının Excel düğmelerinde de kullanılır.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(3, 11), "Konsolide İK Paneli", "Eksik kalemler eklendi: Prim ve Ek Kazançlar grubuna Kasa Tazminatı (brüt, SGK matrahı ve gelir vergisine girer), Diğer Kesintiler grubuna Mazot Kesintisi ve İhbar Kesintisi (bordro kesintisi: bankaya yatan neti azaltır, personelden alacak olarak muhasebeye yazılır). Üç sütun ana tabloda, kartta ve Excel'de yer alır; Birleşik Tablo, Özet, İşten Çıkış ve Ödeme ekranlarında Prim ve Kesintiler toplamlarına dahil edilir. Diğer Kesintiler sekmesinde kişi özetine ve KPI'ya eklendi; kesinti planları Mazot ve İhbar türleriyle kişinin sütununa yansır. Eylül 2026'da üç kalem de 0'dır.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(3, 11), "Personel Muhasebe İşlemleri", "Bordro tahakkuku Mazot ve İhbar kesintilerini personelden alacak (136.01) olarak içerir; Gider Kataloğu'na Kasa Tazminatı (GDR.13.06.04) eklendi.", "/PersonelMuhasebe", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(3, 11), "Personel Muhasebe İşlemleri", "Net ödeme kanalları ayrıldı: R (banka) ödemeleri Uras Power'dan, X (elden) ödemeleri personelin fiili görev yeri şirketinden planlanır; SGK işvereniyle aynı değilse iki şirket için karşılıklı fiş oluşur. Ödeme Yapılmıyor listesi ve personel filtreleri R ve X ödeme şirketlerini birlikte gösterir.", "/PersonelMuhasebe", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(3, 11), "Konsolide Finansal Takip Paneli", "Başlıktaki \"Kasa · Banka · Çek Hareketleri\" ve \"Finekra → Banka Hareketleri · Onay → Muhasebe Fişi\" açıklama kutuları kaldırıldı; hızlı geçiş bağlantıları tek sırada: Kasa Nakit Akışı ↔ Eşleşme, Vade Tarihine Göre Çek ve Senet Özeti (/CekOzet), Bütçe Raporu (/Butce) ve Çek Akıbeti. Yeni eklenen iki bağlantı mevcut sayfalara gider.", "/Rapor123", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(3, 11), "Konsolide İK Paneli", "İşten Çıkış Senaryosu: Net Toplam üstte R-Net, altta X-Net olarak gösterilir; Kesintiler sütunu kaldırıldı; Net Ödenen yerine Ara Toplam geldi (Personel Maliyet Tablosu ile aynı). Toplam Brüt Masraflar ana tablo değeriyle aynı oldu; Ara Toplam + Toplam Brüt Masraflar + Toplam İşveren = Aylık Genel Maliyet tutar. Kıdem, ihbar, yıllık maliyet ve çıkış maliyeti değişmedi.", "/PersonelMaliyet?sekme=cikis", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Birleşik Personel Maliyeti: SGK İşvereni / Ödeyen sütunu kaldırıldı (arama kutusu işverene göre aramaya devam eder); Net Ödenen tek sütun yerine Net Ödenen R (bordrolu, bankaya ödenen) ve Net Ödenen X (bordro dışı, elden ödenen) olarak ayrıldı; toplam tutarlar değişmedi.", "/PersonelMaliyet?sekme=birlesim", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Birleşik Personel Maliyeti: Kişi, Net Ödenen, Toplam Brüt Masraflar, Toplam İşveren ve Genel Maliyet kutuları kaldırıldı; bu bilgiler tablo sütunları ve alt toplamda yer alır. Net Ödenen Toplam sütunu eklendi (R + X). Tüm sekmelerde R ve X birlikte yazılan sütunların alt toplamında R, X ve TOPLAM (R + X) üç satır gösterilir.", "/PersonelMaliyet?sekme=birlesim", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Özet Raporu: Departman Bazında Mevcut ve Kalan (mevcut kişi, işten çıkacak, kalan), Departman ve Görev Bazında Kalan ve Zam Senaryoları tabloları eklendi; işten çıkacak sayısı İşten Çıkış Senaryosu işaretlerinden gelir. Zam Senaryosu'nda Senaryo adı kutusu Toplu R % kutusu ile aynı yükseklikte. Kırılım tablosu en üste alındı; kartlar iki sütunlu akışta dizilerek boş alan azaltıldı; Zam Senaryosu tablosunda ince sütun çizgileri var. Departman tablolarında kişi sayısının yanına aylık maliyet (Mevcut ₺, Çıkacak ₺, Kalan ₺) sütunları eklendi.", "/PersonelMaliyet?sekme=ozet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Raporların Excel düğmesinin yanında PDF düğmesi var (Özet ve tüm sekmeler; Personel Muhasebe İşlemleri de dahil). PDF, ekrandaki tabloyu yatay A4 sayfalara döker: başlık ve sayfa numarası her sayfada, KPI kutuları ilk sayfada; geniş tablolar sütun gruplarına bölünür ve sabit sütunlar her grupta tekrarlanır.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Tablo başlıkları sözcük bazında sarar, sütunlar içeriğe göre daralır (Ödeme Planı dahil); tireli sözcükler (Toplam-R gibi) bölünmez. Kutucuklar tüm sekmelerde aynı yükseklikte tek satırda; Muhasebe Kayıtları'nda kontrol kutuları tek kutuda toplandı. Özet'te Kırılım etiketi okunur renkte.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Tüm rapor sekmelerinde sütun bölmeleri tek standartta: bölme yalnız sütun grubunun başında 2 px açık gri çizgidir ve başlık, gövde ile toplamda aynı yerdedir; hücreler arasında dikey çizgi yoktur. Zam Senaryosu'nun sütun çizgileri kaldırıldı; Ek Çalışmalar, Diğer Kesintiler, Prim, Üretim, Birleşik Tablo, İşten Çıkış, Ödeme ve Özet tablolarına aynı bölmeler eklendi.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide Finansal Takip Paneli", "Tüm sekmelerde tablolara sütun arası ince dikey çizgi eklendi (başlık ve gövde aynı renk; son sütunda çizgi yok).", "/Rapor123", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(4, 11), "Kasa Nakit Akışı", "Tüm sekmelerde tablolara sütun arası ince dikey çizgi eklendi (başlık ve gövde aynı renk; son sütunda çizgi yok).", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(4, 11), "Konsolide Finansal Takip Paneli", "Sekme adlarındaki sayılar kaldırıldı. Tablo sütunları başlıkla aynı hizada: her hücre ortada, ilk satırlar aynı çizgide. Tutarlar ₺ ile gösterilir; dövizli tutarlar $ ya da € işaretiyle yazılır. Başlıklar alta hizalı; iki satırlı başlıkta üst satır kısa, alt satır uzun.", "/Rapor123", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(4, 11), "Kasa Nakit Akışı", "Sekme adlarındaki sayılar kaldırıldı. Tablo sütunları başlıkla aynı hizada: her hücre ortada, ilk satırlar aynı çizgide. Tutarlar ₺ ile gösterilir; dövizli tutarlar $ ya da € işaretiyle yazılır. Başlıklar alta hizalı; iki satırlı başlıkta üst satır kısa, alt satır uzun.", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(4, 11), "Bütçe Raporu", "Tutarlar ₺ işaretiyle gösterilir; tablo hücreleri ortada hizalı, başlık ile gövde aynı hizada. Başlıklar alta hizalı; iki satırlı başlıkta üst satır kısa, alt satır uzun.", "/Butce", "Mali İşler › Finans › Bütçe ve Planlama");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Personel kimlik bilgileri resmi Ekim 2026 ücret bordrolarından tamamlandı (tüm dönemlerde, tüm İK ekranlarında aynı): 88 bordrolu kişinin Sicil Numarası ve SGK Numarası resmi bordrodaki değerlerle yazıldı (önce örnek biçimde üretiliyordu), bordronun şirkete özel departmanı nota eklendi; boş Departman Kodu / Açıklaması bölümden dolduruldu. Ekim'de işe giren Büşra Alişarlı ve Dilanur Sönmez (Selvi Kimya, bordro departmanı Yönetim; 27 prim günü → işe giriş 5 Ekim 2026) ile Kamran Cabbarov (Uras Kimya Üretim; 6 prim günü → 26 Ekim 2026) için bölüm, çatı departman ve işe giriş türetildi; görev ve unvan varsayım olarak yazıldı ve notlandı. TC kimlik, telefon, e-posta ve gündelikçilerin işe giriş tarihi kaynaklarda bulunmadığından boş bırakıldı.", "/PersonelMaliyet?sekme=cari", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Ödeme Planı'na \"Şirket Bazında Toplu Ödeme · Finansa Gönderim\" tablosu eklendi: ödenecek satırlar fiili görev yeri şirketine göre (yansıtma esası) toplanır; her şirket için kişi sayısı, bankadan ödenecek (R), elden ödenecek (X) ve toplam. \"Kasa Nakit Akışı'na Gönder (Toplu)\" şirket başına iki satır yazar: R → Havale / EFT (İşlem Tipi R), X → Nakit (İşlem Tipi X, nakit onayı). Aynı dönem / şirket / kanal tek satır (tutar değişince yeniden gönderilir, ödenmişe dokunulmaz); \"Gönderimi Geri Al\" ödenmemiş satırları kaldırır. Tabloda Kasa Nakit Akışı satır numarası, durumu (Planlandı · Nakit Onayı Bekliyor · Ödendi) ve bağlantısı görünür; Alv Filo ve Uras Power Kasa Nakit Akışı'nda tanımlı olmadığından gönderilmez. Excel çıktısına ikinci sayfa olarak girer.", "/PersonelMaliyet?sekme=odeme", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Kasa Nakit Akışı", "Konsolide İK Paneli › Ödeme Planı'ndan gönderilen şirket bazlı toplu personel maaş ödemeleri satır olarak gelir: \"Personel Maaş Ödemesi · <dönem> · Banka (R)\" Havale / EFT ve \"… Elden (X)\" Nakit (nakit onayı bekler); bağlı belge tipi Personel Ödemesi, İşlem Tipi R / X. Aynı dönem / şirket / kanal için tek satır; panelden yeniden gönderilince ödenmemiş satırın tutarı güncellenir.", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Ödeme Planı'na Gerçekleşen Ödeme eklendi: her satırda planlanan banka / elden tutarın yanında Ödenen (Banka), Ödenen (Elden), Fark (Banka), Fark (Elden) ve Gerçekleşen Durum (Girilmedi · Tam Ödendi · Eksik Ödendi · Fazla Ödendi). Hücreye tıklayınca fiilen ödenen tutar, ödeme tarihi ve not girilir; \"Planlanan Tutarları Yaz\" aynı tutar ödendiyse tek tıkla doldurur. Dip toplamda ödenen ve fark toplamları, kutularda Gerçekleşen Ödeme ve Ödeme Farkı. Girişler dönem bazında sunucuda kalıcı (yeniden başlatınca korunur).", "/PersonelMaliyet?sekme=odeme", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "SGK'lı gündelikçide elden mahsup farkı (günlük ücret × gün + fazla mesai + tatil + yemek + yol + diğer − bordro Net-R) artık kişinin Personel Maliyet Tablosu satırındaki X-Net'e yazılır (kullanıcı onayı); kira ayrıca Kira Desteği-X'te. Fark elden ödemeye, Ödeme Planı'na, Birleşik Tablo'ya ve genel maliyete girer; her dönem kendi Net-R'sine göre hesaplanır. Önce kaynak tabloyla birebirlik için X-Net 0 tutuluyordu (Eylül 2026 kaynak raporundan farklılaşır).", "/PersonelMaliyet?sekme=uretim", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Gündelikçi Üretim Personeli adları \"Gündelikçi Ücretleri 2026 – 09.11.2026\" listesindeki gibi ad-soyad yazıldı (Muharrem Abdullayev, Sinan Cabbarzade, Elşad Necefov, Çoşkun Cabbarzade, Araz Nagiyev, Savalan Ağazade, Ayhan Musayev, Reşat Aliyev, Ali Mahmudov, Naim Şoev, Ruslan Hüseynov, Aslan Hüseynov); \"Kamuran\" = Kamran Cabbarov (26 Ekim 2026'dan itibaren Uras Kimya bordrosunda: Ekim'de SGK'lı gündelikçi, hak edişten bordro Net-R mahsup edilir; Eylül'de SGK'sız). Günlük ücretler aynı. Elman Abbaslı yeni listede yok; Ekim bordrosunda olduğundan satırı korundu (ayrıldıysa kişi kartından İşten Ayrıldı yapılır). Her gündelikçinin artık kişi kaydı var: SGK'sız 11 kişi için bordro dışı kayıt (cari kodu 335.901–335.911, Özel Durum Gündelikçi, D30, SGK işvereni = çalıştığı şirket) açıldı; tutarları Üretim satırından gelir ve her okumada oradan yazılır. Yeni eklenen SGK'sız üretim satırı için kayıt otomatik açılır. Toplamlar değişmedi (Ekim genel maliyeti yalnız Kamran'ın bordro günleri kadar, 8.422,65 ₺ düşer).", "/PersonelMaliyet?sekme=uretim", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Personel Carileri", "SGK'sız gündelikçi üretim personelinin de cari kartı var (335.901–335.911; Konsolide İK Paneli'ndeki bordro dışı kayıttan): şirket çalıştığı şirket (Uras Kimya / ALV Kimya), görev Üretim Personeli, Özel Durum Gündelikçi. Adlar 09.11.2026 gündelikçi listesindeki gibi.", "/CariKart/Personel", "İK ve İdari İşler › İnsan Kaynakları");
            Guncelleme(l, T(9, 11), "Personel Dosyası", "SGK'sız gündelikçi üretim personelinin de personel dosyası var (Konsolide İK Paneli bordro dışı kaydından; cari 335.901–335.911); telefon / e-posta / işe giriş buradan girilebilir, panelle çift yönlü.", "/PersonelDosya", "İK ve İdari İşler › İnsan Kaynakları");
            Yeni(l, T(11, 11), "İhracat Finansal Takibi", "İhracat Tahsilat Raporu ile İBKB Beyanname Takibi tek, konsolide (tüm şirketler) ve dinamik raporda birleşti: İhracat Satışları (Yurtdışı Satış Siparişi'nden canlı; dosyası olmayan faturadan tek tuşla İBKB dosyası), Beyanname / İBKB Dosyaları, Banka Tahsilatları (bankadan gelen döviz girişi hangi ihracat dosyası / GÇB ile eşleşecek seçilir; seçimde \"İBKB oluşturulsun mu?\" sorulur, DAB satırı dosyaya yazılır), İBKB Belgeleri (bankaya verilecek basılabilir başvuru formu, banka İBKB no / durum takibi), Müşteri Bazlı, Vade Takibi, DAB Bağlantıları. Eski /Ibkb adresi buraya yönlenir.", "/IhracatFinans", "Mali İşler › Finans › Döviz ve Dış Ticaret Finansmanı");
            Guncelleme(l, T(11, 11), "İhracat Finansal Takibi", "CARİ BAKİYELER (MİZAN) sekmesi: muhasebe cari hesaplarındaki (mizan 120 yurtdışı müşteri hesapları; Cari Mutabakat Yönetimi ile aynı kaynak) ihracat cari bakiyeleri döviz bazında (net, TL karşılığı, açık fatura adedi, en eski açık fatura ve bakiye yaşı, son hareket, son mutabakat, mutabakat durumu) gelir ve her cari için bu rapordaki İBKB dosyalarının açık kalanıyla (gerçek bedele göre) karşılaştırılır; Fark sütunu bakiye − dosya kalanı (artı: dosyası açılmamış ihracat / eksik tahsilat kaydı, eksi: dosyaya bağlanmamış tahsilat). \"Kontrol Et\" ile Uyumlu / Fark Var / Açıklama Bekliyor + not kalıcı kaydedilir (kim, ne zaman); son kontrol 30 günü geçince satır \"Kontrol Gecikti\", hiç kontrol edilmemişse \"Kontrol Yok\" olur (sarı), fark kırmızı, uyumlu yeşil. Özet şeridinde kontrol bekleyen ve farklı cari sayısı; Kontrol Durumu filtresi; dosya sayısına tıklayınca Beyanname / İBKB Dosyaları o müşteriye daralır; Cari Mutabakat Yönetimi bağlantısı. Dosya bağı cari koduyla ya da müşteri adıyla kurulur; Excel listelerindeki 120.02.xxx kodları cari kartlarla eşleşince bağ otomatik oluşur. ÖZET sekmesi ihracata dair tüm özetleri toplar: Şirket × Yıl, YIL × SATIŞ TEMSİLCİSİ ihracat rakamları (dosya, müşteri, beyanname tutarı, ABD $ karşılığı, gereken / getirilen / kalan, açık dosya ve aynı yılın yurtdışı satış siparişleri; temsilci dosyadaki Satış Temsilcisi alanından, yoksa müşteri cari kartının satış temsilcisinden, yoksa \"Atanmadı\"), İhracat Satışları özeti (yıl × şirket: sipariş, yüklendi / faturalandı, tutar, TL, kg, İBKB dosyası var / yok, eşik altı), Banka Tahsilatı · İBKB özeti (yıl × banka: tahsilat, açık / eşleşti / İBKB düzenlendi, belge durumları), Ülke bazında (Ek-2 muaf · Ek-3 %50 kuralı), Cari Bakiye özeti (döviz bazında), Döviz, DAB / Takip durumu ve Aylık akış; sayılar tıklanınca ilgili sekme açılır. Sekme şeridindeki \"… dosya · … şirket · … açık\" kapsam yazısı kaldırıldı. Ayrıca Beyanname / İBKB Dosyaları ve Müşteri Bazlı'da GERÇEK İHRACAT BEDELİ (beyanname bedeli ile proforma / fatura bedeli farklı olabilir; fark nedeni, gereken ve kalan gerçek bedele göre, \"Bedel Farkı\" takip durumu) ve Banka Tahsilatları'nın Açık / Tamamlanan (eşleşmiş, İBKB'si düzenlenmiş) ayrımı.", "/IhracatFinans?sekme=bakiye", "Mali İşler › Finans › Döviz ve Dış Ticaret Finansmanı");
            Guncelleme(l, T(11, 11), "İhracat Finansal Takibi", "ŞUBE BAKİYELERİ sekmesi: yurtdışındaki kendi şubelerimiz (Fas Boya · Uras Kimya, Fas Kağıt · Avrupa Paper, Tunus, Cezayir, ABD, Meksika, Mısır, Portekiz, Özbekistan · Uras Kimya ve Selvi Kimya, Dubai) tek sayfada; satış temsilcilerinin şube carileri tablolarından (Ali Kemal Gündoğan, Erman Kaval, Vusal, Portekiz) yıl bazında sermaye, resmi fatura, gerçek mal bedeli, iade, komisyon, resmi / diğer ödeme, nakliye, diğer, düzeltme ve not aktarıldı. Bakiye = sermaye + ödemeler + düzeltme − satış esası (gerçek mal bedeli varsa o, yoksa resmi fatura − iade), yıllar boyunca birikimli (eksi: şube bize borçlu). Şubeye tıklayınca detay (yıl satırları, ödeme − satış, devir, gönderim geçmişi); \"Ekstre Gönder\" ile e-posta (mailto) ya da WhatsApp (wa.me) üzerinden şablon mesaj + ekstre bağlantısı, gönderim kaydı ve yanıt (Mutabık / İtirazlı); basılabilir ekstre / mutabakat mektubu (/IhracatFinans/SubeEkstre/{id}, Yazdır → PDF). Şube ekle / düzenle / sil, yıl satırı ekle; temsilci süzgeci. Özet'e \"Yurtdışı Şube Bakiyeleri\" kartı. Satış temsilcisi listesi (Erman Kaval, Ali Kemal Gündoğan, Sevgi Kaya, Berkan Özkan, Aksel Güler) dosya ve şube formlarında. Mısır kaynak tablosunun ara toplamları sütunlarla uyuşmadığından satır notlarıyla işaretlendi (düzeltme alanı). Sekmelerin altındaki uzun açıklama yazıları kaldırıldı.", "/IhracatFinans?sekme=sube", "Mali İşler › Finans › Döviz ve Dış Ticaret Finansmanı");
            Guncelleme(l, T(12, 11), "İhracat Finansal Takibi", "CARİ BAKİYELER (MİZAN): (1) DÜZELTME GÖREVİ ATAMA — \"Kontrol Et\" penceresinde fark görülünce düzeltmeyi yapacak kişi seçilir (portal kullanıcıları + Konsolide İK Paneli personeli; muhasebe / finans önde; e-posta, termin, öncelik, yapılacak). Kaydet'te görev kaydı yazılır, atanan portal kullanıcısıysa mesaj kutusuna düşer, e-posta cihazdaki posta uygulamasında hazır açılır (SMTP bağlanınca doğrudan gider); bağlantı (?gorev=ID) görevi doğrudan açar. Akış: Atandı → atanan \"Düzeltildi\" işaretler → muhasebeci \"Onayla\" (görev kapanır) ya da \"İade Et\" (neden zorunlu, yeniden düzeltilir); kendi düzeltmesini onaylama engellenir; yeniden atama / termin değişikliği; geçmiş kim-ne zaman. Sekmede BEKLEYEN GÖREVLER kartı (Açık / Onay Bekleyen / Bana Atanan / Tümü; termini geçen kırmızı, onay bekleyen mor) ve DÜZELTME PERFORMANSI (kişi bazında görev, açık, onay bekleyen, onaylanan, iade, termin aşımı, ortalama düzeltme ve onay süresi, zamanında %); Özet'e aynı iki kart. Cari satırında açık görev rozeti; Kontrol / Görev süzgecine Görev Açık · Onay Bekliyor · Mutabakat Gönderildi · Mutabakat İtirazlı. (2) MÜŞTERİYE MUTABAKAT GÖNDER — satırdaki uçak düğmesiyle bakiye ya da ekstre, E-posta (mailto) / WhatsApp (wa.me); alıcı cari kartındaki mutabakat yetkilisinden, mesaj şablondan (bakiye yönü, açık fatura, bedeli beklenen ihracat faturaları, ekstre bağlantısı), düzenlenebilir. Gönderim kaydı burada ve Cari Mutabakat Yönetimi günlüğünde (EMT belge no); yanıt Mutabık / İtirazlı işaretlenir, itirazda tek adımda düzeltme görevi atanır. Müşteri ekstresi (/IhracatFinans/CariEkstre?kod=…&t=jeton) portal girişi istemeden açılır: döviz bazında bakiye, hesap hareketleri, açık ihracat dosyaları; Yazdır → PDF.", "/IhracatFinans?sekme=bakiye", "Mali İşler › Finans › Döviz ve Dış Ticaret Finansmanı");
            Guncelleme(l, T(12, 11), "İhracat Finansal Takibi", "ŞUBE BAKİYELERİ: şube detayındaki yıl tablosunda Resmi Fatura, Gerçek Mal Bedeli, İade, Komisyon, Resmi / Diğer Ödeme, Nakliye, Diğer ve Toplam Ödeme tutarlarına tıklanınca o tutarı oluşturan KALEMLER açılır (satış alanlarında ihracat faturaları satır satır, ödeme alanlarında ödeme kalemleri; tarih, belge no, açıklama, tutar, not). Kaynak PDF'lerde yalnız yıllık toplam olduğundan kalemler ekrandan girilir ya da referans listesinden tek tıkla alınır (aynı yıl ve şube ülkesine ait ihracat dosyaları / bu dosyalara bağlı banka tahsilatları); yıl satırı ile kalem toplamı farkı gösterilir, \"Yıl Satırını Kalem Toplamıyla Eşitle\" ile yıl tutarı kalemlerden gelir (eski değer yıl notuna yazılır). MÜŞTERİ BAZLI: Satış Temsilcisi sütunu ve temsilci süzgeci (üst şeritte; \"Atanmadı\" seçilebilir). Cari Bakiyeler'deki \"… yurtdışı müşteri carisi · bakiye zamanı …\" açıklama şeridi kaldırıldı (sayılar kart başlığında). Excel'den gelen \"İptal Edildi\" rozeti öbür rozetlerle aynı boyda.", "/IhracatFinans?sekme=sube", "Mali İşler › Finans › Döviz ve Dış Ticaret Finansmanı");
            Kaldirma(l, T(11, 11), "İhracat Tahsilat Raporu", "İhracat Finansal Takibi'ne katıldı (Banka Tahsilatları sekmesi): bankadan gelen ihracat tahsilatları ihracat dosyasıyla eşleştirilir, İBKB belgesi oradan üretilir. Menüde adı \"(Kaldırıldı)\" rozetiyle durur.", "/IhracatFinans?sekme=tahsilat", "Mali İşler › Finans › Döviz ve Dış Ticaret Finansmanı");
            Kaldirma(l, T(11, 11), "İBKB Beyanname Takibi", "İhracat Finansal Takibi'ne katıldı (Beyanname / İBKB Dosyaları sekmesi); aynı gün kurulan gerçek kayıtlı sürüm (Excel tohumu, eşik otomasyonu, tıklanır KPI) orada sürer. Eski adres (/Ibkb) oraya yönlenir. Menüde adı \"(Kaldırıldı)\" rozetiyle durur.", "/IhracatFinans?sekme=liste", "Mali İşler › Finans › Döviz ve Dış Ticaret Finansmanı");
            Guncelleme(l, T(11, 11), "İBKB Beyanname Takibi","Üretilmiş ön yüz iskeleti yerine GERÇEK KAYITLI, DİNAMİK rapor (Finans ↔ İhracat köprüsü): ihracat departmanının IMKB_LISTELERI.xlsx dosyası (2025-URAS 186, 2026-URAS 23, 2026-SELVİ 125 ihracat dosyası) tohum olarak yüklendi. Her ihracat dosyası için şirket, dosya no, müşteri (kod + ad), başlangıç / kapanış, GÇB no, beyanname tutarı ve dövizi, ülke gerekliliği (%), DAB / İBKB durumu (Bekliyor · Yapıldı · Peşin Yapıldı · Kısmi · Gerek Yok · İptal), banka, bağlanan DAB satırları; hesaplanan gereken / getirilen / kalan bedel, 180 gün vade ve kalan gün, takip durumu (Açık · Vade Yaklaşıyor · Vadesi Geçti · Kısmi · Kapandı · Muaf). Sekmeler: Özet (KPI, şirket × yıl, döviz, durum dağılımı, aylık), Dosya Listesi (filtre, ekle / düzenle / sil, Excel), Müşteri Bazlı, Vade Takibi, DAB Bağlantıları. Kayıtlar kalıcı (App_Data/ibkb.json).", "/Ibkb", "Mali İşler › Finans › Döviz ve Dış Ticaret Finansmanı");
            Guncelleme(l, T(11, 11), "Kredi Raporu","EMLAK KATILIM YAPILANDIRMASI işlendi (Borç Ödeme Protokolü 10.11.2026; Alv Kimya, Avrupa Paper, Uras Kimya ve Alev Özavşar Eren müşterek · müteselsil borçlu, 07.10.2021 ve 12.12.2023 sözleşmeleri): KRD-001 TL kaydı 67.785.685,35 ₺ (2 peşin ödeme 10.000.000 ₺ 10.11 ve 13.11.2026 + 13 taksit 3.675.821,95 ₺, 10.12.2026 – 10.12.2027) ve KRD-002 USD kaydı 22.869,60 $ (11.434,80 $ peşin + 13 × 879,60 $; borç dökümü kuru 50,4461); yapılandırma öncesi tutarlar bankanın 11.11.2026 borç dökümünden (kalan ana para, kâr + BSMV, gecikme cezası). Kredi kaydına PARA BİRİMİ + KUR, DİĞER BORÇLULAR ve PROTOKOL ÖDEME PLANI (bankanın tarih + tutar tablosu; anüite yerine, faiz ayrımı yapılmaz; birden çok peşinat) eklendi; dövizli kredide tablolar kendi para biriminde, dip toplamlar para birimine göre, KPI ve Aylık Nakit Yükü TL karşılığıyla; Kasa Nakit Akışı satırları para birimi ve kurla yazılır. İpotek taahhüdü (Beylikdüzü Gürpınar 1499 ada 12 parsel C Blok 3. kat No 10, malik Alev Özavşar Eren, 50.000.000 ₺ limit, 20.11.2026'ya kadar tesis) kredi teminatında \"Tesis Bekliyor\" durumuyla; tapu senedi ve protokol PDF'leri Belgeler'de. BANKA BORÇ DÖKÜMÜ sekmesi ekranda çizilir oldu (önce boş kalıyordu): Firma × Döviz Özeti (ÖZET sayfası düzeni, Yapılandırma Güncel sütunu: Alv Kimya TL 59.888.848,47 / USD 22.869,60, Daf Kimya 7.896.836,88) + 50 satır; satır ekleme / düzenleme / silme; Excel iki sayfa. Özet sekmesinde yapılandırma kalemleri ve süreç takviminde protokol tarihleri. Alv Kimya ve Daf Kimya ayrı kredi kayıtları (KRD-001 Alv 59.888.848,47 ₺ · KRD-003 Daf 7.896.836,88 ₺; protokol ödemeleri pay oranında bölündü). KONKORDATO · ALACAKLI BANKALAR'a ÖDEME DURUMU sütunu (Açık / Ödendi / Yapılandırıldı; banka bildirimi, tarih, not, bağlı KRD kaydı): Emlak Katılım × Avrupa Paper ve Uras Kimya \"Ödendi\" (banka 11.11.2026: kapandı) — satırlar yeşil, bağlı sözleşme / hesap / tahsilat / mektup satırları da yeşil, bakiye toplamları açık · ödendi ayrımıyla, Özet'te banka ve şirket satırlarında ödeme rozetleri, durum filtresinde \"Ödeme · …\" seçenekleri. Emlak Katılım × Alv Kimya ve Daf Kimya listeye \"Rapor Dışı\" alacak kaydı olarak eklendi (bilirkişi raporunda yok; bankanın güncel borcu 56.938.555,20 / 7.896.836,88 ₺, Yapılandırıldı → KRD). YAPILANDIRMA ÖNCESİ: Kâr / Faiz, BSMV ve Gecikme Cezası ayrı sütun ve alan; Toplam Borç = kalan anapara + kâr + BSMV + gecikme cezası + masraf (geciken taksit tutarı bilgi). MÜHLET TARİHİ BAKİYELERİ: Daf Kimya 6003 / 6004 proje satırları (Proje Geri Ödeme Planı formları + 11.11.2026 dökümü) ve Toplam Anapara (Dosya) · Ödenen Anapara · Kalan Anapara sütunları (6003: 5.600.000 → kalan 2.992.634,83 ₺; 6004: 6.000.000 → kalan 4.170.001,94 ₺); Alv Kimya için 8 proje satırı (1021 Nakit Teminatlı 19.200.000 ₺; 6061 / 6062 / 6063 / 6066 / 6067 Hammadde İşletme Finansmanı; 6064 33.000 $ ve 6065 25.300 $ dövizli, kur 50,4461) + avukat masrafı (ek no 1021 ve 958): kalan ana para, kâr, BSMV ve gecikme cezası dökümden, toplamı KRD-001 (56.938.555,20 ₺) ve KRD-002 (24.391,92 $) ile birebir; 8 ödeme planı PDF'i Belgeler'de. Avrupa Paper'ın 1001 / 1002 / 1003 satırlarına form bilgileri (toplam anapara, gecikme oranı, komisyon, vergi, taksit) eklendi; 3 ödeme planı PDF'i Belgeler'de. Tüm sekmelerde hücreler yatay + dikey ortada; not / açıklama hücreleri 2 satır, tıklayınca tamamı. BANKA KONTROL LİSTESİ sekmesi: her banka × şirket çifti için kayıt sayıları (alacak, sözleşme, hesap satırı, teminat mektubu, tahsilat, belge, KRD, rehin / çek / döküm) kayıtlardan canlı; bilgiler tamamlandıysa OK, eksikse Eksik (notla) işareti kalıcı; sayıya tıklayınca ilgili sekme o banka × şirkete daralır. Kredi Sözleşmeleri · Kefiller'e Belgeler (PDF) sütunu (aynı banka × borçlunun sözleşme / GKS / protokol belgeleri Belgeler'den canlı) ve \"Yapılandırma Protokolü\" sözleşme türü (Emlak Katılım protokolü sözleşme sicilinde). İKİNCİ KONKORDATO DOSYASI: Bakırköy 3. ATM 2024/873 E. (Daf Kimya + ALV Filo, geçici mühlet 04.11.2024) Emlak Katılım bilirkişi raporu (11.08.2025) işlendi — Daf Kimya asaleten 10.256.849,25 ₺ adi alacak (3. şahıs ipoteği), kefaleten 136.514.480,85 ₺ nisap dışı, ALV Filo borçlu değil; 6003 / 6004 mühlet bakiyeleri, GKS kayıtları, rapor PDF'i.", "/KrediYapilandirma?sekme=konkordato", "Mali İşler › Finans › Krediler ve Finansman");
            Guncelleme(l, T(10, 11), "Kredi Raporu", "TEMİNAT MEKTUPLARI sekmesi mektubun üç tarafını açıkça gösterir: MEKTUBU VEREN BANKA (garantör; mektubu düzenleyen, tazmin sonrası alacaklı), LEHİNE VERİLEN ŞİRKET (bankanın kredi müşterisi, borçlu), MUHATAP (mektubun verildiği kurum) ve İSTİNADEN (teminat konusu / borç) sütunları; TAZMİN SONRASI ALACAK sütunu tazmin edilen bedelin bankanın hangi alacağına girdiğini gösterir (Ziraat Katılım ve Emlak Katılım'da mühlet tarihi hesap satırı, Yapı Kredi'de 12 mektup mühlet alacağına eklendi, Halkbank'ta 7 mektup rapor tarihi hesabında %74 temerrüt faiziyle). Bilirkişi raporu muhatabı ve teminat konusunu hiçbir mektupta vermez; bu hücreler \"Raporda Yok\" rozetiyle boş bırakıldı (uydurulmadı), mektup suretinden Teminat Mektubu formundaki yeni Muhatap / İstinaden alanlarına girilir. Her mektupta raporun sayfa numarası (Halkbank s. 8, Ziraat Katılım s. 13, Emlak Katılım s. 19, Yapı Kredi s. 22–23); mektup no, KKB no, veriliş ve geçerlilik raporda yoksa yine \"Raporda Yok\".", "/KrediYapilandirma?sekme=mektuplar", "Mali İşler › Finans › Krediler ve Finansman");
            Guncelleme(l, T(10, 11), "Kredi Raporu", "Teminat Çekleri tablosuna çek bazında TAHSİL EDİLEN, KALAN (tutar − tahsil edilen), ASIL BORÇLU (çekin teminat olduğu kredinin borçlusu) ve MAHSUP (alacağa mahsup / dağıtım tablosu / mahsup dışı) sütunları eklendi; dipte tutar, tahsil edilen ve kalan toplamları ile mahsup kırılımı. Bilirkişi raporundan gelen her çeke çeki veren şirket, alacaklı banka, asıl borçlu, çekin bankası, vade, valör (tahsil tarihi), tahsil tutarı, mahsup durumu ve raporun sayfa numarası işlendi; raporda bulunmayan bilgiler (151 çekte keşideci, VakıfBank çeklerinde tutar) \"Raporda Yok\" rozetiyle gösterilir, uydurulmaz. Çek formuna Tahsil Edilen, Mahsup, Asıl Borçlu ve Konkordato Alacak Kaydı alanları eklendi.", "/KrediYapilandirma?sekme=cekler", "Mali İşler › Finans › Krediler ve Finansman");
            Guncelleme(l, T(10, 11), "Kredi Raporu", "TEMİNAT ÇEKLERİ sekmesi bilirkişi raporunun çek verileriyle dolduruldu (165 kayıt): Anadolubank'ın geçici mühlet sonrası tahsil ettiği 115 müşteri çeki (çekin bankası, çek no, tutar, vade, valör; durum Tahsil Edildi) ve haricen ödenen 6 çek (keşideci, ödeme tarihi; biri karşılıksız), Kuveyt Türk şube hesabından tahsil edilen 34 çek (çeki veren şirket, çekin bankası, vade; firma payı dağıtım tablosuyla), Akbank'ın tahsil ettiği 2 çek, VakıfBank'ın 4 teminat çeki (tutar raporda yok, taksit ödemeleri notta), Yapı Kredi (3) ve Emlak Katılım (1) toplu çek bedelleri. Her çek ilgili konkordato alacak kaydına bağlı; Konkordato satırında \"n teminat çeki\" bağlantısı, dipte teminatta ve tahsil edilen toplamlar, Özet'te Teminat Çekleri kalemi.", "/KrediYapilandirma?sekme=cekler", "Mali İşler › Finans › Krediler ve Finansman");
            Guncelleme(l, T(10, 11), "Kredi Raporu", "ÖZET sekmesi eklendi ve açılış sekmesi oldu: dava dosyası şeridi; Alacaklı Bankalar Özeti (bilirkişi sonuç tablosu banka bazında birleştirilmiş: borçlu şirketler, sözleşme limiti, kat ihtarı · temerrüt sayısı, geçici mühlet nakdi alacak ve bakiye, gayrinakdi, tazmin edilen mektup, mühlet sonrası tahsilat, rapor tarihi alacağı, faiz + BSMV, rehin, alacak statüsü, durum, kefaleten alacak); Borçlu Şirketler (davacı / dava dışı, banka ve kayıt sayısı, bakiye, rapor tarihi, tahsilat, kefaleten, asıl borçlu ipoteği, kefil olduğu sözleşme, yapılandırma); Teminat · Rehin · Gayrinakdi (asıl borçlu ipoteği imtiyazlı, 3. şahıs rehni adi, diğer rehin, teminat çekleri, tazmin edilen mektuplar, çek taahhüdü, kat ihtarı depo talepleri, belgeler); Yapılandırma Durumu (öncesi → sonrası, aylık taksit yükü, önümüzdeki 3 ay, vadesi geçen, Kasa Nakit Akışı; protokol girilince dolar); Mühlet Sonrası Tahsilat Kanalları; Süreç Takvimi (dava, mühlet başlangıcı / bitişi, kat ihtarları, tahsilat aralığı, ara karar, kur tarihi, rapor tarihi). Birleşik KPI seti; satıra tıklayınca ilgili ayrıntı sekmesi filtreyle açılır; Excel altı tabloyu ayrı sayfa olarak indirir.", "/KrediYapilandirma?sekme=ozet", "Mali İşler › Finans › Krediler ve Finansman");
            Guncelleme(l, T(10, 11), "Kredi Raporu", "Örnek kayıt kaldırıldı: KRD-001 (Halkbank, ÖRNEK-2024-0001) silindi ve kalıcı dosya yokken örnek kredi üretilmesi iptal edildi; rapor yalnız gerçek veri taşır (konkordato kayıtları bilirkişi raporundan, ipotekler ve belgeler gerçek). Yapılandırma kayıtları bankayla protokol yapıldıkça Kredi Ekle ile girilecek.", "/KrediYapilandirma", "Mali İşler › Finans › Krediler ve Finansman");
            Guncelleme(l, T(10, 11), "Kredi Raporu", "KONKORDATO kümesi eklendi (Bakırköy 2. Asliye Ticaret Mahkemesi 2024/894 E. bilirkişi raporu, 19.02.2026, 62 sayfa, tüm detaylar aktarıldı): KONKORDATO · ALACAKLI BANKALAR — dava dosyası şeridi (mahkeme, dosya no, davacılar, vekil, geçici mühlet 05.11.2024, ara karar, rapor tarihi, bilirkişi, kur) ve 14 alacaklı bankanın borçlu şirket bazında alacak kayıtları (asaleten 21 + kefaleten 6): kat ihtarı (noterlik, ihtar tarihi, yevmiye no, hesap kat tarihi, istenen nakdi / depo edilecek gayrinakdi tutar, mehil), tebliğ yöntemi ve tarihi, temerrüt tarihi; geçici mühlet tarihi itibariyle nakdi alacak (ekstreye göre ve kat ihtarına itibar edilen), tazmin bedelleri, mühlet sonrası tahsilat, bakiye alacak; rapor tanzim tarihi faiz hesabı (akdi faiz → temerrüt faizi, dönem satırları tutar × gün × oran / 36000, BSMV %5), gayrinakdi çek taahhüt bedeli (yaprak × 9.270 ₺), rehin miktarı ve alacak statüsü (adi / imtiyazlı-rüçhanlı), hukuki değerlendirme; KREDİ SÖZLEŞMELERİ · KEFİLLER (GKS ve finansal kiralama sözleşmeleri, tarih, tutar / limit, müteselsil kefiller ve kefalet limitleri, davacı kefil işareti); MÜHLET TARİHİ BAKİYELERİ (141 kredi / hesap satırı: kredi no, tür, akdi faiz, anapara, döviz ve kur, faiz başlangıcı, işlemiş faiz / komisyon, BSMV + KKDF, KDV, temerrüt faizi, bakiye); MÜHLET SONRASI TAHSİLATLAR (206 kayıt: çek no, çekin bankası, vade, valör, havale, şube, mevduat rehni, teminat çeki, haricen; mahsup işareti ve firma payı dağılımı); TEMİNAT MEKTUPLARI (mektup no, KKB no, veriliş, geçerlilik, tutar, kur, tazmin tarihi ve bedeli, durum). Raporun ipotekleri Rehin · İpotek Takibi'ne tapu yevmiye no, malik türü (asıl borçlu / 3. şahıs) ve alacak statüsüyle yazıldı (Emlak Katılım 104 Mn, Yapı Kredi 102 Mn, YK Finansal Kiralama 6 Mn, Ziraat Bankası 70 Mn). Konkordato sekmelerinde KPI seti ve durum filtresi kendine özgü; alacak kaydından sözleşme / hesap / tahsilat / mektup satırlarına bağ filtresiyle geçilir; tüm kayıtlar düzenlenir, silinir, eklenir (App_Data/konkordato.json kalıcı). Bilirkişi raporunun toplama farkları (sonuç tablosu 948.854.666,04 ↔ satırlar 948.857.666,04; Anadolubank tahsilat 1,00 ₺; Ziraat Katılım 8.606.309,47 ↔ 8.636.309,47) notlarda belirtildi.", "/KrediYapilandirma?sekme=konkordato", "Mali İşler › Finans › Krediler ve Finansman");
            Guncelleme(l, T(9, 11), "Kredi Raporu", "Peşinat eklendi: yapılandırma sonrası bölümünde Peşinat ₺, Peşinat Tarihi ve Ödendi işareti. Peşinat taksitlendirilen yeni anaparanın dışındadır (\"Yeni Anaparayı Öner\" peşinatı düşer), Toplam Geri Ödeme ve Borç Farkı'na girer; Krediler ve Yapılandırma Sonrası tablolarında Peşinat sütunu, Taksit Takvimi'nde ilk satır, Aylık Nakit Yükü'nde kendi ayında yer alır. Nakit akışa aktarımda Kasa Nakit Akışı'na \"KRD-001 · Peşinat\" Havale / EFT satırı olarak yazılır (ödendi işaretliyse ÖDENDİ).", "/KrediYapilandirma", "Mali İşler › Finans › Krediler ve Finansman");
            Guncelleme(l, T(9, 11), "Kredi Raporu", "Sekme yapısı yenilendi: kredi sekmeleri (Krediler, Yapılandırma Öncesi, Yapılandırma Sonrası, Taksit Takvimi, Aylık Nakit Yükü) ve teminat · belge sekmeleri. REHİN · İPOTEK TAKİBİ: yapılandırılan kredilerin teminatları ile yapılandırma kaydı olmayan eski kredilerin ipotek / rehinleri (bağımsız kayıt: banka, eski kredi referansı, tür, tapu / kimlik bilgisi, derece, malik, tutar, ekspertiz) tek listede; tesis tarihi, durum Aktif → Fek Bekliyor → Fek Edildi / Paraya Çevrildi, fek tarihi, kredi kapanış; fek bekleyenler üstte ve kırmızı. TEMİNAT ÇEKLERİ: bankaya teminat verilen müşteri çek / senetleri (şirket, teminat verilen banka, bağlı kredi ya da GKS referansı, çek no, keşideci, çekin bankası, vade, tutar ve para birimi, veriliş tarihi, durum Teminatta / İade Alındı / Tahsil Edildi / Karşılıksız, iade tarihi); teminatta kalan toplam dipte, vadesi geçenler işaretli. BELGELER · SÖZLEŞME / GKS: taranmış kredi sözleşmesi, yapılandırma protokolü, Genel Kredi Sözleşmesi (GKS), ipotek belgesi, rehin sözleşmesi, teminat mektubu, teminat çeki fotokopisi, ödeme planı, ekspertiz raporu, fek yazısı (PDF / JPG / PNG, en çok 20 MB, birden çok dosya bir seferde); belge krediye, rehin kaydına ya da teminat çekine bağlanır, tarayıcıda açılır, indirilir, silinir. Durum filtresi sekmeye göre (kredi durumu / teminat durumu / çek durumu / belge türü); kredi satırlarında Belge · Çek sütunu ve belge yükleme (ataç) düğmesi; kredi kartındaki teminat satırlarına tesis tarihi, durum ve fek tarihi eklendi. Belgeler sunucuda App_Data/kredi-belgeler altında, tüm kayıtlar kredi-yapilandirma.json içinde kalıcı.", "/KrediYapilandirma?sekme=belgeler", "Mali İşler › Finans › Krediler ve Finansman");
            Guncelleme(l, T(9, 11), "Kasa Nakit Akışı", "Kredi Raporu'ndan gelen kredi taksitleri Havale / EFT satırı olarak akar: kurum banka, belge no \"KRD-001 · 03/36\", bağlı belge tipi Kredi Taksidi, İşlem Tipi R, planlanan tarih taksit tarihi, notta protokol ve taksit sonrası kalan anapara. Kredi / taksit başına tek satır; yapılandırma değişince ödenmemiş satır güncellenir, ödenmişe dokunulmaz; kayıt silinince ödenmemişler kaldırılır.", "/Rapor79?sekme=havale", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(9, 11), "Planlı Ödemeler", "Kredi Raporu'ndaki krediler düzenli ödeme olarak listelenir: kategori Kredi, tedarikçi banka, aylık tutar taksit, ödeme günü ilk taksit günü, bütçe kalemi Kredi Faiz ve Banka Komisyonları. Taksit satırlarını rapor yazar (aylık otomatik akış bu kayıtlarda kapalı); taksit ayları ilgili Kasa Nakit Akışı satırına bağlı görünür, takvim bitince kayıt pasife alınır.", "/Rapor123?sekme=duzenli", "Mali İşler › Finans › Ödeme Yönetimi");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "İşten Çıkış Senaryosu dip toplamı her tutar sütununda üç satır: Toplam (listelenen kişiler), Çıkacak (İşten Çıkacak işaretlilerin toplamı: kıdem / ihbar / tek seferlik çıkış maliyetinde ödenecek tutar) ve Kalan (toplam − çıkacak: aylık maliyet sütunlarında çıkışlardan sonraki durum). Ara Toplam, Toplam Brüt Masraflar, SGK İşveren, Genel Maliyet, Yıllık, Tahmini Kıdem, Tahmini İhbar ve Tek Seferlik Çıkış Maliyeti sütunlarında; Net Toplam ve Ek Ödemeler R · X · Toplam olarak kalır.", "/PersonelMaliyet?sekme=cikis", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Her sekmede tek arama kutusu: Ödeme Planı, Birleşik Tablo ve İşten Çıkış Senaryosu'ndaki ikinci kutular kaldırıldı (genel arama ad, görev, bölüm, unvan, şirket, görev yeri, sicil, cari kodu ve notta arar); Ek Çalışmalar ve Diğer Kesintiler kendi kutularıyla kalır (talep / dosya no da arar), genel arama bu sekmelerde uygulanmaz; Şirket Teşvikleri sekmesine arama eklendi. Zam Senaryosu şeridi tek satıra sığdırıldı: senaryo adı kutuda, Kaydet / Karşılaştır, R % / X %, Sıfırla (açıklamalar ipucunda).", "/PersonelMaliyet?sekme=zam", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Sekme şeritlerindeki anahtarlar ikon aldı: Üretim Personeli Gizle (fabrika), Özel Kişiler Gizle (kişi etiketi), Çoklu Satırları Birleştir (grupla) tüm sekmelerde aynı ikonla; 0 ₺ Sütunları Gizle, Ödenecek / Ödenmeyecek, Yalnız Çıkacaklar, R ve X Aynı Oran, Dövizli Gizle, SGK'lı / SGK'sız, Personel Detayını Göster ve Sütun ve Koşullar anahtarları da ikonlu.", "/PersonelMaliyet?sekme=tablo", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Personel Maliyet Tablosu'nda SGK'sız kişiler (SGK / brüt detayı olmayan gündelikçi ve bordrosuz özel kişiler) SGK İşvereni sütununda şirket adıyla değil \"SGK'sız\" işaretiyle görünür (ödeyen şirket ipucunda; Ali Mahmudov gibi). Ödeme Planı'nda banka blokeli rozeti \"R → Elden\". Dövizli maaş alan kişilerde Ödeme Planı'nda TL tutarın altında dövizli maaş × kur yazılır (Toplam Ödeme'de ve maaşın aktığı net hücresinde).", "/PersonelMaliyet?sekme=tablo", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Şirket Bazında Toplu Ödeme · Finansa Gönderim tablosunda elden ödeme ikiye ayrıldı: \"Elden Ödenecek (X)\" (gündelikçi dışı personel) ve \"Üretim Personeli (X)\" (Üretim Personeli sekmesindeki gündelikçilerin elden tutarı: SGK'sızda tamamı, SGK'lıda bordro Net-R mahsubundan kalan fark + kira). Üretim personeli ödemesi ayrı günde yapılabildiğinden kendi \"Üretim Personeli (X) Tarihi\" alanı var; Kasa Nakit Akışı'na şirket başına üçüncü bir Nakit satırı (\"Üretim Personeli Ödemesi · <dönem> · Elden (X)\") gider ve durumu tabloda ayrı sütunda izlenir. Kişi sütununda gündelikçi sayısı ayrıca yazılır.", "/PersonelMaliyet?sekme=odeme", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Kasa Nakit Akışı", "Konsolide İK Paneli'nden gelen toplu personel ödemesi artık şirket başına üç satır olabilir: Banka (R) Havale / EFT, Elden (X) Nakit ve \"Üretim Personeli Ödemesi · <dönem> · Elden (X)\" Nakit (gündelikçi ödemesi; kendi planlanan tarihiyle, nakit onayı bekler).", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(9, 11), "Kasa Nakit Akışı", "Sekme çubuğu sıkılaştırıldı: sekmeler sayfa genişliğine yayılmak yerine sola yaslı ve bitişik; adlar tam (Havale / EFT, Kredi / Banka Kartı, Talimatlar, Aylık Ödeme · Çek Vade, Banka / Kasa Bakiyesi, İşlem Günlüğü); yöntem sekmeleri ile araç sekmeleri ince çizgiyle ayrıldı; şirket · tarih aralığı · kayıt sayısı özeti çubuğun sağ ucunda. Filtre kartının başlık satırı kaldırıldı (Temizle düğmesi hızlı dönem düğmelerinin yanında), üst satır, kutular ve kart başlıkları arası boşluklar azaltıldı: tablo ekranda daha yukarıda başlar.", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(9, 11), "Kasa Nakit Akışı", "Ödeme Listesi · Tüm Yöntemler sekmesi eski görünümdeki başlıkları ayrı sütun olarak gösterir (Kaynak Firma hariç: Fatura Sahibi ile aynı bilgi olduğundan gösterilmez): Sıra, İşlem Tipi, Belge No · Belge Tipi, Belge Tarihi, Planlanan Ödeme Tarihi, Son Ödeme Tarihi, Kurum (Ödenecek Cari), Satınalmacı, Ürün / Hizmet, Fatura Sahibi, Ödeyen Şirket, PB, Anlaşılan Kur (kaynak ve kur günü altta), Tutar (belge para biriminde), Tutar (₺), Ödeme Yöntemi, Ödenme Tarihi, Toplam Ödenen, Ödenen PB, Ödeme Durumu, Mutabakat, Son Mutabakat Tarihi, Dekont (ek sayısı; tek dosya tıklanınca açılır, birden çoksa çekmecedeki Ekler bölümü), Talimat ve Not. Arama kutusu işlem tipi, satınalmacı ve mutabakat durumunda da arar. Tablo dar ekranda yatay kayar; Excel çıktısı aynı sütunlarla iner. Yöntem sekmeleri kendi özel sütunlarını korur.", "/Rapor79", "Mali İşler › Finans › Nakit Akışı ve Likidite");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Gündelikçi Üretim Personeli Maliyet Tablosu'nda Yemek, Yol ve Kira sütunları Personel Maliyet Tablosu ile aynı düzende R üstte / X altta yazılır: Kamil Mahmudov (23.520 ₺) ve Elmin Jabbarov (25.400 ₺) kirası X tarafında; SGK'lı gündelikçide bordro kaydının R ve X'i, SGK'sız gündelikçide yemek / yol / kira tamamen X. Satır formunda toplam girilir (R sabit, fazlası X).", "/PersonelMaliyet?sekme=uretim", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Menüde İnsan Kaynakları › Genel Bakış'ın ilk kaydı oldu (Personel Maliyet ve Bordro grubundan taşındı). İnsan Kaynakları alt menüsündeki tüm ekranlar (Personel Carileri, Personel Dosyası, Ekip İzin Takvimi, İzin Takip Raporu, Mesai Takip Raporu, ana sayfadaki Yaklaşan İzinler) personel listesini artık bu panelin kişi kayıtlarından alır; panelde kişi eklenince ya da değişince hepsi aynı anda değişir. ?kisi=<sıra> bağlantısı kişi kartını açar.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Genel Bakış");
            Guncelleme(l, T(9, 11), "Personel Carileri", "Özetler sekmesi personel kırılımlarına çevrildi (önce müşteri / tedarikçi carilerinin temsilci dağılımı ve sınıf matrisi görünüyordu): Şirket (SGK İşvereni), Çatı Departman ve Fiili Görev Yeri bazında aktif / işten ayrılan personel, özel kişi ve gündelikçi sayıları, telefon / e-posta eksikleri, kıdem dağılımı (1 yıldan az · 1–5 · 5–15 · 15+ · işe giriş tarihi yok). Cari Kartları sekmesindeki süzgece göre hesaplanır. Liste açılışta aktif personeli gösterir (Konsolide İK Paneli ve Personel Dosyası ile aynı sayı); işten ayrılanlar Durum süzgecinden, sayaçta aktif / ayrılan ayrımı.", "/CariKart/Personel", "İK ve İdari İşler › İnsan Kaynakları › Personel ve Organizasyon");
            Guncelleme(l, T(9, 11), "Personel Carileri", "Artık Konsolide İK Paneli kişilerinden canlı üretilen personel carilerini (335.xxx = kişi sırası) listeler: adı, SGK işvereni, görev · bölüm, fiili görev yeri, işe giriş · kıdem, telefon · e-posta, sicil · TCKN, durum (işten ayrılan pasif). Satıra tıklayınca kart ve Konsolide İK Paneli kişi kartı bağlantısı açılır; kimlik ve iletişim orada değişir, burada düzenlenmez. Önce bu menü kaydı Cari Bilgileri'ni (müşteri + tedarikçi) açıyordu; Cari Bilgileri'nde Personel Carileri tipi de aynı kişileri gösterir.", "/CariKart/Personel", "İK ve İdari İşler › İnsan Kaynakları › Personel ve Organizasyon");
            Guncelleme(l, T(9, 11), "Personel Dosyası", "Kişiler Konsolide İK Paneli'nden (her kişi için cari kodu 335.xxx); ad, şirket (SGK işvereni), bölüm, görev, işe giriş, telefon, e-posta, sicil / SGK / TC no ve durum oradan okunur. Dosyadan girilen telefon, e-posta ve işe giriş Konsolide İK Paneli'ne yazılır ve kalıcıdır (kişi kartı ve tüm sekmeler aynı anda değişir). Önceki örnek kullanıcı dosyaları (rastgele telefon, doğum tarihi, pasaport, belge) kaldırıldı; adres, pasaport, vize, belge ve eğitim bilgileri bu ekranda girilir.", "/PersonelDosya", "İK ve İdari İşler › İnsan Kaynakları › Personel ve Organizasyon");
            Guncelleme(l, T(9, 11), "Ekip İzin Takvimi", "Personel listesi, departman süzgeci ve yıllık izin bakiyeleri (işe giriş kıdemi) Konsolide İK Paneli kişilerinden; örnek izin talepleri de panel personeline bağlandı (yıllık, mazeret, ücretsiz, idari türler).", "/IkTalep/IzinTakvim", "İK ve İdari İşler › İnsan Kaynakları › İzin ve Devamlılık");
            Guncelleme(l, T(9, 11), "İzin Takip Raporu", "Personel listesi ve bakiyeler Konsolide İK Paneli kişilerinden; örnek talepler panel personeline bağlandı.", "/IkTalep/IzinTakip", "İK ve İdari İşler › İnsan Kaynakları › İzin ve Devamlılık");
            Guncelleme(l, T(9, 11), "Mesai Takip Raporu", "Personel listesi (süzgeç ve yeni talep seçimi) Konsolide İK Paneli kişilerinden; mesai talepleri zaten bordro kişilerine bağlıydı.", "/IkTalep/MesaiTakip", "İK ve İdari İşler › İnsan Kaynakları › Performans ve İş Takibi");
            Guncelleme(l, T(9, 11), "Yaklaşan İzinler", "Ana sayfadaki Yaklaşan İzinler kartı sabit örnek listeden çıktı: onaylı izin taleplerinden canlı (İzin Takip Raporu ile aynı veri; kişiler Konsolide İK Paneli'nden); satıra tıklayınca İzin Takip Raporu açılır.", "/", "İK ve İdari İşler › İnsan Kaynakları › İzin ve Devamlılık");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Gündelikçi Üretim Personeli Maliyet Tablosu ile Personel Maliyet Tablosu senkron (tek kaynak): SGK'lı gündelikçide Yemek, Yol, Kira ve Fazla Mesai artık seçili dönemin bordro kaydından gelir (R + X; R resmi bordrodan, sabit). Üretim satırından girilen yemek / yol / kira toplamı bordro kaydına yazılır (R aynen kalır, fazlası X; R'nin altına inilemez), kişi kartından yapılan değişiklik Üretim'e yansır — Kamil Mahmudov'un yolu (3.650,10 ₺) ve mesaisi (3.910 ₺) iki tabloda da aynı. Kamil Mahmudov'un günlük ücreti \"Gündelikçi Ücretleri 2026 – 20.10.2026\" Excel'inden 1.700 ₺, çalışılan gün 30 (bordro R-Net 51.000,01 = 30 × 1.700): hak ediş + yol + mesai bankadan ödenen Net-R ile birebir, elden yalnız kira 23.520 ₺. Diğer 22 gündelikçinin günlük ücreti Excel ile doğrulandı.", "/PersonelMaliyet?sekme=uretim", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(9, 11), "Konsolide İK Paneli", "Gündelikçi Üretim Personeli Maliyet Tablosu: Yemek ve Yol'un yanına Kira sütunu eklendi. SGK'lı gündelikçide kira, bordro kaydındaki Kira Desteği-X'ten gelir (Kamil Mahmudov 23.520 ₺, Elmin Jabbarov 25.400 ₺; kişi kartından değişir), R mahsubuyla netleştirilmez ve Elden Ödenecek (X)'e eklenir; SGK'sız gündelikçide satırdan girilir ve toplam hak edişe girer. Toplam Sosyal Yardımlar ve Toplam Hak Ediş kirayı içerir.", "/PersonelMaliyet?sekme=uretim", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(6, 11), "Konsolide İK Paneli", "Panel artık Personel Cari Kartı sekmesiyle açılır (menüden ve adresten; diğer sekmeler ?sekme= ile açılmaya devam eder). Personel Cari Kartı'nda Kişi Parametreleri üstte, Genel Bordro Parametreleri altta. ?sekme= derin bağlantılarına cari, tesvik ve ozelrapor eklendi (önce bu sekmelere verilen bağlantılar ana tabloya düşüyordu).", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(6, 11), "Konsolide İK Paneli", "Raporun adı \"Konsolide İK Paneli\" oldu (eski adı Personel Maliyet Raporu): sayfa başlığı, menü (İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro ile Yönetim › Özel Analizler › Özel Raporlar), Excel / PDF başlıkları ve Personel Muhasebe İşlemleri ile Yansıtma ekranlarındaki bağlantılar güncellendi; adres (/PersonelMaliyet), sekmeler ve veriler değişmedi. Özel Rapor'da SGK Durumu seçimi (Hepsi / Var / Yok) şeritten Koşullar kartına, koşul satırlarının altına sabit koşul satırı olarak alındı.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(6, 11), "Konsolide İK Paneli", "Girişler artık kalıcı: satır ve kart düzenlemeleri, personel ekleme / silme, Yeni Bordro dönemi, teşvik seçimi, üretim personeli, prim satırı, kesinti planı ve muhasebe simülasyon / işlem / eşleştirme kayıtları sunucuda günlüğe (App_Data/personel-maliyet-kayit.jsonl) yazılır ve uygulama yeniden başlayınca aynı sırayla geri yüklenir; önceden yeniden başlatmada kaybolan girişler (ör. Kira X tutarları) ve Ekim 2026 dönemi artık korunur. Tüm sekmeler aynı veriden çizildiği için bir sekmede kaydedilen tutar diğerlerine anında yansır.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(6, 11), "Konsolide İK Paneli", "Yeni sekme: Özel Rapor — sütunları ve koşulları siz belirlersiniz (ör. Genel Maliyet ≥ 80.000 ₺, Toplam Net ≥ 60.000 ₺; metin alanlarında eşittir / içerir); şeritte SGK Durumu seçimi (Hepsi / Var / Yok) ve koşullarda SGK Durumu, Kaynak (Bordro / Özel / Üretim), Özel Durumu, Durum, işveren, görev yeri gibi alanlar listeden seçilir; kapsam bordrolu + özel kişiler + SGK'sız üretim (ana filtreler geçerli), hücreler ana tabloyla aynı, dip toplam, Excel / PDF; raporlar adla kaydedilir (tarayıcıda) ve tek tıkla yeniden açılır.", "/PersonelMaliyet?sekme=ozelrapor", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(6, 11), "Konsolide İK Paneli", "23 gündelikçi üretim personelinin kimlik alanları tek düzende: Görev Üretim Personeli, Çatı Departman Üretim, Özel Durumu Gündelikçi, Departman Kodu D30, Departman Açıklaması Üretim Departmanı (Kamil Mahmudov'a özel durumu yazıldı; SGK'sız 13 gündelikçiye departman kodu ve açıklaması eklendi).", "/PersonelMaliyet?sekme=uretim", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(6, 11), "Konsolide İK Paneli", "Gündelikçi Üretim Personeli Maliyet Tablosu: şeritte \"SGK'lı\" ve \"SGK'sız\" anahtarları (ikisi açıkken tümü; biri kapatılınca yalnız diğer grup), sayaçta SGK'lı / SGK'sız kişi sayısı. Kamil Mahmudov (ALV Kimya Çorlu, bordrolu üretim personeli) SGK'lı gündelikçi olarak listeye eklendi; günlük ücreti 20.10.2026 listesinde olmadığından boş, satıra tıklayıp girilir.", "/PersonelMaliyet?sekme=uretim", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(6, 11), "Konsolide İK Paneli", "Birleşik Personel Maliyeti: Mesai'nin solunda Kira sütunu (üstte R: bordrodaki kira desteği, altta X: bordro dışı); ana tablodaki Kira Desteği de R / X oldu. Joao Paulo Araujo Fernandes'in aylık 500 € kira desteği X (bordro dışı) olarak her dönemde o dönemin kuruyla ₺ yazılır (Eylül 2026: 27.815,30 ₺; Ekim 2026: 27.826,95 ₺); Devrim / Hale Bisren'e aylık 45.000 ₺, Kamil Mahmudov'a 23.520 ₺ ve Elmin Jabbarov'a 25.400 ₺ kira X olarak yazılır. Kira X elden ödemeye ve genel maliyete girer, brüt ve SGK'ya girmez. Yeni \"Çoklu Satırları Birleştir\" anahtarı: birden fazla satırı olan kişi (Cüneyt Arda Ceylan, 4 SGK işvereni) tek satırda toplanır; tutarlar toplanır, satıra tıklayınca ilk kayıt açılır.", "/PersonelMaliyet?sekme=birlesim", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(6, 11), "Konsolide İK Paneli", "İşten Çıkış Senaryosu kendi sekmesine özel oldu: \"İşten Çıkacak\" işaretleri artık Ödeme Planı'na (pembe satır, İşten Çıkış Ödemesi kutusu ve Finans İhtiyacı'ndaki çıkış tutarı kaldırıldı; Finans İhtiyacı = bankadan + elden ödenecek) ve Özet Raporu'na yansımaz. Departman Bazında Mevcut / İşten Çıkacak / Kalan ile Departman ve Görev Bazında Kalan tabloları Özet'ten İşten Çıkış Senaryosu sekmesine taşındı (senaryo tablosunun altında; senaryonun Excel ve PDF çıktısına girer).", "/PersonelMaliyet?sekme=cikis", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(5, 11), "Konsolide İK Paneli", "Yeni sekme: Şirket Teşvik ve İndirimleri — bordro teşvikleri, destekler ve vergi istisnalarının kataloğu; her teşvik için şirket bazında \"faydalanıyor / muaf\" seçimi. Seçime göre kişi bazında Teşvik İndirimi, Teşvik Sonrası İşveren ve Genel Maliyet (Teşvik Sonrası) sütunları hesaplanır; Toplam İşveren resmi bordroyla aynı kalır.", "/PersonelMaliyet?sekme=tesvik", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(5, 11), "Konsolide İK Paneli", "Yeni sekme: Personel Cari Kartı — raporu etkileyen tüm kişi parametreleri tek listede (SGK işvereni, görev yeri, ödeme şirketleri, durum, özel durum, bloke hesap, ödeme yapılmıyor, döviz düzeni, günler, yemek istisnası, kaynak brüt / işveren / hazine). Satıra tıklayınca kartta \"Rapor Parametreleri\" bölümünden düzenlenir; genel bordro parametreleri (asgari ücret, SGK tavanı, oranlar, dilimler) üstte.", "/PersonelMaliyet?sekme=cari", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(5, 11), "Konsolide İK Paneli", "Ekim 2026 bordrosu baştan kuruldu: personel kazanç birleşik dosyasındaki R ve X tutarları, ek ödemeler ve kesintiler esas alındı. Yeni Bordro artık Ekim için bu dosyayı kullanır. Sayfa dönem seçilmeden açılınca kişi listesinin bir önceki dönemden gelmesi düzeltildi. Yeni dönemde Prim Ödemeleri ve Ek Çalışmalar satırları bordrodaki tutarlardan türetilir; Prim Uyum yalnız aynı dönemi karşılaştırır. Ekim banka ödemeleri dosyanın Kalan Net Tutar-R sütunundan icra kadar düşük (icra Eylül ile aynı); Eylül'ün \"Ödeme Yapılmıyor\" notu Ekim'e taşınmaz. Brüt, SGK işveren, hazine indirimi ve günler altı şirketin resmi Ekim bordrosundan işlendi; net ve ek kalemler kazanç dosyasından.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(5, 11), "Konsolide İK Paneli", "Zam Senaryosu şeridi tek satıra indi: Excel ve PDF düğmeleri ikon olarak en sağda; senaryo adı ve arama kutuları kısaltıldı, boşluklar daraltıldı. Ekran daralırsa şerit iki satıra geçer.", "/PersonelMaliyet?sekme=zam", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Tablo hizası tüm sekmelerde düzeltildi: başlık ile gövde aynı hizada, her hücre ortada, ilk satırlar aynı çizgide. Tutar sütunlarında ₺ işareti var; Özet kartlarındaki tutarlar da ₺ ile gösterilir. Başlıklar alta hizalı, en çok iki satır: iki satırlı başlıkta üst satır kısa, alt satır üst satırdan uzun ya da eşit; sütun genişliği başlık metnine göre ayarlandı.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Tüm sekmelerde kutucuklar (KPI) filtre çubuğunun üstünde; İşten Çıkış, Ödeme, Ek Çalışma, Diğer Kesintiler ve Muhasebe kutuları rapor başlığının altından üstteki şeride alındı. Her sekmede yalnızca o sekmenin kutuları görünür.", "/PersonelMaliyet?sekme=cikis", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Yeni Bordro: Dönem yanındaki Yeni Bordro düğmesi güncel dönemin kopyasını (Ekim 2026 gibi) oluşturur; kesinti taksitleri yeni aya göre hesaplanır, prim ve ek çalışma kalemleri kopyalanır. Banka hesabı blokeli kişilerde (Cafer İpek, Nükhet Özavşar) R tutarı icra ve kesintiler düşüldükten sonra elden ödenir: Ödeme Planı'nda banka 0, elden toplam. Maliyet tutarları değişmez.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Ekim 2026 bordrosu: dövizli maaşlar güncel EUR ve USD kuruyla hesaplanır. Joao Paulo Araujo Fernandes ve Vu Thi Thuy Ha'da R sabit tutar, kalanı X'ten ödenir; Sevgi Kaya ve Berkan Özkan'da tamamı R (banka); Orazgül Jumayeva'da tamamı X (elden). Emine Tanış ve Medine Rozykulova Ekim'de yok. Yeni Bordro düğmesi EUR ve USD kurunu sorar.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Zam Senaryosu'nda \"Dövizli gizle\" kutusu: dövizli maaşlı kişiler (Ekim 2026: Joao Paulo Araujo Fernandes, Vu Thi Thuy Ha, Orazgül Jumayeva, Sevgi Kaya, Berkan Özkan) zam tablosundan ve toplamlardan çıkar. Açık gelir; senaryoya kaydedilir.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "PDF tasarımı ekrana uyarlandı: başlıklar alt çizgide hizalı, gövde hücreleri ilk satırdan hizalı (çok satırlı hücre yanındakini kaydırmaz), grup başlıkları tek satırda; kenarlık, zemin ve renkler ekrandaki gibi.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Dönem verileri açılırken en yeni ay (yıl) otomatik seçilir ve güncel sayılır; alt toplam satırının mavi şeridi sürekli (beyaz kesikler giderildi).", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Tüm sekmelerde tutarlar virgülden sonra iki haneyle gösterilir (örnek: 9.230,79 ₺); adet, gün ve yüzde değerleri değişmez.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(4, 11), "Konsolide İK Paneli", "Arama kutusu beyaz filtre çubuğundan çıkarılıp her sekmenin yeşil şeridine taşındı (sağda); şeritte sol tarafta yalnız rapor adı görünür (büyük harf), kayıt sayısı sağda yer alır. Özet'teki açıklama satırı kaldırıldı.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Yeni(l, T(3, 11), "Konsolide İK Paneli", "Zam Senaryosu sekmesi: toplu R % ve toplu X % ayrı ayrı girilir (R ve X aynı oran kutusu ile birlikte); her kişi için R ve X ayrı oran verilebilir. Zam maaşa uygulanır (R-Net, X-Net; üretimde günlük ücret), ek ödemeler (yol, yemek, prim, fazla mesai) sabit kalır. Net Mevcut ve Net Zamlı sütunları R, X ve Toplam olarak yan yana gösterilir; Ek Ödemeler Toplam R üstte X altta; Ara Toplam, Toplam Brüt Masraflar, SGK İşveren ve Genel Maliyet mevcut ve zamlı verilir; aylık ve yıllık genel maliyet artışı Zam Özeti tablosunda (kaynak kırılımının yanında) yer alır; satıra tıklanınca açılan kişi kartında Net Zamlı X-Net tutarı (₺) elle girilir; satırdaki ve özetteki tüm değerler buna göre yeniden hesaplanır, Net Artışı yüzde olarak da gösterilir. Senaryo Kaydet ile adlandırılıp tarayıcıda saklanır; Senaryo Karşılaştırması sayfasında kayıtlar yan yana karşılaştırılır ve bir senaryo yeni sekmede açılır. Veri, bordro ve muhasebe kayıtları değişmez.", "/PersonelMaliyet?sekme=zam", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(3, 11), "Konsolide İK Paneli", "Üretim Personeli Gizle ve Özel Kişiler Gizle anahtarları Birleşik Tablo, İşten Çıkış Senaryosu, Ödeme, Özet, Ek Çalışmalar, Diğer Kesintiler ve Prim Ödemeleri sekmelerinde de; tek ortak durum olduğu için kişi sayıları ve toplamlar tüm sekmelerde uyumludur. İşten Çıkış Senaryosu'na Özel Kişiler eklendi (bordrolu, özel ve SGK'sız üretim personeli birlikte).", "/PersonelMaliyet?sekme=cikis", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(3, 11), "Konsolide İK Paneli", "Eylül 2026 verisinde bir özel kişi işten ayrıldı olarak işaretlendi (ayrılış tarihi 30.09.2026; kayıt korunur). Aktif özel kişi sayısı 8; Personel Maliyet Tablosu, Birleşik, İşten Çıkış, Ödeme, Özet, Zam ve Muhasebe toplamları buna göre güncellendi. Durum filtresi \"Tümü\" seçilince kişi görünür.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(3, 11), "Konsolide İK Paneli", "Ödeme Şirketi artık otomatik: R (bordrolu) net ödemeler her zaman Uras Power'dan, X (elden) ödemeler personelin fiili görev yeri şirketinden yapılır. Kimlik grubundaki tek sütun Ödeme Şirketi-R ve Ödeme Şirketi-X olarak ayrıldı; kişi kartında elle giriş kalktı. Muhasebe Kayıtları'nda X ödemesi SGK işvereninden farklı bir şirketten yapılıyorsa iki şirket arasında karşılıklı set oluşur (R ile aynı mantık). Üretim Personeli'nin SGK'sız 13 kişisinin SGK İşvereni çalıştıkları şirket (Uras Kimya / ALV Kimya) olarak yazıldı, Durum Aktif; tutarlar değişmedi.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(3, 11), "Konsolide İK Paneli", "Personel Maliyet Tablosu tüm kişileri gösterir: bordrolu, Özel Kişiler ve SGK'sız Üretim Personeli aynı tabloda. \"Üretim Personeli Gizle\" ve \"Özel Kişiler Gizle\" anahtarları (0 ₺ Sütunları Gizle'nin yanında) bu grupları tablodan ayırır; sayaç, dip toplam ve KPI görünen kişilere göre güncellenir. Üretim satırları X tarafıdır (hak ediş ve tatil kazancı, ek X ödemeler, genel maliyet = toplam hak ediş; Birleşik Tablo ve Özet ile aynı); düzenleme modunda değiştirilmez, satıra tıklanınca üretim düzenlemesi açılır.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(3, 11), "Konsolide İK Paneli", "Ödeme sekmesi eklendi: her kişi için ödenecek / ödenmeyecek seçimi ve Ödeme Durumu filtresi; tabloda Ödeme Özeti-R (R-Net, Ek Ödemeler Toplam-R, Kesintiler Toplamı-R, Kalan Net Tutar (Banka)) ve Ödeme Özeti-X (X-Net, Ek Ödemeler Toplam-X, Kesintiler Toplamı-X, Kalan Net Tutar (Elden)) sütunları; Toplam Ödeme = Kalan Net Tutar (Banka) + Kalan Net Tutar (Elden); ödenmeyecek satırlar gri. Net ücret sütunlarındaki yıl öneki kaldırıldı (R-Net, X-Net). R-Net anlaşılan net maaştır; Ek Ödemeler Toplam-R maaşa eklenen R ek ödemelerinin toplamıdır (Yol, Yemek, Fazla Mesai, Prim toplamı + bunların dışındaki tüm R ek ödemeler, ör. kira); banka tutarı R-Net + Ek Ödemeler Toplam-R− kesintiler olup kaynak KALAN NET TUTAR (BANKA) ile birebir eşleşir. SGK'lı gündelikçinin X-Net'i kaynakla birebir 0'dır (Ödeme Yapılmıyor); hak ediş − R mahsup bordro X'ine yazılmaz. İşten çıkacaklar İşten Çıkış Senaryosu'nda seçilir; tahmini işten çıkış ödemesi (kıdem + ihbar, İşten Çıkış Senaryosu ile aynı hesap) ayrı kartta ve Finans İhtiyacı'nda toplanır. Varsayılan: kayıtta 'Ödeme Yapılmıyor' notu olan kişi ödenmez. Seçimler tarayıcıda saklanır ve muhasebe kayıtlarını değiştirmez. Personel Maliyet Tablosu'nda üst grup başlığı (Personel Kimlik Bilgileri vb.) yalnızca kendi sütunlarının üstünde kalır; sola sabit sütunların ötesine geçmez.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(2, 11), "Konsolide İK Paneli", "Personel Maliyet Raporu 2026-09 tablosu (DUZELTILMIS_v5_2) satır satır uygulandı: 87 kişinin kimlik bilgileri, departman kodu, sicil ve SGK numarası, puantaj günleri, yemek, yol, fazla mesai, prim, kira desteği, kesintiler (avans, icra, borç, BES, özel sigorta, sendika), diğer ek ödemeler, X-Net, brüt, SGK işveren tutarı, hazine indirimi ve notları raporla aynı. Dönem Eylül 2026 tek dönemdir; Ekim ve Kasım dönemleri kaldırıldı. Prim, mesai ve kesinti planları aynı ayın (Eylül 2026) kayıtlarından okunur. Özel Kişiler sekmesinde 9 kişi: Alper Köse, Devrim / Hale Bisren, Emine Tanış, Erman Kaval, Medine Rozykulova, Murat Özavşar, Mustafa Savaş, Nükhet Özavşar, Orazgül Jumayeva. Alev Özavşar Eren bordrolu personele alındı. Brüt ve SGK bilgisi olmayan Özel kişilerde brüt ve SGK hesaplanmaz; Genel Maliyet nakit tutarıdır. Devrim / Hale Bisren satırının SGK'sı ALV Kimya, Nükhet Özavşar'ın Alv Filo olarak tutuldu. İşveren oranları raporla eşitlendi (MYO %12, KVSK %2,25); SGK tavanı 9 × asgari brüt (297.270). Yemek istisnası (7.500,22) SGK, damga ve gelir vergisi matrahından düşülür. SGK'lı gündelikçilerde elden X kuralı sürer. Üretim Personeli'nin SGK'sız 13 kişisi değişmedi. Ek Çalışmalar ve Diğer Kesintiler'de departman kodu olmayan kişinin masraf merkezi yalnız bölüm adını gösterir.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Yeni(l, T(2, 11), "Personel Muhasebe İşlemleri","İK › İnsan Kaynakları › Personel Maliyet ve Bordro altında, Personel Maliyet Yansıtması ekranının yerine: personel ile ilgili tüm muhasebe işlemlerinin ayrıntılı ekranı. Konsolide İK Paneli ›Muhasebe Kayıtları sekmesiyle aynı simülasyon verisini kullanır, burada yapılan onay / muhasebeleştirme / ters kayıt / hesap eşleştirmesi orada da anında görünür (ve tersi). Sekmeler: Muhasebe Kayıtları (personel bazlı satırlar açık, 11 kontrol, şirket fişleri, özet kayıtlar, fiş önizleme, audit, Onaya Gönder / Onayla / Muhasebeleştir / Ters Kayıt / Yeniden Simüle), Ödemeler (dönemin net ödeme listesi: banka R / kasa X, ödeyen şirket, hesap, fiş no, \"Ödeme Yapılmıyor\" notlular ayrı), Yansıtma Hazırlığı ve Yansıtma Kayıtları (eski ekranın işlevleri + simülasyon B grubu ile şirket çifti mutabakatı), Kalem Eşleme (GDR.13 ↔ YNS.13), Hesap Eşleştirme, Fiş Arşivi (tüm dönemlerin simülasyonları ve muhasebe fiş numaraları). Her personel tablosunda (muhasebe satırları, fiş önizleme, ödemeler, ödeme yapılmıyor listesi, yansıtma hazırlığı, yansıtma kayıtları ve kayıt detayı) SGK İşvereni · Fiili Görev Yeri · Ödeme Şirketi sütunları yer alır; filtre çubuğundaki aynı üç seçim tüm sekmelerdeki personel satırlarını süzer (Kalem Eşleme, Hesap Eşleştirme ve Fiş Arşivi'nde personel satırı olmadığından pasif). Dönem seçimi ortak; eski /PersonelYansitma adresi buraya yönlenir.", "/PersonelMuhasebe", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Kaldirma(l, T(2, 11), "Personel Maliyet Tablosu", "Menüden kaldırıldı (İK › İnsan Kaynakları › Personel Maliyet ve Bordro): eski tablo ekranının (Rapor57) kişileri ve maliyet kalemleri Konsolide İK Paneli'nde (eski adı Personel Maliyet Raporu) bordro kalemleri, sekmeler ve muhasebe kayıtlarıyla birlikte izlenir. Eski adres (/Rapor57) oraya yönlenir. Menüde adı \"(Kaldırıldı)\" rozetiyle durur.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Kaldirma(l, T(2, 11), "Personel Maliyet Yansıtması", "Personel Muhasebe İşlemleri ekranına dönüştü (adı değişti, kapsamı genişledi): yansıtma hazırlığı, yansıtma kayıtları ve kalem eşleme orada sekme olarak sürer; eski adres oraya yönlenir. Menüde adı \"(Kaldırıldı)\" rozetiyle durur.", "/PersonelMuhasebe?sekme=hazirlik", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Yeni(l, T(25, 9), "Personel Maliyet Yansıtması", "İK › İnsan Kaynakları › Personel Maliyet ve Bordro altında: personel cari kartında SGK İşvereni ile Fiili Görev Yeri farklı olan çalışanların aylık maliyeti, bordro dönemi seçilince otomatik bulunur ve SGK işvereni şirketten fiili görev yeri şirkete yansıtılır. Kalemler Gider Kataloğu 13 Personel ve İşçilik Giderleri (GDR.13.AA.KK) ile bire bir yansıtma gelir kalemine (YNS.13.AA.KK) eşlenir. \"Seçilenleri Yansıt\" tek adımda iki şirkete birden kayıt atar (kaynakta 120 cari / 649 yansıtma geliri, hedefte 770 personel gideri / 320 cari). Çok şirketli görev yerinde pay dağılımı, kayıt listesi ve kaynak → hedef matrisi, iki taraflı fiş detayı, Fatura Oluştur / İptal, Kalem Eşleme ve KDV parametresi, Excel.", "/PersonelYansitma", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(1, 11), "Konsolide İK Paneli", "Kişi ve rakamlar \"Güncel Eksiksiz 01.11.2026\" tablosundan yerleştirildi: 86 personel satırı (yeni: yönetim özel, yurtdışı şube, gündelikçi üretim personeli, Avrupa Paper ve Alv Filo SGK işverenleri; aynı kişi farklı işverenlerde ayrı satır). R bordrolu ücret, X bordro dışı ödeme olarak düzeltildi: BAZ R MAAŞ → R-Net, YOL-YEMEK-KİRA → Yemek / Yol, MESAİ → Fazla Mesai, BAZ X MAAŞ → X-Net, X tarafı yol-yemek / mesai / prim → Diğer Ek Ödemeler-X (kırılımı Not'ta), KESİNTİLER TOPLAMI → Borç, \"Ödeme Yapılmıyor\" → Not. Toplam Brüt Maliyet ve İş Veren tutarları satıra bağlı: brüt kazanç, SGK işveren ve genel maliyet kaynak tabloyla birebir; vergi ve SGK işçi kalemleri bu tutarlarla tutarlı türetilir, satır düzenlenince model yeniden hesaplar. Özel Durumu listesine Gündelikçi eklendi; KPI ve özet kalemleri R / X ayrımına göre. Maliyet ve Not grubu sadeleşti: Net-X Bordro (bordro dışı ödenen toplam), Net-R Bordro (tüm ekler dahil, kesintiler düşülmüş, bankadan yatacak net), Ara Toplam, Toplam Brüt Masraflar, Toplam İşveren, Genel Maliyet, Not; tekrar sütunu Diğer Ek Ödemeler-R 2 kaldırıldı. Ödeme Özeti grubu dört sütuna indi: R-Net, Diğer Ek Ödemeler-R, Kesintiler Toplamı, Kalan Net Tutar (Banka); Diğer Ek Ödemeler-X sütunu kaldırıldı; hem R hem X tarafı olan kalemler (Yemek, Yol, Fazla Mesai, Prim) tek sütunda altlı üstlü gösterilir: üstte R (bordrolu), altta X (bordro dışı, yalnız Net-X Bordro'ya eklenir); düzenlemede ve kartta R / X ayrı girilir, Excel'de iki sütun olur. Bu grupların toplamları -R / -X olarak ayrıldı (Toplam Ek Çalışma, Toplam Sosyal Yardımlar, Toplam Prim). Tüm tutarlar ₺ işaretiyle. Ödeme Özeti ikiye bölündü: Ödeme Özeti-R (R-Net, Diğer Ek Ödemeler-R, Kesintiler Toplamı-R, Kalan Net Tutar (Banka)) ve hemen sağında Ödeme Özeti-X (X-Net, Diğer Ek Ödemeler-X, Kesintiler Toplamı-X, Kalan Net Tutar (Elden)). Dövizli maaş: kartta Para Birimi (USD / EUR / GBP), Döviz Tutarı ve Kur girilince X-Net ₺ karşılığıyla dolar, tabloda kur notu görünür. \"0 ₺ Sütunları Gizle\" anahtarı tamamı sıfır olan sütunları kaldırır. Dört yeni sekme: Üretim Personeli (SGK'sız, tamamen X, saat / gün bazlı: saat ücreti × çalışılan gün × 7,5, fazla mesai ×1,5, tatil ×2, yemek / yol / sosyal yardım, avans-kesinti, net ödenen), Prim Ödemeleri (ciro / tahsilat / hedef primi ve özel ödemeler dönem bazında; kişi toplamı ana tablodaki Prim-X ile karşılaştırılır), Özel Kişiler (Alev Özavşar Eren, Murat ve Nükhet Özavşar, Devrim / Hale Bisren, Mustafa Savaş, Erman Kaval, Medine Rozykulova, Orazgül Jumayeva: Personel Maliyet Tablosu'ndan çıkarılıp aynı sütun, düzenleme ve kart yapısıyla ayrı sekmede izlenir) ve Birleşik Tablo (Bordro + Üretim + Özel; R-Net, X-Net, yol, yemek, mesai, prim, diğer ek ödemeler, kesintiler, net ödenen, Toplam Brüt Masraflar, Toplam İşveren, Genel Maliyet — brüt kalemler açılmaz). Filtrelere Dönem (Ay) seçimi eklendi: seçilen ayın bordro verisi yüklenir (Kasım 2026 kaynak tablodan; Ekim ve Eylül 2026 türetilmiş örnek dönem), düzenleme ve kart kayıtları seçili döneme işlenir; derin bağlantı ?donem=2026-10. İki yeni sekme: Ek Çalışmalar (İK Mesai Talebi modülünden dinamik: kim mesai yapmış, kim onaylamış, ne zaman, PDKS gerçekleşmesi, puantaj aktarımı, taleplerden hesaplanan tutar ↔ tablodaki Fazla Mesai farkı, talep detayı çekmecesi) ve Diğer Kesintiler (şahsi avans talepleri ve kasa ödemeleri, Kasa Nakit Akışı senkron satırı, avans mahsubu / icra / borç planları: toplam, aylık taksit, ödenen / kalan, bitiş dönemi, PDF ekleri; \"Kesinti / İcra Ekle\" formu plan açar, PDF yükler ve kişinin bordrosundaki kesinti sütununa yansıtır). Bordrolu personel talep modüllerinde tanınır (Yönetici onayı bölüm müdürü, Direktör GMY, İK Bordro ve Özlük). Muhasebe Kayıtları sekmesi (IT Analiz 01.11.2026): kayıtlar doğrudan atılmaz — Simülasyon Oluştur atılacak tüm fişleri şirket, hesap, borç / alacak, X/R, tutar ve açıklama bazında önizler (A Bordro Tahakkuku, B Fiili Görev Yeri Yansıtması, C Net Personel Ödemesi, D Başka Şirket Tarafından Ödeme), 11 kontrol çalışır (fiş dengesi, şirket-hesap uyumu, posting hesabı, X/R ve genel maliyet mutabakatı, yansıtma, ödeme şirketi, mükerrer, dönem, açıklama standardı, \"Ödeme Yapılmıyor\" istisnası), kritik hata varken Onayla kapalı; Onaya Gönder → Onayla (yetki) → Muhasebeleştir gerçek yevmiye fişlerini oluşturur ve fiş numaralarını yazar; Ters Kayıt referanslı ters fiş atar. Hesap Eşleştirme tanım ekranı (şirket + işlem türü + kaynak kalem + X/R + yön → hesap, geçerlilik, aktif), kaynak veri değişince simülasyon \"Güncelliğini Yitirdi\", audit log, fiş önizleme. Personel Kimlik Bilgileri grubuna Ödeme Şirketi sütunu eklendi. Simülasyon ekran açılınca otomatik oluşur (düğme kaldırıldı); bilgi gizliliği için varsayılan görünüm personel adı içermeyen özet simülasyondur (hesap + X/R + karşı şirket bazında toplam) ve muhasebeye kayıtlar bu genel hâliyle atılır, personel bazlı satırlar \"Personel Detayını Göster\" ile açılır. R (banka) net ödemelerinin tamamı varsayılan olarak Uras Power'dan yapılır, X (elden) ödemesi SGK işvereni kasasından. Cüneyt Arda Ceylan'ın üç işverendeki satırı tek satırda toplandı (R-Net 58.333,35 · Brüt Masraflar 24.554,82 · İş Veren 19.685,93); personel 84. Tüm sekmelerde satıra tıklayınca düzenleme çekmecesi: prim satırı (dönem, personel, tür, baz, oran %, sabit tutar, R/X; kaydedilince kişinin ilgili bordro dönemindeki Prim-X / Prim-R prim satırlarının toplamından yeniden yazılır, kartı ve carisi güncellenir), üretim personeli (ekle / düzenle / sil, Birleşik Tablo'ya yansır), kesinti / icra planı (toplam, taksit, ödenen, başlangıç; bordro kesinti sütunu plan toplamına eşitlenir); Birleşik Tablo satırı kişinin kartını açar; mesai ve avans detayında Personel Kartı düğmesi. Üretim Personeli sekmesi \"Gündelikçi Üretim Personeli Maliyet Tablosu\" oldu: \"Gündelikçi Ücretleri 2026 – 20.10.2026\" listesinden 22 kişi (Uras Kimya 17, Alv Kimya Çorlu 5) günlük ücretleriyle; hak ediş = günlük ücret × gün, mesai ×1,5, tatil ×2. SGK'lı dokuz gündelikçi (Aslan Huseynov, Azad Shirinov, Elman Abbaslı, Elmin Jabbarov, Mehman Babayev, Murad Hudaybergenov, Rahman Babazade, Ramin Musayev, Tural Abbasov) Personel Maliyet Tablosu'na bağlandı: bordro Net-R mahsup edilir, kalan fark elden nakit X olarak kişinin X-Net'ine otomatik yazılır, R kısımları aynen kalır; SGK'sız gündelikçiler tamamı X olarak Birleşik Tablo'ya girer. Emekli (E) ve engelli (♿) rozetleri tüm sekmelerdeki ad hücrelerinde. Birleşik Tablo'ya Net Toplam sütunu; Diğer Ek Ödemeler yalnız dolu dönemlerde görünür. Yeni \"İşten Çıkış Senaryosu\" sekmesi: Birleşik Tablo satırlarında kişiler işaretlenir, mevcut / çıkacak / kalan aylık genel maliyet, yıllık tasarruf, tahmini kıdem (min(brüt, kıdem tavanı) × kıdem yılı) ve ihbar (haftalık brüt × ihbar haftası) ile tek seferlik çıkış maliyeti ve geri dönüş süresi hesaplanır; veri değişmez, işaretler tarayıcıda saklanır. Özet Raporu artık tüm maliyetleri kapsar (bordrolu + özel kişiler + SGK'sız gündelikçiler), Kaynak kırılımı ve Kaynak Dağılımı kartı eklendi; kırılım tablosunda Ek Çalışma / Sosyal Yardım / Prim R üstte X altta, Top. Ek Ödemeler ve Toplam Kesintiler sütunları. Rapor tamamen tıklanabilir: ana tablo, kişi özetleri ve senaryo satırları kartı; mesai / avans satırları talep detayını; muhasebe özet ve fiş satırları fiş önizlemesini; özet raporu kırılım, matris ve dağılım satırları ilgili filtreyi uygulayıp tabloya döner. Ek Çalışmalar ve Diğer Kesintiler listeleri üstteki ortak filtrelerle senkron. Tüm sekmelerde tablo başlıkları (grup ve sütun satırı) ile dip toplam donduruldu; Sıra'dan Adı-Soyadı'na kadar olan sütunlar yatay kaydırmada sola sabit; tablolar kendi kaydırma kabında (section) kayar, sayfa uzamaz. İşten Çıkış Senaryosu: Ek Ödemeler ve Kesintiler sütunları eklendi (Net Toplam + Ek Ödemeler − Kesintiler = Net Ödenen; Net Ödenen + Kesintiler + Toplam Brüt Masraflar + Toplam İşveren = Aylık Genel Maliyet), dip toplamda her sütunun altında kendi toplamı (Net Toplam dahil), rakamlar Birleşik Tablo'nun Özel Kişiler hariç haliyle birebir. Yoğun yerleşim: KPI kutuları Personel Maliyet Yansıtması ile aynı ölçüde, kendi KPI şeridi olan sekmelerde genel şerit gizlenir; filtreler tek satırlık çubuk; sekme başlık şeridi inceltildi, başlık beyaz (okunmuyordu), alt açıklama başlığın ipucunda; rapor açıklaması \"i\" düğmesiyle açılır; tek tablolu sekmelerde tablo ekranın kalanını doldurur. Personel Maliyet Tablosu sekmesinde şerit başlığı kaldırıldı (sekme adıyla aynıydı), şeritte yalnız kapsam · dönem sayacı. Muhasebe Kayıtları sekmesine \"Personel Muhasebe İşlemleri\" bağlantısı eklendi: ayrıntılı işlemler (personel bazlı satırlar, ödemeler, yansıtma, fiş arşivi) o ekranda, aynı veriyle senkron; sekmeye her girişte veri tazelenir. Sekme sırası: Personel Maliyet Tablosu › Ek Çalışmalar › Diğer Kesintiler › Prim Ödemeleri › Üretim Personeli › Özel Kişiler › Birleşik Tablo › İşten Çıkış Senaryosu › Özet Raporu › Muhasebe Kayıtları.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Guncelleme(l, T(1, 11), "Konsolide İK Paneli", "Tablo \"Personel Bordro ve Ödeme Tablosu\" düzenine geçti (tasarım aynı, içerik yeni): 16 sütun grubu — Personel Kimlik Bilgileri (departman kodu / açıklaması, sicil ve SGK numarası eklendi), Net Ücret (X-Net, R-Net, Toplam Net), Puantaj ve Çalışma Kazançları (prim gün; normal çalışma, hafta sonu, resmî tatil, bayram, ücretli izin gün ve kazançları), Ek Çalışmalar (fazla mesai, bayram, gece farkı, pazar, resmi tatil), Sosyal Yardımlar (+ çocuk yardımı), Prim ve Ek Kazançlar (maaş farkı, prim, özel ödeme), Yan Haklar (özel sağlık, kıyafet, koruyucu ekipman, doğum, evlilik), Yasal Ödemeler (kıdem, ihbar, işe iade, yıllık izin, rapor farkı, doğum izni), Brüt Kazanç ve SGK Matrahı, Gelir Vergisi (matrah, kümülatif, hesaplanan, asgari ücret istisnası, indirimler, tutar), Damga Vergisi, SGK İşçi Payları, İşveren Payları (işsizlik, MYÖ, GSS, SGDP, KVSK, hazine indirimi), Diğer Kesintiler (avans, icra, borç, özel sigorta, sendika, BES), Ödeme Özeti (kesintiler toplamı, bankaya kalan net) ve Maliyet ve Not (Toplam Net-X / Net-R, diğer ek ödemeler, ara toplam, toplam brüt masraflar, toplam işveren, genel maliyet). Girilen alanlar sarı, hesaplanan sütunlar gri zeminli; brüt ücret X-Net'ten brütleştirilir, vergi ve SGK payları 2026 parametreleriyle (asgari ücret, tavan, dilimler, SGDP) satır bazında hesaplanır ve düzenlerken anında yenilenir. Kart çekmecesinde tüm bordro kalemleri grup başlıklarıyla; özet raporu ve Excel yeni kalemlerle. Personel Maliyet Yansıtması kalem eşlemesi yeni alanlara (toplam brüt masraflar, SGK işveren toplam prim, çocuk yardımı, maaş farkı) bağlandı.", "/PersonelMaliyet", "İK ve İdari İşler › İnsan Kaynakları › Personel Maliyet ve Bordro");
            Yeni(l, T(22, 9), "Konsolide İK Paneli", "Yönetim › Özel Raporlar altında \"PERSONEL 19.06 GÜNCEL\" tablosunun portal karşılığı: personel kimlik bilgileri (SGK işvereni, fiili görev yeri, ünvan, bölüm, görev, işe giriş, kıdem, çatı departman, özel durum) ve aylık maliyet kalemleri — brüt ücret (X-Net, R-Net, brüt ücret masrafları), işveren payı, ek çalışma, sosyal yardımlar (yemek, yol, servis, kira desteği, eğitim), prim (satış primi, özel ödeme), yan haklar, yasal ödemeler ve genel maliyet; toplamlar otomatik. Filtreler, KPI kutuları, çatı departman / SGK işvereni / görev yeri / ünvan özetleri, satır bazında düzenleme ve kaydetme, Excel.", "/PersonelMaliyet", "Yönetim › Özel Analizler › Özel Raporlar");
            Yeni(l, T(22, 9), "Yapılan Ödemeler", "Yönetim › Özel Raporlar altında tüm grup şirketlerinin yaptığı ödemelerin konsolide listesi: Banka (Havale / EFT), Çek (vadeli çekler; Ödendi / Vade Bekliyor), Nakit (Kasa) çıkışları ve Nakit Avans teslimleri. Kaynaklar: ERP banka / kasa, çek bordrosu, Nakit Avans modülü ve Aylık Alım Onay'daki ödenmiş tedarikçi faturaları. Dönem, şirket, ödeme türü, kategori, alıcı tipi, para birimi, durum ve kaynak filtreleri; KPI kutuları; Şirket × Ödeme Türü ve Ay × Ödeme Türü matrisleri; kategori dağılımı; en büyük 10 alıcı; satır detayından kaynak belgeye geçiş; Excel.", "/YapilanOdemeler", "Yönetim › Özel Analizler › Özel Raporlar");
            Yeni(l, T(21, 9), "Genel Analiz Raporu", "Yönetim › Özel Raporlar altında, \"2026 Aylık Analiz Raporu\" Excel şablonuyla aynı düzende: Ciro (şirket alt toplamları), Alımlar, Giderler, Ara Sonuç, Amortisman, Kur Farkı ve Sonuç satırları; 12 ay + Toplam + Aylık Ort.; yazılabilir hücreler, otomatik alt toplam, kaydet ve Excel (CSV) çıktısı.");
            Yeni(l, T(21, 9), "Aylık Alım Onay Ekranı", "Muhasebe'nin hazırladığı aylık alım raporu (tedarikçi faturaları, kalem detayı ve fatura görüntüsü); satınalmacı ve Tedarik Zinciri Direktörü ay sonu onayı, uyarılar, ay kapanışı. Tedarik Zinciri ve Muhasebe menülerinde.", "/Modul/tedarik-zinciri?yol=satin-alma/fiyat-alim-analizi/r0", "Tedarik Zinciri › Satın Alma › Fiyat ve Alım Analizi");
            Yeni(l, T(20, 9), "Grup İçi Özel Finansal İşlemler Raporu", "Yansıtma, Mahsup ve Temlik işlemlerinin birleşik listesi; şirket bazında açık tutarlar ve ERP grup içi bakiye tablosu.");
            Yeni(l, T(20, 9), "Temlik İşlemleri", "Alacağın grup şirketine devri: Muhasebe → Hukuk → Finans onayı, sözleşme, borçluya bildirim, tahsilat ve kapanış.", "/Modul/mali-isler?yol=grup-ici-ozel/r2", "Mali İşler › Grup İçi Özel Finansal İşlemler");   // aynı ad Muhasebe'de de var (Rapor121); adres elle
            Yeni(l, T(20, 9), "Mahsup İşlemleri", "ERP cari bakiyeleriyle sınırlı karşılıklı / üçlü / avans / fatura mahsubu; A-B fişleri ve mutabakat.");
            Yeni(l, T(19, 9), "Yansıtma İşlemleri", "Şirketler arası masraf, hizmet, personel ve kira yansıtması; KDV hesabı, e-fatura ve karşı kabul akışı.");
            Yeni(l, T(18, 9), "Araç Talebi", "Filo master, ehliyet ve ceza puanı kontrolü, müsaitlik, tahsis → anahtar teslim → iade → HGS/ceza → kapanış.");
            Yeni(l, T(18, 9), "Seyahat Talebi", "Gün / gece, parametrik harcırah, bütçe eşiğinde Direktör onayı, bilet / otel / avans / masraf formu.");
            Yeni(l, T(18, 9), "Belge Talebi", "SLA hedefli belge hazırlama: hazırlık → imza → belge no → teslim → teyit; KVKK rızası ve kargo adresi.");
            Yeni(l, T(18, 9), "Mesai Talebi", "Planlanan saat, çarpan, 270 saat yıllık sınır, PDKS gerçekleşme ve bordro puantajı.");
            Yeni(l, T(18, 9), "Mesai Takip Raporu", "Mesai taleplerinin onay, gerçekleşme ve puantaj durumu.");
            Yeni(l, T(17, 9), "İzin Talebi", "İzin türü master'ı, kıdeme göre hak ediş, iş günü hesabı, çakışma / vekil kontrolleri ve parametrik onay akışı.");
            Yeni(l, T(17, 9), "Ekip İzin Takvimi", "Ekip bazında planlanan ve onaylanan izinlerin aylık takvim görünümü.");
            Yeni(l, T(17, 9), "İzin Takip Raporu", "İzin taleplerinin talep / kullanım / puantaj statüleriyle takibi.");
            Yeni(l, T(16, 9), "Avans Talebi", "Nakit Avans Talep, Ödeme, Mahsup ve Kapatma Modülü (şartname v1.0): gösterge kutucukları, onay akışı ve kaynak sistem olayları.");
            Yeni(l, T(16, 9), "Nakit Avans — Bekleyen Ödemeler", "Finans için teslim bekleyen avansların listesi ve teslim teyidi.");
            Yeni(l, T(16, 9), "Nakit Avans Takip Raporu", "Açık = Teslim − Mahsup − İade özetiyle tüm avansların takibi.");

            // --- Taşıma, güncelleme, kaldırma ---
            Yeni(l, T(22, 9), "Müşteri Cari Kartları", "\"Cari Kart ve Faaliyet Eşleştirme Yapısı\" IT raporuna göre: CARİ_MASTER listesi (kod, ünvan, VKN, tip, bölge / ülke / şehir, sınıf, ilişki durumu, rol / eş cari, vade, durum), faaliyet grubu bazında satış temsilcisi, detay drawer'ında CARİ_FAALİYET satırları ve ürün hiyerarşisi; tip / bölge / sınıf matrisi.", "/CariKart/Musteri", "Satış ve Operasyon › Müşteri ve CRM Yönetimi › Müşteri Portföyü");
            Yeni(l, T(22, 9), "Müşteri Talep Formu", "Cari kart açılış talebi: CARİ_MASTER alanları bağımlı seçimlerle (kart tipi → bölge → ülke → şehir, tip + bölge → cari sınıfı, ilişki durumu, rol, çift rolde eş cari kodu), CARİ_FAALİYET satırları (faaliyet ana grubu → grubu → satış temsilcisi, ana faaliyet, ürün sınıfı › grubu › serisi › adı), canlı validasyon, Muhasebe onayı sonrası kart otomatik açılır.", "/CariKart/MusteriTalep", "Talep › Yeni Talep › Müşteri");
